{
  "name": "Laporan Keuangan PHBI Maulid 1448H",
  "description": "Sistem Informasi Manajemen Keuangan Masjid Jami' Al-Ishlah untuk Maulid Nabi Muhammad SAW 1448 H | 2026 M"
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface PreviousFund {
  id: string;
  date: string;
  nominal: number;
}

export interface WeeklyData {
  id: string;
  date: string;
  week: string;
  rt: string;
  grossAmount: number; // Pendapatan Kotor
  consumptionCut: number; // 5%
  commissionCut: number; // 10%
  netAmount: number; // Jumlah Bersih masuk kas
}

export interface DonorData {
  id: string;
  date: string;
  name: string;
  source: string; // Sumber Dana
  nominal: number;
}

export interface ExpenseData {
  id: string;
  date: string;
  purpose: string; // Keperluan
  nominal: number;
}

export interface AppData {
  previousFunds: PreviousFund[];
  weeklyData: WeeklyData[];
  donors: DonorData[];
  expenses: ExpenseData[];
}

export type DataType = 'previous' | 'weekly' | 'donor' | 'expense';

export const formatCurrency = (amount: number): string => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency',
    currency: 'IDR',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(amount);
};

export const formatDate = (dateString: string): string => {
  if (!dateString) return '-';
  const options: Intl.DateTimeFormatOptions = { day: 'numeric', month: 'long', year: 'numeric' };
  return new Date(dateString).toLocaleDateString('id-ID', options);
};

export const calculateWeeklyCuts = (gross: number) => {
  const consumption = gross * 0.05;
  const commission = gross * 0.10;
  const net = gross - consumption - commission;
  return { consumption, commission, net };
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppData, PreviousFund, WeeklyData, DonorData, ExpenseData } from '../types';
import Swal from 'sweetalert2';

interface DataContextType {
  publishedData: AppData;
  stagedData: AppData; // Admin working copy
  isLoggedIn: boolean;
  login: () => void;
  logout: () => void;
  // CRUD Actions (Effect Staged Data)
  addPreviousFund: (data: Omit<PreviousFund, 'id'>) => void;
  deletePreviousFund: (id: string) => void;
  addWeeklyData: (data: Omit<WeeklyData, 'id'>) => void;
  deleteWeeklyData: (id: string) => void;
  addDonor: (data: Omit<DonorData, 'id'>) => void;
  deleteDonor: (id: string) => void;
  addExpense: (data: Omit<ExpenseData, 'id'>) => void;
  deleteExpense: (id: string) => void;
  // System Actions
  publishData: () => void;
  resetData: (type: 'all' | 'previous' | 'weekly' | 'donor' | 'expense') => void;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

const initialData: AppData = {
  previousFunds: [],
  weeklyData: [],
  donors: [],
  expenses: [],
};

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [publishedData, setPublishedData] = useState<AppData>(initialData);
  const [stagedData, setStagedData] = useState<AppData>(initialData);
  const [isLoggedIn, setIsLoggedIn] = useState(false);

  // Load initial data from localStorage (Simulating Supabase fetch)
  useEffect(() => {
    const storedPublished = localStorage.getItem('phbi_published_data');
    const storedStaged = localStorage.getItem('phbi_staged_data');

    if (storedPublished) setPublishedData(JSON.parse(storedPublished));
    if (storedStaged) setStagedData(JSON.parse(storedStaged));

    // Auto-sync staged with published if empty (first run)
    if (!storedStaged && storedPublished) {
       setStagedData(JSON.parse(storedPublished));
    }
  }, []);

  // Persist Staged Data whenever it changes
  useEffect(() => {
    localStorage.setItem('phbi_staged_data', JSON.stringify(stagedData));
  }, [stagedData]);

  // Persist Published Data
  useEffect(() => {
    localStorage.setItem('phbi_published_data', JSON.stringify(publishedData));
  }, [publishedData]);

  const login = () => setIsLoggedIn(true);
  const logout = () => setIsLoggedIn(false);

  // --- CRUD Operations (Operate on Staged Data) ---

  const addPreviousFund = (item: Omit<PreviousFund, 'id'>) => {
    const newItem = { ...item, id: crypto.randomUUID() };
    setStagedData(prev => ({ ...prev, previousFunds: [...prev.previousFunds, newItem] }));
  };
  const deletePreviousFund = (id: string) => {
    setStagedData(prev => ({ ...prev, previousFunds: prev.previousFunds.filter(i => i.id !== id) }));
  };

  const addWeeklyData = (item: Omit<WeeklyData, 'id'>) => {
    const newItem = { ...item, id: crypto.randomUUID() };
    setStagedData(prev => ({ ...prev, weeklyData: [...prev.weeklyData, newItem] }));
  };
  const deleteWeeklyData = (id: string) => {
    setStagedData(prev => ({ ...prev, weeklyData: prev.weeklyData.filter(i => i.id !== id) }));
  };

  const addDonor = (item: Omit<DonorData, 'id'>) => {
    const newItem = { ...item, id: crypto.randomUUID() };
    setStagedData(prev => ({ ...prev, donors: [...prev.donors, newItem] }));
  };
  const deleteDonor = (id: string) => {
    setStagedData(prev => ({ ...prev, donors: prev.donors.filter(i => i.id !== id) }));
  };

  const addExpense = (item: Omit<ExpenseData, 'id'>) => {
    const newItem = { ...item, id: crypto.randomUUID() };
    setStagedData(prev => ({ ...prev, expenses: [...prev.expenses, newItem] }));
  };
  const deleteExpense = (id: string) => {
    setStagedData(prev => ({ ...prev, expenses: prev.expenses.filter(i => i.id !== id) }));
  };

  // --- System Actions ---

  const publishData = () => {
    setPublishedData(stagedData);
    Swal.fire({
      icon: 'success',
      title: 'Data Dipublikasikan',
      text: 'Semua data yang diinput telah disimpan ke database publik (Supabase Mock).',
      confirmButtonColor: '#047857'
    });
  };

  const resetData = (type: 'all' | 'previous' | 'weekly' | 'donor' | 'expense') => {
    if (type === 'all') {
      setStagedData(initialData);
      setPublishedData(initialData);
    } else {
      const keyMap: Record<string, keyof AppData> = {
        'previous': 'previousFunds',
        'weekly': 'weeklyData',
        'donor': 'donors',
        'expense': 'expenses'
      };
      const key = keyMap[type];
      setStagedData(prev => ({ ...prev, [key]: [] }));
      // Note: Resetting staged implies we might want to publish this empty state later, 
      // but for "Reset" usually it clears everything immediately including DB.
      // Based on prompt: "Data di kolom tabel supabase akan Hilang SEMUANYA juga".
      setPublishedData(prev => ({ ...prev, [key]: [] }));
    }
  };

  return (
    <DataContext.Provider value={{
      publishedData,
      stagedData,
      isLoggedIn,
      login,
      logout,
      addPreviousFund,
      deletePreviousFund,
      addWeeklyData,
      deleteWeeklyData,
      addDonor,
      deleteDonor,
      addExpense,
      deleteExpense,
      publishData,
      resetData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

