import React from 'react';
import { ArrowUpCircle, ArrowDownCircle, Wallet, Info } from 'lucide-react';
import { formatCurrency } from '../utils/format';

interface SummaryCardProps {
  title: string;
  amount: number;
  type: 'income' | 'expense' | 'balance';
  onDetailClick?: () => void;
}

const SummaryCard: React.FC<SummaryCardProps> = ({ title, amount, type, onDetailClick }) => {
  const getIcon = () => {
    switch (type) {
      case 'income': return <ArrowUpCircle className="w-8 h-8 text-emerald-600" />;
      case 'expense': return <ArrowDownCircle className="w-8 h-8 text-red-600" />;
      default: return <Wallet className="w-8 h-8 text-blue-600" />;
    }
  };

  const getBgColor = () => {
    switch (type) {
      case 'income': return 'bg-emerald-50 border-emerald-200';
      case 'expense': return 'bg-red-50 border-red-200';
      default: return 'bg-blue-50 border-blue-200';
    }
  };

  return (
    <div className={`rounded-xl p-6 shadow-md border ${getBgColor()} relative transition hover:shadow-lg`}>
      <div className="flex justify-between items-start">
        <div>
          <p className="text-gray-500 text-sm font-semibold uppercase tracking-wider">{title}</p>
          <h3 className="text-2xl md:text-3xl font-bold mt-2 text-gray-800">{formatCurrency(amount)}</h3>
        </div>
        {getIcon()}
      </div>
      {onDetailClick && (
        <button 
          onClick={onDetailClick}
          className="absolute bottom-4 right-4 text-xs font-semibold text-gray-500 hover:text-primary flex items-center gap-1"
        >
          <Info className="w-4 h-4" /> Detail
        </button>
      )}
    </div>
  );
};

export default SummaryCard;

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { AppData } from '../types';
import { formatCurrency, formatDate } from './format';

export const generatePDF = (data: AppData, type: 'weekly' | 'donor' | 'expense' | 'all_income' | 'all_expense') => {
  const doc = new jsPDF();
  const titleStyle = { fontSize: 16, fontStyle: 'bold' as const, align: 'center' as const };
  const subTitleStyle = { fontSize: 10, align: 'center' as const };

  const addHeader = (title: string) => {
    doc.setFontSize(14);
    doc.text("MASJID JAMI' AL-ISHLAH", 105, 15, { align: 'center' });
    doc.setFontSize(10);
    doc.text("Kp. Teriti Rw. 04 Desa Karet Kec. Sepatan Kab. Tangerang", 105, 20, { align: 'center' });
    doc.line(15, 25, 195, 25);

    doc.setFontSize(14);
    doc.text(title, 105, 35, { align: 'center' });
    doc.setFontSize(10);
    doc.text("PHBI Maulid Nabi Muhammad SAW 1448 H | 2026 M", 105, 40, { align: 'center' });
  };

  if (type === 'weekly' || type === 'all_income') {
    addHeader('LAPORAN PEMASUKAN MINGGUAN (PER RT)');

    const rows = data.weeklyData.map(item => [
      item.week,
      item.rt,
      formatDate(item.date),
      formatCurrency(item.grossAmount),
      formatCurrency(item.consumptionCut),
      formatCurrency(item.commissionCut),
      formatCurrency(item.netAmount)
    ]);

    autoTable(doc, {
      startY: 50,
      head: [['Minggu', 'RT', 'Tanggal', 'Kotor', 'Konsumsi 5%', 'Komisi 10%', 'Bersih']],
      body: rows,
      theme: 'grid',
      headStyles: { fillColor: [6, 78, 59] }, // emerald-900
      foot: [['TOTAL', '', '', 
        formatCurrency(data.weeklyData.reduce((a,b)=>a+b.grossAmount,0)),
        formatCurrency(data.weeklyData.reduce((a,b)=>a+b.consumptionCut,0)),
        formatCurrency(data.weeklyData.reduce((a,b)=>a+b.commissionCut,0)),
        formatCurrency(data.weeklyData.reduce((a,b)=>a+b.netAmount,0))
      ]]
    });
  }

  if (type === 'donor' || (type === 'all_income' && data.donors.length > 0)) {
    // If combined report, add spacing
    let finalY = (doc as any).lastAutoTable?.finalY || 50;
    if (type === 'all_income') {
        doc.text("LAPORAN DONATUR", 14, finalY + 15);
        finalY += 20;
    } else {
        addHeader('LAPORAN PEMASUKAN DONATUR');
        finalY = 50;
    }

    const rows = data.donors.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.name,
      item.source,
      formatCurrency(item.nominal)
    ]);

    autoTable(doc, {
      startY: finalY,
      head: [['No', 'Tanggal', 'Nama', 'Sumber', 'Nominal']],
      body: rows,
      theme: 'grid',
      headStyles: { fillColor: [4, 120, 87] }, // emerald-700
      foot: [['', '', '', 'TOTAL', formatCurrency(data.donors.reduce((a,b)=>a+b.nominal,0))]]
    });
  }

  if (type === 'expense' || type === 'all_expense') {
    addHeader('LAPORAN PENGELUARAN DANA');

    const rows = data.expenses.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.purpose,
      formatCurrency(item.nominal)
    ]);

    autoTable(doc, {
      startY: 50,
      head: [['No', 'Tanggal', 'Keperluan', 'Nominal']],
      body: rows,
      theme: 'grid',
      headStyles: { fillColor: [185, 28, 28] }, // red-700
      foot: [['', '', 'TOTAL', formatCurrency(data.expenses.reduce((a,b)=>a+b.nominal,0))]]
    });
  }

  // Footer for all
  const pageCount = doc.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.text(`Dicetak pada: ${new Date().toLocaleString('id-ID')}`, 15, doc.internal.pageSize.height - 10);
    doc.text(`Hal ${i} dari ${pageCount}`, 195, doc.internal.pageSize.height - 10, { align: 'right' });
  }

  doc.save(`Laporan_PHBI_${type}_${new Date().toISOString().slice(0,10)}.pdf`);
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatDate, formatCurrency, calculateWeeklyCuts } from '../../utils/format';
import Swal from 'sweetalert2';
import { Trash2, Edit, Save, Plus } from 'lucide-react';

const InputSection: React.FC = () => {
  const { stagedData, addPreviousFund, deletePreviousFund, addWeeklyData, deleteWeeklyData, addDonor, deleteDonor, addExpense, deleteExpense } = useData();
  const [activeTab, setActiveTab] = useState<'previous' | 'weekly' | 'donor' | 'expense'>('previous');

  // Form States
  const [prevForm, setPrevForm] = useState({ date: '', nominal: '' });
  const [weekForm, setWeekForm] = useState({ date: '', week: '', rt: '', gross: '' });
  const [donorForm, setDonorForm] = useState({ date: '', name: '', source: 'Tunai', nominal: '' });
  const [expForm, setExpForm] = useState({ date: '', purpose: '', nominal: '' });

  const confirmSave = (callback: () => void) => {
    Swal.fire({
      title: 'Yakin Ingin disimpan?',
      text: "Data akan masuk ke dashboard Preview",
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Simpan',
      cancelButtonText: 'Cancel'
    }).then((result) => {
      if (result.isConfirmed) {
        callback();
        Swal.fire('Tersimpan!', 'Data berhasil dikirim ke Dashboard Preview.', 'success');
      }
    });
  };

  const confirmDelete = (id: string, deleteFn: (id: string) => void) => {
    Swal.fire({
      title: 'Apakah anda yakin ingin dihapus?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'Iya, Hapus',
      cancelButtonText: 'Cancel'
    }).then((result) => {
      if (result.isConfirmed) {
        deleteFn(id);
        Swal.fire('Berhasil!', 'Data berhasil dihapus.', 'success');
      }
    });
  };

  // Handlers
  const handleSavePrev = () => {
    if (!prevForm.date || !prevForm.nominal) return;
    confirmSave(() => {
      addPreviousFund({ date: prevForm.date, nominal: Number(prevForm.nominal) });
      setPrevForm({ date: '', nominal: '' });
    });
  };

  const handleSaveWeek = () => {
    if (!weekForm.date || !weekForm.gross) return;
    const gross = Number(weekForm.gross);
    const { consumption, commission, net } = calculateWeeklyCuts(gross);
    confirmSave(() => {
      addWeeklyData({
        date: weekForm.date,
        week: weekForm.week || 'Minggu 1',
        rt: weekForm.rt || 'RT 01',
        grossAmount: gross,
        consumptionCut: consumption,
        commissionCut: commission,
        netAmount: net
      });
      setWeekForm({ date: '', week: 'Minggu 1', rt: 'RT 01', gross: '' });
    });
  };

  const handleSaveDonor = () => {
    if(!donorForm.name || !donorForm.nominal) return;
    confirmSave(() => {
      addDonor({
        date: donorForm.date,
        name: donorForm.name,
        source: donorForm.source,
        nominal: Number(donorForm.nominal)
      });
      setDonorForm({ date: '', name: '', source: 'Tunai', nominal: '' });
    });
  };

  const handleSaveExp = () => {
    if(!expForm.purpose || !expForm.nominal) return;
    confirmSave(() => {
        addExpense({
            date: expForm.date,
            purpose: expForm.purpose,
            nominal: Number(expForm.nominal)
        });
        setExpForm({ date: '', purpose: '', nominal: '' });
    });
  }

  const tabClass = (tab: string) => 
    `px-4 py-2 rounded-t-lg font-semibold ${activeTab === tab ? 'bg-primary text-white' : 'bg-gray-200 text-gray-600 hover:bg-gray-300'}`;

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-gray-800 border-b pb-2">Input Data Keuangan</h2>

      {/* Tabs */}
      <div className="flex flex-wrap gap-2">
        <button onClick={() => setActiveTab('previous')} className={tabClass('previous')}>Panitia Sebelumnya</button>
        <button onClick={() => setActiveTab('weekly')} className={tabClass('weekly')}>Mingguan (Per RT)</button>
        <button onClick={() => setActiveTab('donor')} className={tabClass('donor')}>Donatur</button>
        <button onClick={() => setActiveTab('expense')} className={tabClass('expense')}>Pengeluaran</button>
      </div>

      <div className="bg-white p-6 rounded-b-lg shadow-md border border-gray-200">

        {/* PREVIOUS FUND FORM */}
        {activeTab === 'previous' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 bg-gray-50 p-4 rounded-lg">
                <input type="date" value={prevForm.date} onChange={e => setPrevForm({...prevForm, date: e.target.value})} className="border p-2 rounded" />
                <input type="number" placeholder="Nominal" value={prevForm.nominal} onChange={e => setPrevForm({...prevForm, nominal: e.target.value})} className="border p-2 rounded" />
                <button onClick={handleSavePrev} className="bg-primary text-white py-2 rounded flex items-center justify-center gap-2 hover:bg-emerald-800"><Save size={18}/> SIMPAN DATA</button>
            </div>

            <table className="w-full text-sm text-left">
                <thead className="bg-gray-100 uppercase"><tr><th>Tgl</th><th>Nominal</th><th>Aksi</th></tr></thead>
                <tbody>
                    {stagedData.previousFunds.map(d => (
                        <tr key={d.id} className="border-b">
                            <td className="p-3">{formatDate(d.date)}</td>
                            <td className="p-3 font-bold">{formatCurrency(d.nominal)}</td>
                            <td className="p-3"><button onClick={() => confirmDelete(d.id, deletePreviousFund)} className="text-red-600 hover:text-red-800"><Trash2 size={16}/></button></td>
                        </tr>
                    ))}
                </tbody>
            </table>
          </div>
        )}

        {/* WEEKLY FORM */}
        {activeTab === 'weekly' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 bg-gray-50 p-4 rounded-lg">
                <input type="date" value={weekForm.date} onChange={e => setWeekForm({...weekForm, date: e.target.value})} className="border p-2 rounded" />
                <select value={weekForm.week} onChange={e => setWeekForm({...weekForm, week: e.target.value})} className="border p-2 rounded">
                    <option value="">Pilih Minggu</option>
                    {[...Array(30)].map((_, i) => <option key={i} value={`Minggu ${i+1}`}>Minggu {i+1}</option>)}
                </select>
                <select value={weekForm.rt} onChange={e => setWeekForm({...weekForm, rt: e.target.value})} className="border p-2 rounded">
                    <option value="">Pilih RT</option>
                    {[...Array(6)].map((_, i) => <option key={i} value={`RT 0${i+1}`}>RT 0{i+1}</option>)}
                </select>
                <input type="number" placeholder="Pendapatan Kotor" value={weekForm.gross} onChange={e => setWeekForm({...weekForm, gross: e.target.value})} className="border p-2 rounded" />
                <button onClick={handleSaveWeek} className="bg-primary text-white py-2 rounded flex items-center justify-center gap-2 hover:bg-emerald-800"><Save size={18}/> SIMPAN</button>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-100 uppercase">
                        <tr>
                            <th className="p-3">Minggu/RT</th>
                            <th className="p-3">Kotor</th>
                            <th className="p-3 text-red-500">5%</th>
                            <th className="p-3 text-red-500">10%</th>
                            <th className="p-3 text-green-700">Bersih</th>
                            <th className="p-3">Aksi</th>
                        </tr>
                    </thead>
                    <tbody>
                        {stagedData.weeklyData.map(d => (
                            <tr key={d.id} className="border-b hover:bg-gray-50">
                                <td className="p-3">{d.week} - {d.rt}</td>
                                <td className="p-3">{formatCurrency(d.grossAmount)}</td>
                                <td className="p-3 text-red-500">-{formatCurrency(d.consumptionCut)}</td>
                                <td className="p-3 text-red-500">-{formatCurrency(d.commissionCut)}</td>
                                <td className="p-3 font-bold text-green-700">{formatCurrency(d.netAmount)}</td>
                                <td className="p-3"><button onClick={() => confirmDelete(d.id, deleteWeeklyData)} className="text-red-600 hover:text-red-800"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
          </div>
        )}

        {/* DONOR FORM */}
        {activeTab === 'donor' && (
             <div className="space-y-6">
             <div className="grid grid-cols-1 md:grid-cols-5 gap-4 bg-gray-50 p-4 rounded-lg">
