import React from 'react';
import { useData } from '../../context/DataContext';
import Swal from 'sweetalert2';
import { Trash, AlertTriangle } from 'lucide-react';

const ResetSection: React.FC = () => {
  const { resetData } = useData();

  const handleReset = (type: 'all' | 'previous' | 'weekly' | 'donor' | 'expense', label: string) => {
    Swal.fire({
        title: `Reset Data ${label}?`,
        text: "Apakah Anda Yakin? Data yang sudah diinput akan hilang permanen dari database!",
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        cancelButtonColor: '#3085d6',
        confirmButtonText: 'Ya, Reset Data',
        cancelButtonText: 'Batal'
      }).then((result) => {
        if (result.isConfirmed) {
          resetData(type);
          Swal.fire(
            'Terhapus!',
            `Data ${label} berhasil direset ke 0.`,
            'success'
          );
        }
      });
  };

  return (
    <div className="space-y-6">
       <h2 className="text-2xl font-bold text-red-800 border-b pb-2 flex items-center gap-2">
           <AlertTriangle /> Reset Data
       </h2>
       <div className="bg-red-50 border border-red-200 p-4 rounded-lg text-red-700 text-sm mb-6">
           <strong>PERINGATAN:</strong> Tindakan ini tidak dapat dibatalkan. Menghapus data di sini akan menghapus data di database (Mock Supabase) secara permanen.
       </div>

       <div className="space-y-4">
           {[
               { id: 'previous', label: 'Data Panitia Sebelumnya' },
               { id: 'weekly', label: 'Data Mingguan (Per RT)' },
               { id: 'donor', label: 'Data Donatur' },
               { id: 'expense', label: 'Data Pengeluaran' },
               { id: 'all', label: 'SEMUA DATA (SELURUHNYA)', danger: true }
           ].map((item) => (
               <div key={item.id} className="flex items-center justify-between bg-white p-4 shadow rounded border border-gray-100">
                   <span className="font-semibold">{item.label}</span>
                   <button 
                    onClick={() => handleReset(item.id as any, item.label)}
                    className={`px-4 py-2 rounded text-white text-sm font-bold flex items-center gap-2 ${item.danger ? 'bg-red-700 hover:bg-red-900' : 'bg-orange-500 hover:bg-orange-600'}`}
                   >
                       <Trash size={16} /> Reset
                   </button>
               </div>
           ))}
       </div>
    </div>
  );
};

