                 <span>Preview Data</span>
             </div>
             <div onClick={() => setActivePage('report')} className={navItemClass('report')}>
                 <FileText size={20}/>
                 <span>Laporan</span>
             </div>
             <div onClick={() => setActivePage('reset')} className={navItemClass('reset')}>
                 <RefreshCcw size={20}/>
