                <button onClick={handleSavePrev} className="bg-primary text-white py-2 rounded-lg font-bold flex items-center justify-center gap-2 hover:bg-emerald-800 shadow-md transform active:scale-95 transition"><Save size={18}/> SIMPAN DATA</button>
            </div>

            {/* Desktop Table */}
            <div className="hidden md:block">
