        text: 'User Name dan Password salah. Silahkan Periksa kembali',
        confirmButtonColor: '#064e3b'
      });
    }
  };

  const handleRegisterClick = () => {
    Swal.fire({
      title: 'Pendaftaran Akun Baru',
      text: 'Silahkan Menghubungi Ketua Panitia',
      icon: 'info',
      confirmButtonText: 'Baik, Mengerti',
      confirmButtonColor: '#2563eb' // Blue
    });
  };

  if (isLoggedIn) {
    return <AdminDashboard />;
  }

  return (
    <div className="flex flex-col min-h-screen font-sans">
      <Header onLoginClick={() => setIsLoginModalOpen(true)} />

      <main className="flex-grow bg-gray-50">
        <PublicHome />
      </main>

      <Footer />

      {/* Login Modal */}
      {isLoginModalOpen && (
        <Modal title="Masuk Admin" onClose={() => setIsLoginModalOpen(false)}>
           <div className="space-y-5">
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Username</label>
                <input 
                  type="text" 
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full bg-white border border-gray-300 text-gray-900 rounded-lg px-4 py-3 focus:ring-2 focus:ring-primary focus:border-primary outline-none shadow-sm transition"
                  placeholder="Masukkan Username"
                />
              </div>
              <div>
                <label className="block text-sm font-semibold text-gray-700 mb-1">Password</label>
                <div className="relative">
                  <input 
                    type={showPassword ? "text" : "password"} 
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full bg-white border border-gray-300 text-gray-900 rounded-lg px-4 py-3 pr-10 focus:ring-2 focus:ring-primary focus:border-primary outline-none shadow-sm transition"
                    placeholder="Masukkan Password"
                  />
                  {/* Icon Mata */}
                  <button 
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-primary transition"
                    type="button"
                  >
                    {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                  </button>
                </div>
              </div>

              <div className="flex flex-col gap-3 pt-2">
                <div className="flex gap-3">
                  <button 
                    onClick={() => setIsLoginModalOpen(false)}
                    className="flex-1 bg-gray-100 text-gray-700 py-3 rounded-lg hover:bg-gray-200 font-bold border border-gray-300 transition"
                  >
                    Batal
                  </button>
                  <button 
                    onClick={handleLoginSubmit}
                    className="flex-1 bg-primary text-white py-3 rounded-lg hover:bg-emerald-800 font-bold shadow-md transition"
                  >
                    Login
                  </button>
                </div>

                {/* Tombol Daftar Biru */}
                <div className="relative flex py-2 items-center">
                    <div className="flex-grow border-t border-gray-200"></div>
                    <span className="flex-shrink-0 mx-4 text-gray-400 text-xs">Atau</span>
                    <div className="flex-grow border-t border-gray-200"></div>
                </div>

                <button 
                  onClick={handleRegisterClick}
                  className="w-full bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-lg font-bold shadow-md transition flex items-center justify-center gap-2"
                >
                  <UserPlus size={18} /> Daftar Akun Baru
                </button>
              </div>
           </div>
        </Modal>
      )}
    </div>
  );
};

