             </div>

             {/* Desktop Table */}
             <div className="hidden md:block">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-100 uppercase text-gray-700"><tr><th className="p-3">Tgl</th><th className="p-3">Keperluan</th><th className="p-3">Nominal</th><th className="p-3">Aksi</th></tr></thead>
                    <tbody>
                        {stagedData.expenses.map(d => (
                            <tr key={d.id} className="border-b">
                                <td className="p-3">{formatDate(d.date)}</td>
                                <td className="p-3">{d.purpose}</td>
                                <td className="p-3 font-bold text-red-600">{formatCurrency(d.nominal)}</td>
                                <td className="p-3"><button onClick={() => confirmDelete(d.id, deleteExpense)} className="text-red-600 hover:text-red-800 bg-red-50 p-2 rounded-full"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>

             {/* Mobile Cards */}
             <div className="md:hidden space-y-3">
               {stagedData.expenses.map(d => (
                 <div key={d.id} className="bg-white border border-gray-200 p-4 rounded-lg shadow-sm border-l-4 border-l-red-500">
                    <div className="flex justify-between items-start">
                        <div>
                             <h4 className="font-bold text-gray-800 text-sm">{d.purpose}</h4>
                             <p className="text-xs text-gray-500 mt-1">{formatDate(d.date)}</p>
                        </div>
                        <button onClick={() => confirmDelete(d.id, deleteExpense)} className="text-red-600 bg-red-50 p-2 rounded-lg flex-shrink-0 ml-2"><Trash2 size={18}/></button>
                    </div>
                    <div className="text-right mt-2 font-bold text-red-600 text-lg">
                        {formatCurrency(d.nominal)}
                    </div>
                 </div>
               ))}
            </div>

           </div>
        )}

      </div>
    </div>
  );
};

