import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatCurrency, formatDate } from '../../utils/format';
import Swal from 'sweetalert2';
import { UploadCloud, AlertCircle } from 'lucide-react';

const PreviewSection: React.FC = () => {
  const { stagedData, publishData } = useData();
  const [updateDate, setUpdateDate] = useState(new Date().toISOString().split('T')[0]);

  const handlePublish = () => {
    if (!updateDate) {
        Swal.fire('Error', 'Silahkan pilih tanggal publikasi/update terlebih dahulu.', 'error');
        return;
    }

    Swal.fire({
      title: 'Publikasikan Data?',
      text: "Data akan tampil di Halaman Utama Publik.",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'YA, Publikasikan',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        publishData(updateDate);
      }
    });
  };

  const totalStagedIncome = 
    stagedData.previousFunds.reduce((a,b)=>a+b.nominal,0) + 
    stagedData.weeklyData.reduce((a,b)=>a+b.netAmount,0) + 
    stagedData.donors.reduce((a,b)=>a+b.nominal,0);

  const totalStagedExpense = stagedData.expenses.reduce((a,b)=>a+b.nominal,0);

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-center border-b pb-4 gap-4">
        <div>
           <h2 className="text-2xl font-bold text-gray-800">Preview Data (Draft)</h2>
           <p className="text-sm text-gray-500">Data ini belum dilihat publik sampai Anda menekan tombol Publikasikan.</p>
        </div>

        <div className="flex flex-col md:flex-row items-center gap-3 w-full md:w-auto">
             {/* Date Selection for Update Status */}
             <div className="w-full md:w-auto">
                 <label className="block text-xs font-bold text-gray-600 mb-1">Tanggal Update Realtime</label>
                 <input 
                    type="date" 
                    value={updateDate}
                    onChange={(e) => setUpdateDate(e.target.value)}
                    className="w-full bg-white border border-gray-300 rounded px-3 py-2 text-sm focus:ring-2 focus:ring-primary outline-none"
                    style={{colorScheme: 'light'}}
                 />
             </div>

             <button 
                onClick={handlePublish}
                className="w-full md:w-auto bg-secondary hover:bg-primary text-white px-6 py-3 rounded-lg font-bold shadow-lg flex items-center justify-center gap-2 animate-pulse mt-2 md:mt-0"
            >
                <UploadCloud /> PUBLIKASIKAN DATA
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-emerald-50 p-4 rounded-lg border border-emerald-200">
            <h3 className="font-bold text-emerald-800">Total Pemasukan (Draft)</h3>
            <p className="text-2xl font-bold">{formatCurrency(totalStagedIncome)}</p>
        </div>
        <div className="bg-red-50 p-4 rounded-lg border border-red-200">
            <h3 className="font-bold text-red-800">Total Pengeluaran (Draft)</h3>
            <p className="text-2xl font-bold">{formatCurrency(totalStagedExpense)}</p>
        </div>
      </div>

      {/* Tables Preview - Simplified view */}
      <div className="space-y-4">
        <h3 className="font-bold text-gray-700">Ringkasan Item Belum Dipublikasi</h3>

        {stagedData.weeklyData.length > 0 && (
            <div className="bg-white border rounded p-4">
                <h4 className="font-bold mb-2">Mingguan ({stagedData.weeklyData.length} items)</h4>
                <div className="max-h-40 overflow-y-auto text-sm">
                    {stagedData.weeklyData.map(d => (
                        <div key={d.id} className="flex justify-between py-1 border-b border-gray-100">
                            <span>{d.week} - {d.rt}</span>
                            <span className="font-mono">{formatCurrency(d.netAmount)}</span>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {stagedData.donors.length > 0 && (
             <div className="bg-white border rounded p-4">
             <h4 className="font-bold mb-2">Donatur ({stagedData.donors.length} items)</h4>
             <div className="max-h-40 overflow-y-auto text-sm">
                 {stagedData.donors.map(d => (
                     <div key={d.id} className="flex justify-between py-1 border-b border-gray-100">
                         <span>{d.name} ({d.source})</span>
                         <span className="font-mono">{formatCurrency(d.nominal)}</span>
                     </div>
                 ))}
             </div>
         </div>
        )}

        {stagedData.expenses.length > 0 && (
             <div className="bg-white border rounded p-4">
             <h4 className="font-bold mb-2 text-red-700">Pengeluaran ({stagedData.expenses.length} items)</h4>
             <div className="max-h-40 overflow-y-auto text-sm">
                 {stagedData.expenses.map(d => (
                     <div key={d.id} className="flex justify-between py-1 border-b border-gray-100">
                         <span>{d.purpose}</span>
                         <span className="font-mono text-red-600">{formatCurrency(d.nominal)}</span>
                     </div>
                 ))}
             </div>
         </div>
        )}

        {stagedData.weeklyData.length === 0 && stagedData.donors.length === 0 && stagedData.expenses.length === 0 && (
            <div className="text-center py-10 bg-gray-50 text-gray-400 rounded-lg flex flex-col items-center">
                <AlertCircle size={48} className="mb-2"/>
                <p>Tidak ada data baru untuk dipublikasikan.</p>
            </div>
        )}

      </div>

    </div>
  );
};

export default PreviewSection;

import React from 'react';
import { ArrowUpCircle, ArrowDownCircle, Wallet, Info } from 'lucide-react';
import { formatCurrency } from '../utils/format';

interface SummaryCardProps {
  title: string;
  amount: number;
  type: 'income' | 'expense' | 'balance';
  subtitle?: string;
  onDetailClick?: () => void;
}

const SummaryCard: React.FC<SummaryCardProps> = ({ title, amount, type, subtitle, onDetailClick }) => {
  const getIcon = () => {
    switch (type) {
      case 'income': return <ArrowUpCircle className="w-6 h-6 md:w-8 md:h-8 text-emerald-600" />;
      case 'expense': return <ArrowDownCircle className="w-6 h-6 md:w-8 md:h-8 text-red-600" />;
      default: return <Wallet className="w-6 h-6 md:w-8 md:h-8 text-blue-600" />;
    }
  };

  const getBgColor = () => {
    switch (type) {
      case 'income': return 'bg-emerald-50 border-emerald-200';
      case 'expense': return 'bg-red-50 border-red-200';
      default: return 'bg-blue-50 border-blue-200';
    }
  };

  return (
    <div className={`rounded-xl p-4 md:p-6 shadow-md border ${getBgColor()} relative transition hover:shadow-lg`}>
      <div className="flex justify-between items-start">
        <div>
          <p className="text-gray-500 text-xs md:text-sm font-semibold uppercase tracking-wider">{title}</p>
          <h3 className="text-xl md:text-3xl font-bold mt-1 md:mt-2 text-gray-800">{formatCurrency(amount)}</h3>
          {subtitle && (
            <p className="text-[10px] md:text-xs text-gray-500 mt-1 font-medium">{subtitle}</p>
          )}
        </div>
        {getIcon()}
      </div>
      {onDetailClick && (
        <button 
          onClick={onDetailClick}
          className="absolute bottom-3 right-3 md:bottom-4 md:right-4 text-[10px] md:text-xs font-semibold text-gray-500 hover:text-primary flex items-center gap-1"
        >
          <Info className="w-3 h-3 md:w-4 md:h-4" /> Detail
        </button>
      )}
    </div>
  );
};

export default SummaryCard;

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatDate, formatCurrency, calculateWeeklyCuts } from '../../utils/format';
import Swal from 'sweetalert2';
import { Trash2, Save } from 'lucide-react';

const InputSection: React.FC = () => {
  const { stagedData, addPreviousFund, deletePreviousFund, addWeeklyData, deleteWeeklyData, addDonor, deleteDonor, addExpense, deleteExpense } = useData();
  const [activeTab, setActiveTab] = useState<'previous' | 'weekly' | 'donor' | 'expense'>('previous');

  // Form States
  const [prevForm, setPrevForm] = useState({ date: '', nominal: '' });
  const [weekForm, setWeekForm] = useState({ date: '', week: '', rt: '', gross: '' });
  const [donorForm, setDonorForm] = useState({ date: '', name: '', source: 'Tunai', nominal: '' });
  const [expForm, setExpForm] = useState({ date: '', purpose: '', nominal: '' });

  const confirmSave = (callback: () => void) => {
    Swal.fire({
      title: 'Yakin Ingin disimpan?',
      text: "Data akan masuk ke dashboard Preview",
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Simpan',
      cancelButtonText: 'Cancel'
    }).then((result) => {
      if (result.isConfirmed) {
        callback();
        Swal.fire('Tersimpan!', 'Data berhasil dikirim ke Dashboard Preview.', 'success');
      }
    });
  };

  const confirmDelete = (id: string, deleteFn: (id: string) => void) => {
    Swal.fire({
      title: 'Apakah anda yakin?',
      text: "Hapus data ini?",
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'Ya, Hapus',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        deleteFn(id);
        Swal.fire('Berhasil!', 'Data dihapus.', 'success');
      }
    });
  };

  // Handlers
  const handleSavePrev = () => {
    if (!prevForm.date || !prevForm.nominal) return;
    confirmSave(() => {
      addPreviousFund({ date: prevForm.date, nominal: Number(prevForm.nominal) });
      setPrevForm({ date: '', nominal: '' });
    });
  };

  const handleSaveWeek = () => {
    if (!weekForm.date || !weekForm.gross) return;
    const gross = Number(weekForm.gross);
    const { consumption, commission, net } = calculateWeeklyCuts(gross);
    confirmSave(() => {
      addWeeklyData({
        date: weekForm.date,
        week: weekForm.week || 'Minggu 1',
        rt: weekForm.rt || 'RT 01',
        grossAmount: gross,
        consumptionCut: consumption,
        commissionCut: commission,
        netAmount: net
      });
      setWeekForm({ date: '', week: 'Minggu 1', rt: 'RT 01', gross: '' });
    });
  };

  const handleSaveDonor = () => {
    if(!donorForm.name || !donorForm.nominal) return;
    confirmSave(() => {
      addDonor({
        date: donorForm.date,
        name: donorForm.name,
        source: donorForm.source,
        nominal: Number(donorForm.nominal)
      });
      setDonorForm({ date: '', name: '', source: 'Tunai', nominal: '' });
    });
  };

  const handleSaveExp = () => {
    if(!expForm.purpose || !expForm.nominal) return;
    confirmSave(() => {
        addExpense({
            date: expForm.date,
            purpose: expForm.purpose,
            nominal: Number(expForm.nominal)
        });
        setExpForm({ date: '', purpose: '', nominal: '' });
    });
  }

  const tabClass = (tab: string) => 
    `flex-1 text-center md:flex-none px-2 py-2 md:px-4 md:py-3 rounded-t-lg font-bold text-xs md:text-base transition-colors ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`;

  // Common Input Class with specific Focus Outline and Date Icon styling
  const inputClass = "w-full bg-white border border-gray-300 text-gray-900 text-sm rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary shadow-sm transition-shadow [&::-webkit-calendar-picker-indicator]:cursor-pointer";

  // Input class specifically for Rupiah inputs (padding left)
