      <div className="flex flex-row gap-1 overflow-x-auto no-scrollbar">
        <button onClick={() => setActiveTab('previous')} className={tabClass('previous')}>Panitia</button>
        <button onClick={() => setActiveTab('weekly')} className={tabClass('weekly')}>Mingguan</button>
        <button onClick={() => setActiveTab('donor')} className={tabClass('donor')}>Donatur</button>
        <button onClick={() => setActiveTab('expense')} className={tabClass('expense')}>Keluar</button>
      </div>

      <div className="bg-white p-3 md:p-6 rounded-b-lg shadow-md border border-gray-200">

        {/* PREVIOUS FUND FORM */}
        {activeTab === 'previous' && (
          <div className="space-y-4 md:space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 bg-gray-50 p-3 rounded-lg border border-gray-200">
                <input 
                  type="date" 
                  id="date-prev"
                  value={prevForm.date} 
                  onChange={e => setPrevForm({...prevForm, date: e.target.value})} 
                  className={inputClass} 
                  style={{colorScheme: 'light'}} 
                />

                {/* Nominal Input with Dots */}
                <div className="relative">
                    <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-sm pointer-events-none">Rp.</span>
                    <input 
                        type="text" 
