                <button onClick={handleSavePrev} className="bg-primary text-white py-2 rounded-lg font-bold text-xs md:text-sm flex items-center justify-center gap-2 hover:bg-emerald-800 shadow-md transform active:scale-95 transition"><Save size={16}/> SIMPAN</button>
            </div>

            {/* Desktop Table */}
            <div className="hidden md:block">
              <table className="w-full text-sm text-left">
