                 <label className="block text-[10px] md:text-xs font-bold text-gray-600 mb-1">Tanggal Update Realtime</label>
                 <input 
                    type="date" 
                    value={updateDate}
                    onChange={(e) => setUpdateDate(e.target.value)}
                    className="w-full bg-white border border-gray-300 rounded px-3 py-2 text-sm focus:ring-1 focus:ring-primary outline-none"
                    style={{colorScheme: 'light'}}
                 />
             </div>

             <button 
                onClick={handlePublish}
                className="w-full md:w-auto bg-secondary hover:bg-primary text-white px-4 py-2 md:px-6 md:py-3 rounded-lg font-bold shadow-lg flex items-center justify-center gap-2 animate-pulse mt-2 md:mt-0 text-sm md:text-base"
            >
                <UploadCloud size={18} /> PUBLIKASIKAN DATA
            </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3 md:gap-6">
        <div className="bg-emerald-50 p-3 md:p-4 rounded-lg border border-emerald-200">
            <h3 className="font-bold text-emerald-800 text-xs md:text-base">Total Pemasukan (Draft)</h3>
            <p className="text-base md:text-2xl font-bold">{formatCurrency(totalStagedIncome)}</p>
        </div>
        <div className="bg-red-50 p-3 md:p-4 rounded-lg border border-red-200">
            <h3 className="font-bold text-red-800 text-xs md:text-base">Total Pengeluaran (Draft)</h3>
            <p className="text-base md:text-2xl font-bold">{formatCurrency(totalStagedExpense)}</p>
        </div>
      </div>

      {/* Tables Preview - Simplified view */}
      <div className="space-y-3 md:space-y-4">
        <h3 className="font-bold text-gray-700 text-sm md:text-base">Ringkasan Item Belum Dipublikasi</h3>

        {stagedData.weeklyData.length > 0 && (
            <div className="bg-white border rounded p-3 md:p-4">
                <h4 className="font-bold mb-2 text-xs md:text-sm">Mingguan ({stagedData.weeklyData.length} items)</h4>
                <div className="max-h-40 overflow-y-auto text-xs md:text-sm">
                    {stagedData.weeklyData.map(d => (
                        <div key={d.id} className="flex justify-between py-1 border-b border-gray-100">
                            <span>{d.week} - {d.rt}</span>
                            <span className="font-mono">{formatCurrency(d.netAmount)}</span>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {stagedData.donors.length > 0 && (
             <div className="bg-white border rounded p-3 md:p-4">
             <h4 className="font-bold mb-2 text-xs md:text-sm">Donatur ({stagedData.donors.length} items)</h4>
             <div className="max-h-40 overflow-y-auto text-xs md:text-sm">
