const InputSection: React.FC = () => {
  const { stagedData, addPreviousFund, deletePreviousFund, addWeeklyData, deleteWeeklyData, addDonor, deleteDonor, addExpense, deleteExpense } = useData();
  const [activeTab, setActiveTab] = useState<'previous' | 'weekly' | 'donor' | 'expense'>('previous');

  // Form States - Nominal disimpan sebagai string agar bisa menampilkan format titik (Rp. 1.000.000)
  const [prevForm, setPrevForm] = useState({ date: '', nominal: '' });
  const [weekForm, setWeekForm] = useState({ date: '', week: '', rt: '', gross: '' });
  const [donorForm, setDonorForm] = useState({ date: '', name: '', source: 'Tunai', nominal: '' });
  const [expForm, setExpForm] = useState({ date: '', purpose: '', nominal: '' });

  // 1. Helper: Format tampilan saat mengetik (Visual: 1000000 -> 1.000.000)
  const formatNumberInput = (value: string) => {
    if (!value) return '';
    // Hanya ambil angka
    const rawValue = value.replace(/\D/g, ''); 
    // Format ke string dengan titik (id-ID)
    return new Intl.NumberFormat('id-ID').format(Number(rawValue));
  };

  // 2. Helper: Ubah kembali ke angka murni untuk disimpan ke Database/Context (Data: 1.000.000 -> 1000000)
  const parseNumberInput = (value: string) => {
    if (!value) return 0;
    // Hapus semua titik, lalu jadikan number
    return Number(value.replace(/\./g, ''));
  };

  const confirmSave = (callback: () => void) => {
    Swal.fire({
      title: 'Yakin Ingin disimpan?',
      text: "Data akan masuk ke dashboard Preview",
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Simpan',
      cancelButtonText: 'Cancel'
    }).then((result) => {
      if (result.isConfirmed) {
        callback();
        Swal.fire('Tersimpan!', 'Data berhasil dikirim ke Dashboard Preview.', 'success');
      }
    });
  };

  const confirmDelete = (id: string, deleteFn: (id: string) => void) => {
    Swal.fire({
      title: 'Hapus Data?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'Ya, Hapus',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        deleteFn(id);
        Swal.fire('Berhasil!', 'Data dihapus.', 'success');
      }
    });
  };

  // --- HANDLERS DENGAN PARSING ANGKA ---

  const handleSavePrev = () => {
    if (!prevForm.date || !prevForm.nominal) return;
    confirmSave(() => {
      // Gunakan parseNumberInput agar yang tersimpan adalah angka murni (bisa dijumlahkan)
      addPreviousFund({ date: prevForm.date, nominal: parseNumberInput(prevForm.nominal) });
      setPrevForm({ date: '', nominal: '' });
    });
  };

  const handleSaveWeek = () => {
    if (!weekForm.date || !weekForm.gross) return;
    // Parsing angka murni sebelum perhitungan
    const gross = parseNumberInput(weekForm.gross);
    const { consumption, commission, net } = calculateWeeklyCuts(gross);
    confirmSave(() => {
      addWeeklyData({
        date: weekForm.date,
        week: weekForm.week || 'Minggu 1',
        rt: weekForm.rt || 'RT 01',
        grossAmount: gross,
        consumptionCut: consumption,
        commissionCut: commission,
        netAmount: net
      });
      setWeekForm({ date: '', week: 'Minggu 1', rt: 'RT 01', gross: '' });
    });
  };

  const handleSaveDonor = () => {
    if(!donorForm.name || !donorForm.nominal) return;
    confirmSave(() => {
      addDonor({
        date: donorForm.date,
        name: donorForm.name,
        source: donorForm.source,
        nominal: parseNumberInput(donorForm.nominal)
      });
      setDonorForm({ date: '', name: '', source: 'Tunai', nominal: '' });
    });
  };

  const handleSaveExp = () => {
    if(!expForm.purpose || !expForm.nominal) return;
    confirmSave(() => {
        addExpense({
            date: expForm.date,
            purpose: expForm.purpose,
            nominal: parseNumberInput(expForm.nominal)
        });
        setExpForm({ date: '', purpose: '', nominal: '' });
    });
  }

  const tabClass = (tab: string) => 
    `flex-1 text-center md:flex-none px-2 py-2 md:px-4 md:py-3 rounded-t-lg font-bold text-xs md:text-sm transition-colors ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`;

  // Common Input Class with thinner focus outline (ring-1)
  const inputClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg px-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm transition-shadow [&::-webkit-calendar-picker-indicator]:cursor-pointer";

  // Input class specifically for Rupiah inputs
  const inputRpClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg pl-8 md:pl-10 pr-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm transition-shadow font-mono tracking-wide";

  return (
    <div className="space-y-4 md:space-y-6">
      <h2 className="text-sm md:text-xl font-bold text-gray-800 border-b pb-2">Input Data Keuangan</h2>

      {/* Tabs */}
      <div className="flex flex-row gap-1 overflow-x-auto no-scrollbar">
        <button onClick={() => setActiveTab('previous')} className={tabClass('previous')}>Panitia</button>
        <button onClick={() => setActiveTab('weekly')} className={tabClass('weekly')}>Mingguan</button>
        <button onClick={() => setActiveTab('donor')} className={tabClass('donor')}>Donatur</button>
        <button onClick={() => setActiveTab('expense')} className={tabClass('expense')}>Keluar</button>
      </div>

      <div className="bg-white p-3 md:p-6 rounded-b-lg shadow-md border border-gray-200">

        {/* PREVIOUS FUND FORM */}
        {activeTab === 'previous' && (
          <div className="space-y-4 md:space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 bg-gray-50 p-3 rounded-lg border border-gray-200">
                <div className="w-full">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input 
                    type="date" 
                    id="date-prev"
                    value={prevForm.date} 
                    onChange={e => setPrevForm({...prevForm, date: e.target.value})} 
                    className={inputClass} 
                    style={{colorScheme: 'light'}} 
                    />
                </div>

                {/* Nominal Input with Dots */}
                <div className="w-full">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Nominal</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input 
                            type="text" 
                            inputMode="numeric"
                            placeholder="0" 
                            value={prevForm.nominal} 
                            onChange={e => setPrevForm({...prevForm, nominal: formatNumberInput(e.target.value)})} 
                            className={inputRpClass} 
                        />
                    </div>
                </div>

                <div className="flex items-end">
                     <button onClick={handleSavePrev} className="w-full bg-primary text-white py-2 rounded-lg font-bold text-xs md:text-sm flex items-center justify-center gap-2 hover:bg-emerald-800 shadow-md transform active:scale-95 transition"><Save size={16}/> SIMPAN</button>
                </div>
            </div>

            {/* Desktop Table */}
            <div className="hidden md:block">
              <table className="w-full text-sm text-left">
                  <thead className="bg-gray-100 uppercase text-gray-700"><tr><th className="p-3">Tgl</th><th className="p-3">Nominal</th><th className="p-3">Aksi</th></tr></thead>
                  <tbody>
                      {stagedData.previousFunds.map(d => (
                          <tr key={d.id} className="border-b">
                              <td className="p-3">{formatDate(d.date)}</td>
                              <td className="p-3 font-bold">{formatCurrency(d.nominal)}</td>
                              <td className="p-3"><button onClick={() => confirmDelete(d.id, deletePreviousFund)} className="text-red-600 hover:text-red-800 bg-red-50 p-2 rounded-full"><Trash2 size={16}/></button></td>
                          </tr>
                      ))}
                  </tbody>
              </table>
            </div>

            {/* Mobile Cards */}
            <div className="md:hidden space-y-2">
               {stagedData.previousFunds.map(d => (
                 <div key={d.id} className="bg-white border border-gray-200 p-3 rounded-lg shadow-sm flex justify-between items-center">
                    <div>
                        <p className="text-[10px] text-gray-500">{formatDate(d.date)}</p>
                        <p className="font-bold text-gray-800 text-sm">{formatCurrency(d.nominal)}</p>
                    </div>
                    <button onClick={() => confirmDelete(d.id, deletePreviousFund)} className="bg-red-50 text-red-600 p-1.5 rounded-lg"><Trash2 size={16}/></button>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* WEEKLY FORM */}
        {activeTab === 'weekly' && (
          <div className="space-y-4 md:space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3 bg-gray-50 p-3 rounded-lg border border-gray-200">
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input 
                    type="date"
                    id="date-week"
                    value={weekForm.date} 
                    onChange={e => setWeekForm({...weekForm, date: e.target.value})} 
                    className={inputClass} 
                    style={{colorScheme: 'light'}}
                    />
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Minggu Ke</label>
                    <select value={weekForm.week} onChange={e => setWeekForm({...weekForm, week: e.target.value})} className={inputClass}>
                        <option value="">Pilih Minggu</option>
                        {[...Array(30)].map((_, i) => <option key={i} value={`Minggu ${i+1}`}>Minggu {i+1}</option>)}
                    </select>
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">RT</label>
                    <select value={weekForm.rt} onChange={e => setWeekForm({...weekForm, rt: e.target.value})} className={inputClass}>
                        <option value="">Pilih RT</option>
                        {[...Array(6)].map((_, i) => <option key={i} value={`RT 0${i+1}`}>RT 0{i+1}</option>)}
                    </select>
                </div>

                {/* Nominal Input with Dots */}
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Pemasukan Kotor</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input 
                            type="text" 
                            inputMode="numeric"
                            placeholder="0" 
                            value={weekForm.gross} 
                            onChange={e => setWeekForm({...weekForm, gross: formatNumberInput(e.target.value)})} 
                            className={inputRpClass} 
                        />
                    </div>
                </div>

                <div className="col-span-1 md:col-span-2 lg:col-span-1 flex items-end">
                    <button onClick={handleSaveWeek} className="w-full bg-primary text-white py-2 rounded-lg font-bold text-xs md:text-sm flex items-center justify-center gap-2 hover:bg-emerald-800 shadow-md transform active:scale-95 transition"><Save size={16}/> SIMPAN</button>
                </div>
            </div>

            {/* Desktop Table */}
            <div className="hidden md:block overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-100 uppercase text-gray-700">
                        <tr>
                            <th className="p-3">Minggu/RT</th>
                            <th className="p-3">Kotor</th>
                            <th className="p-3 text-red-500">5%</th>
                            <th className="p-3 text-red-500">10%</th>
                            <th className="p-3 text-green-700">Bersih</th>
                            <th className="p-3">Aksi</th>
                        </tr>
                    </thead>
                    <tbody>
                        {stagedData.weeklyData.map(d => (
                            <tr key={d.id} className="border-b hover:bg-gray-50">
                                <td className="p-3 font-medium">{d.week} - {d.rt}</td>
                                <td className="p-3">{formatCurrency(d.grossAmount)}</td>
                                <td className="p-3 text-red-500">-{formatCurrency(d.consumptionCut)}</td>
                                <td className="p-3 text-red-500">-{formatCurrency(d.commissionCut)}</td>
                                <td className="p-3 font-bold text-green-700">{formatCurrency(d.netAmount)}</td>
                                <td className="p-3"><button onClick={() => confirmDelete(d.id, deleteWeeklyData)} className="text-red-600 hover:text-red-800 bg-red-50 p-2 rounded-full"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

             {/* Mobile Cards with Detailed Breakdown */}
             <div className="md:hidden space-y-2">
               {stagedData.weeklyData.map(d => (
                 <div key={d.id} className="bg-white border border-gray-200 p-3 rounded-lg shadow-sm relative">
                    <div className="flex justify-between items-center mb-2 pb-1 border-b border-gray-100">
                        <div className="flex items-center gap-2">
                             <span className="font-bold text-gray-800 text-xs">{d.week}</span>
                             <span className="bg-emerald-50 text-emerald-700 text-[10px] px-1.5 py-0.5 rounded border border-emerald-100">{d.rt}</span>
                        </div>
                        <button onClick={() => confirmDelete(d.id, deleteWeeklyData)} className="text-red-600 bg-red-50 p-1.5 rounded"><Trash2 size={14}/></button>
                    </div>

                    {/* Detailed Breakdown Section */}
                    <div className="text-[10px] space-y-1">
                        <div className="flex justify-between text-gray-600">
                             <span>Kotor:</span>
                             <span className="font-medium">{formatCurrency(d.grossAmount)}</span>
                        </div>
                        <div className="flex justify-between text-red-500">
                             <span>Pot 5%:</span>
                             <span>-{formatCurrency(d.consumptionCut)}</span>
                        </div>
                        <div className="flex justify-between text-red-500">
                             <span>Pot 10%:</span>
                             <span>-{formatCurrency(d.commissionCut)}</span>
                        </div>
                        <div className="flex justify-between font-bold text-primary border-t border-dashed border-gray-300 pt-1 mt-1">
                             <span>Bersih:</span>
                             <span className="text-xs">{formatCurrency(d.netAmount)}</span>
                        </div>
                    </div>
                 </div>
               ))}
            </div>

          </div>
        )}

        {/* DONOR FORM */}
        {activeTab === 'donor' && (
             <div className="space-y-4 md:space-y-6">
             <div className="grid grid-cols-1 md:grid-cols-5 gap-3 bg-gray-50 p-3 rounded-lg border border-gray-200">
                 <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input 
                    type="date"
                    id="date-donor"
                    value={donorForm.date} 
                    onChange={e => setDonorForm({...donorForm, date: e.target.value})} 
                    className={inputClass} 
                    style={{colorScheme: 'light'}}
                    />
                 </div>
                 <div className="col-span-1 md:col-span-2 lg:col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Nama</label>
                    <input type="text" placeholder="Nama Donatur" value={donorForm.name} onChange={e => setDonorForm({...donorForm, name: e.target.value})} className={inputClass} />
                 </div>
                 <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Sumber</label>
                    <select value={donorForm.source} onChange={e => setDonorForm({...donorForm, source: e.target.value})} className={inputClass}>
                        <option value="Tunai">Tunai</option>
                        <option value="Transfer">Transfer</option>
                        <option value="QRIS">QRIS</option>
                    </select>
                 </div>

                 {/* Nominal Input with Dots */}
                 <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Nominal</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input 
                            type="text" 
                            inputMode="numeric"
                            placeholder="0" 
                            value={donorForm.nominal} 
                            onChange={e => setDonorForm({...donorForm, nominal: formatNumberInput(e.target.value)})} 
                            className={inputRpClass} 
                        />
                    </div>
                 </div>

                 <div className="col-span-1 md:col-span-5 flex items-end">
                    <button onClick={handleSaveDonor} className="w-full bg-primary text-white py-2 rounded-lg font-bold text-xs md:text-sm flex items-center justify-center gap-2 hover:bg-emerald-800 shadow-md transform active:scale-95 transition"><Save size={16}/> SIMPAN</button>
                 </div>
             </div>

             {/* Desktop Table */}
             <div className="hidden md:block">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-100 uppercase text-gray-700"><tr><th className="p-3">Tgl</th><th className="p-3">Nama</th><th className="p-3">Sumber</th><th className="p-3">Nominal</th><th className="p-3">Aksi</th></tr></thead>
                    <tbody>
                        {stagedData.donors.map(d => (
                            <tr key={d.id} className="border-b">
                                <td className="p-3">{formatDate(d.date)}</td>
                                <td className="p-3 font-semibold">{d.name}</td>
                                <td className="p-3"><span className="bg-blue-50 text-blue-700 px-2 py-1 rounded text-xs border border-blue-100">{d.source}</span></td>
                                <td className="p-3 font-bold">{formatCurrency(d.nominal)}</td>
                                <td className="p-3"><button onClick={() => confirmDelete(d.id, deleteDonor)} className="text-red-600 hover:text-red-800 bg-red-50 p-2 rounded-full"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>

             {/* Mobile Cards */}
             <div className="md:hidden space-y-2">
               {stagedData.donors.map(d => (
                 <div key={d.id} className="bg-white border border-gray-200 p-3 rounded-lg shadow-sm">
                    <div className="flex justify-between items-start mb-1">
                        <div>
                             <h4 className="font-bold text-gray-800 text-sm">{d.name}</h4>
                             <p className="text-[10px] text-gray-500">{formatDate(d.date)}</p>
                        </div>
                        <button onClick={() => confirmDelete(d.id, deleteDonor)} className="text-red-600 bg-red-50 p-1.5 rounded-lg"><Trash2 size={16}/></button>
                    </div>
                    <div className="flex justify-between items-center mt-2 pt-2 border-t border-gray-100">
                         <span className="text-[10px] bg-blue-50 text-blue-700 px-1.5 py-0.5 rounded border border-blue-100">{d.source}</span>
                         <span className="font-bold text-blue-600 text-sm">{formatCurrency(d.nominal)}</span>
                    </div>
                 </div>
               ))}
            </div>

           </div>
        )}

        {/* EXPENSE FORM */}
        {activeTab === 'expense' && (
             <div className="space-y-4 md:space-y-6">
             <div className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-gray-50 p-3 rounded-lg border border-gray-200">
                 <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input 
                    type="date"
                    id="date-expense"
                    value={expForm.date} 
                    onChange={e => setExpForm({...expForm, date: e.target.value})} 
                    className={inputClass} 
                    style={{colorScheme: 'light'}}
                    />
                 </div>
                 <div className="col-span-1 md:col-span-2">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Keperluan</label>
                    <input type="text" placeholder="Keperluan" value={expForm.purpose} onChange={e => setExpForm({...expForm, purpose: e.target.value})} className={inputClass} />
                 </div>

                 {/* Nominal Input with Dots */}
                 <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Nominal</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input 
                            type="text"
                            inputMode="numeric"
                            placeholder="0" 
                            value={expForm.nominal} 
