  // --- FETCH DATA (SUPABASE ONLY) ---
  const fetchSupabaseData = async (notifyError = false) => {
    try {
      // a. Fetch Previous Funds
      const { data: prevFunds, error: prevError } = await supabase.from('previous_funds').select('*');
      if (prevError) throw prevError;

      const mappedPrev = prevFunds?.map((item: any) => ({
          ...item,
          createdBy: item.created_by // Map from DB
      })) || [];

      // b. Fetch Weekly Data
      const { data: weekly, error: weeklyError } = await supabase.from('weekly_data').select('*');
      if (weeklyError) throw weeklyError;

      const mappedWeekly = weekly?.map((item: any) => ({
        id: item.id,
        date: item.date,
        week: item.week,
        rt: item.rt,
        grossAmount: item.gross_amount,
        consumptionCut: item.consumption_cut,
        commissionCut: item.commission_cut,
        netAmount: item.net_amount,
        createdBy: item.created_by // Map from DB
      })) || [];

      // c. Fetch Donors
      const { data: donors, error: donorError } = await supabase.from('donors').select('*');
      if (donorError) throw donorError;

      const mappedDonors = donors?.map((item: any) => ({
        ...item,
        createdBy: item.created_by // Map from DB
      })) || [];

      // d. Fetch Expenses
      const { data: expenses, error: expError } = await supabase.from('expenses').select('*');
