        const { data, error } = await supabase
            .from('admin_users')
            .select('id, username')
            .eq('username', u)
            .eq('password', p)
            .single();

        if (error || !data) {
            console.error("Auth failed:", error?.message);
            return false;
        }
        return true;
    } catch (err) {
        console.error("Auth error:", err);
        return false;
    }
