              </h3>
              <div className="bg-white border rounded-lg overflow-hidden shadow-sm">
                  {users.length === 0 ? (
                      <div className="p-4 text-center text-gray-400 text-xs">Belum ada user tambahan.</div>
                  ) : (
                      <ul className="divide-y divide-gray-100">
                          {users.map((user, idx) => (
                              <li key={user.id} className="p-3 md:p-4 flex justify-between items-center hover:bg-gray-50 transition">
                                  <div className="flex items-center gap-2 md:gap-3">
                                      <div className="bg-gray-100 w-6 h-6 md:w-8 md:h-8 flex items-center justify-center rounded-full text-gray-600 font-bold text-[10px] md:text-xs">
                                          {idx + 1}
                                      </div>
                                      <div>
                                          <p className="font-bold text-gray-800 text-xs md:text-sm leading-tight">{user.username}</p>
                                          <p className="text-[9px] md:text-[10px] text-gray-400 leading-tight mt-0.5">
                                            {new Date(user.created_at).toLocaleDateString('id-ID')}
                                          </p>
                                      </div>
                                  </div>
                                  <button 
                                    onClick={() => handleDelete(user.id, user.username)}
                                    className="text-red-500 hover:text-red-700 hover:bg-red-50 p-1.5 md:p-2 rounded transition"
                                    title="Hapus"
                                  >
                                      <Trash2 size={14} className="md:w-4 md:h-4" />
                                  </button>
                              </li>
                          ))}
                      </ul>
                  )}
              </div>
          </div>

      </div>
    </div>
  );
};

export default UserManagementSection;

export interface PreviousFund {
  id: string;
  date: string;
  nominal: number;
  createdBy?: string; // Menambah audit user
}

export interface WeeklyData {
  id: string;
  date: string;
  week: string;
  rt: string;
  grossAmount: number; // Pendapatan Kotor
  consumptionCut: number; // 5%
  commissionCut: number; // 10%
  netAmount: number; // Jumlah Bersih masuk kas
  createdBy?: string; // Menambah audit user
}

export interface DonorData {
  id: string;
  date: string;
  name: string;
  // source: string; // Dihapus
  nominal: number;
  createdBy?: string; // Menambah audit user
}

export interface ExpenseData {
  id: string;
  date: string;
  purpose: string; // Keperluan
  nominal: number;
  createdBy?: string; // Menambah audit user
}

export interface AppData {
  lastUpdated: string; // Tanggal update data real-time
  previousFunds: PreviousFund[];
  weeklyData: WeeklyData[];
  donors: DonorData[];
  expenses: ExpenseData[];
}

export type DataType = 'previous' | 'weekly' | 'donor' | 'expense';

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatDate, formatCurrency, calculateWeeklyCuts } from '../../utils/format';
import Swal from 'sweetalert2';
import { Trash2, Save } from 'lucide-react';

const InputSection: React.FC = () => {
  const { stagedData, addPreviousFund, deletePreviousFund, addWeeklyData, deleteWeeklyData, addDonor, deleteDonor, addExpense, deleteExpense } = useData();
  const [activeTab, setActiveTab] = useState<'previous' | 'weekly' | 'donor' | 'expense'>('previous');

  // Form States - Nominal disimpan sebagai string agar bisa menampilkan format titik (Rp. 1.000.000)
  const [prevForm, setPrevForm] = useState({ date: '', nominal: '' });
  const [weekForm, setWeekForm] = useState({ date: '', week: '', rt: '', gross: '' });
  const [donorForm, setDonorForm] = useState({ date: '', name: '', nominal: '' });
  const [expForm, setExpForm] = useState({ date: '', purpose: '', nominal: '' });

  // 1. Helper: Format tampilan saat mengetik (Visual: 1000000 -> 1.000.000)
  const formatNumberInput = (value: string) => {
    if (!value) return '';
    // Hanya ambil angka
    const rawValue = value.replace(/\D/g, ''); 
    // Format ke string dengan titik (id-ID)
    return new Intl.NumberFormat('id-ID').format(Number(rawValue));
  };

  // 2. Helper: Ubah kembali ke angka murni untuk disimpan ke Database/Context (Data: 1.000.000 -> 1000000)
  const parseNumberInput = (value: string) => {
    if (!value) return 0;
    // Hapus semua titik, lalu jadikan number
    return Number(value.replace(/\./g, ''));
  };

  const confirmSave = (callback: () => void) => {
    Swal.fire({
      title: 'Yakin Ingin disimpan?',
      text: "Data akan masuk ke dashboard Preview",
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Simpan',
      cancelButtonText: 'Cancel'
    }).then((result) => {
      if (result.isConfirmed) {
        callback();
        Swal.fire('Tersimpan!', 'Data berhasil dikirim ke Dashboard Preview.', 'success');
      }
    });
  };

  const confirmDelete = (id: string, deleteFn: (id: string) => void) => {
    Swal.fire({
      title: 'Hapus Data?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'Ya, Hapus',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        deleteFn(id);
        Swal.fire('Berhasil!', 'Data dihapus.', 'success');
      }
    });
  };

  // --- HANDLERS DENGAN PARSING ANGKA ---

  const handleSavePrev = () => {
    if (!prevForm.date || !prevForm.nominal) return;
    confirmSave(() => {
      // Gunakan parseNumberInput agar yang tersimpan adalah angka murni (bisa dijumlahkan)
      addPreviousFund({ date: prevForm.date, nominal: parseNumberInput(prevForm.nominal) });
      setPrevForm({ date: '', nominal: '' });
    });
  };

  const handleSaveWeek = () => {
    if (!weekForm.date || !weekForm.gross) return;
    // Parsing angka murni sebelum perhitungan
    const gross = parseNumberInput(weekForm.gross);
    const { consumption, commission, net } = calculateWeeklyCuts(gross);
    confirmSave(() => {
      addWeeklyData({
        date: weekForm.date,
        week: weekForm.week || 'Minggu 1',
        rt: weekForm.rt || 'RT 01',
        grossAmount: gross,
        consumptionCut: consumption,
        commissionCut: commission,
        netAmount: net
      });
      setWeekForm({ date: '', week: 'Minggu 1', rt: 'RT 01', gross: '' });
    });
  };

  const handleSaveDonor = () => {
    if(!donorForm.name || !donorForm.nominal) return;
    confirmSave(() => {
      addDonor({
        date: donorForm.date,
        name: donorForm.name,
        nominal: parseNumberInput(donorForm.nominal)
      });
      setDonorForm({ date: '', name: '', nominal: '' });
    });
  };

  const handleSaveExp = () => {
    if(!expForm.purpose || !expForm.nominal) return;
    confirmSave(() => {
        addExpense({
            date: expForm.date,
            purpose: expForm.purpose,
            nominal: parseNumberInput(expForm.nominal)
        });
        setExpForm({ date: '', purpose: '', nominal: '' });
    });
  }

  const tabClass = (tab: string) => 
    `flex-1 text-center md:flex-none px-2 py-2 md:px-4 md:py-3 rounded-t-lg font-bold text-xs md:text-sm transition-colors ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`;

  // Common Input Class with thinner focus outline (ring-1)
  const inputClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg px-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm transition-shadow [&::-webkit-calendar-picker-indicator]:cursor-pointer";

  // Input class specifically for Rupiah inputs
  const inputRpClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg pl-8 md:pl-10 pr-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm transition-shadow font-mono tracking-wide";

  return (
