                    <button onClick={() => confirmDelete(d.id, deletePreviousFund)} className="bg-red-50 text-red-600 p-1.5 rounded-lg"><Trash2 size={16}/></button>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* WEEKLY FORM */}
        {activeTab === 'weekly' && (
          <div className="space-y-4 md:space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3 bg-gray-50 p-3 rounded-lg border border-gray-200">
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input 
                    type="date"
