import * as XLSX from 'xlsx';
import { AppData } from '../types';
import { formatDate } from './format';

export const generateExcel = (data: AppData, type: 'weekly' | 'donor' | 'expense' | 'all_income' | 'all_expense') => {
  const wb = XLSX.utils.book_new();

  // Helper untuk membuat sheet dari JSON dan menambahkannya ke workbook
  const addToSheet = (sheetName: string, headers: string[], rowData: any[]) => {
    const wsData = [headers, ...rowData];
    const ws = XLSX.utils.aoa_to_sheet(wsData);

    // Auto-width column sederhana
    const wscols = headers.map(h => ({ wch: h.length + 10 }));
    ws['!cols'] = wscols;

    XLSX.utils.book_append_sheet(wb, ws, sheetName);
  };

  // --- MINGGUAN ---
  if (type === 'weekly' || type === 'all_income') {
    const headers = ['Minggu', 'RT', 'Tanggal', 'Pemasukan Kotor', 'Potongan Konsumsi (5%)', 'Potongan Komisi (10%)', 'Jumlah Bersih'];
    const rows = data.weeklyData.map(item => [
      item.week,
      item.rt,
      formatDate(item.date),
      item.grossAmount,
      item.consumptionCut,
      item.commissionCut,
      item.netAmount
    ]);

    // Tambahkan Baris Total
    const totalRow = [
        'TOTAL', '', '',
        data.weeklyData.reduce((a,b)=>a+b.grossAmount,0),
        data.weeklyData.reduce((a,b)=>a+b.consumptionCut,0),
        data.weeklyData.reduce((a,b)=>a+b.commissionCut,0),
        data.weeklyData.reduce((a,b)=>a+b.netAmount,0)
    ];
    rows.push(totalRow);

    addToSheet("Mingguan", headers, rows);
  }

  // --- DONATUR ---
  if (type === 'donor' || (type === 'all_income' && data.donors.length > 0)) {
    const headers = ['No', 'Tanggal', 'Nama Donatur', 'Nominal'];
    const rows = data.donors.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.name,
      item.nominal
    ]);

    const totalRow = ['', '', 'TOTAL', data.donors.reduce((a,b)=>a+b.nominal,0)];
    rows.push(totalRow);

    addToSheet("Donatur", headers, rows);
  }

  // --- PENGELUARAN ---
  if (type === 'expense' || type === 'all_expense') {
    const headers = ['No', 'Tanggal', 'Keperluan', 'Nominal'];
    const rows = data.expenses.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.purpose,
      item.nominal
    ]);

    const totalRow = ['', '', 'TOTAL', data.expenses.reduce((a,b)=>a+b.nominal,0)];
    rows.push(totalRow);

    addToSheet("Pengeluaran", headers, rows);
  }

  // Tulis File
  XLSX.writeFile(wb, `Laporan_PHBI_${type}_${new Date().toISOString().slice(0,10)}.xlsx`);
};

