import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { AppData } from '../types';
import { formatCurrency, formatDate } from './format';

const KOP_URL = "https://bmcenhkcwuxnclmlcriy.supabase.co/storage/v1/object/sign/image/KOP%20SURAT%20PHBI.jpg?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9iODZjZjM2NS1mNTBmLTQwMmQtYjUwMC00Mjg3YjVlYTgxYzkiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJpbWFnZS9LT1AgU1VSQVQgUEhCSS5qcGciLCJpYXQiOjE3Njg1NTEzNzEsImV4cCI6MTgwMDA4NzM3MX0.9zfrxm6XRn1j3cH_U_ey5zOHZaOOlj4lLboVDUe3n7s";

// Helper untuk memuat gambar menjadi Base64 agar aman di jsPDF
const getBase64ImageFromURL = (url: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "Anonymous";
    img.src = url;
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext("2d");
      ctx?.drawImage(img, 0, 0);
      const dataURL = canvas.toDataURL("image/jpeg");
      resolve(dataURL);
    };
    img.onerror = (error) => {
      reject(error);
    };
  });
};

export const generatePDF = async (data: AppData, type: 'weekly' | 'donor' | 'expense' | 'all_income' | 'all_financial') => {
  const doc = new jsPDF();

  // 1. Load & Draw KOP
  try {
    const kopBase64 = await getBase64ImageFromURL(KOP_URL);
    doc.addImage(kopBase64, 'JPEG', 0, 0, 210, 45); 
  } catch (error) {
    console.error("Gagal memuat KOP Surat", error);
    doc.setFontSize(16);
    doc.text("MASJID JAMI' AL-ISHLAH", 105, 20, { align: 'center' });
  }

  // 2. Tentukan Posisi Awal Tabel (Setelah Kop)
  let startY = 50; 

  // Helper untuk menambah judul section dan cek halaman baru
  const addTitle = (title: string, isFirstSection = false) => {
    // Jika bukan section pertama, kita cek apakah perlu halaman baru atau space tambahan
    if (!isFirstSection) {
        const lastTableY = (doc as any).lastAutoTable?.finalY || startY;
        startY = lastTableY + 15;

        // Jika sisa halaman sedikit, ganti halaman
        if (startY > 250) {
            doc.addPage();
            startY = 20; // Margin atas halaman baru
        }
    }

    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text(title, 105, startY, { align: 'center' });
    startY += 10;
  };

  // --- 1. PREVIOUS FUNDS (Hanya jika All Financial) ---
  if (type === 'all_financial') {
     addTitle('LAPORAN DANA AWAL (PANITIA SEBELUMNYA)', true);

     if (data.previousFunds.length > 0) {
        const rows = data.previousFunds.map((item, idx) => [
            idx + 1,
            formatDate(item.date),
            formatCurrency(item.nominal)
        ]);

        autoTable(doc, {
            startY: startY,
            head: [['No', 'Tanggal', 'Nominal']],
            body: rows,
            theme: 'grid',
            headStyles: { fillColor: [88, 28, 135] }, // Purple
            foot: [['', 'TOTAL', formatCurrency(data.previousFunds.reduce((a,b)=>a+b.nominal,0))]]
        });
     } else {
         doc.setFontSize(10);
         doc.setFont("helvetica", "italic");
         doc.text("(Tidak ada data dana awal)", 105, startY + 5, { align: 'center' });
         (doc as any).lastAutoTable = { finalY: startY + 10 }; // Fake Y update
     }
  }

  // --- 2. WEEKLY DATA ---
  if (type === 'weekly' || type === 'all_income' || type === 'all_financial') {
    // Jika all_financial, ini bukan section pertama (previous funds duluan)
    addTitle('LAPORAN PEMASUKAN MINGGUAN (PER RT)', type !== 'all_financial');

    const rows = data.weeklyData.map(item => [
      item.week,
      item.rt,
      formatDate(item.date),
      formatCurrency(item.grossAmount),
      formatCurrency(item.consumptionCut),
      formatCurrency(item.commissionCut),
      formatCurrency(item.netAmount)
    ]);

    autoTable(doc, {
      startY: startY,
      head: [['Minggu', 'RT', 'Tanggal', 'Kotor', 'Konsumsi 5%', 'Komisi 10%', 'Bersih']],
      body: rows,
      theme: 'grid',
      headStyles: { fillColor: [6, 78, 59] }, // emerald-900
      foot: [['TOTAL', '', '', 
        formatCurrency(data.weeklyData.reduce((a,b)=>a+b.grossAmount,0)),
        formatCurrency(data.weeklyData.reduce((a,b)=>a+b.consumptionCut,0)),
        formatCurrency(data.weeklyData.reduce((a,b)=>a+b.commissionCut,0)),
        formatCurrency(data.weeklyData.reduce((a,b)=>a+b.netAmount,0))
      ]]
    });
  }

  // --- 3. DONOR DATA ---
  if (type === 'donor' || type === 'all_income' || type === 'all_financial') {
    addTitle('LAPORAN PEMASUKAN DONATUR', type === 'donor');

    const rows = data.donors.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.name,
      formatCurrency(item.nominal)
    ]);

    autoTable(doc, {
      startY: startY,
      head: [['No', 'Tanggal', 'Nama', 'Nominal']],
      body: rows,
      theme: 'grid',
      headStyles: { fillColor: [4, 120, 87] }, // emerald-700
      foot: [['', '', 'TOTAL', formatCurrency(data.donors.reduce((a,b)=>a+b.nominal,0))]]
    });
  }

  // --- 4. EXPENSE DATA ---
  if (type === 'expense' || type === 'all_financial') {
    addTitle('LAPORAN PENGELUARAN DANA', type === 'expense');

    const rows = data.expenses.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.purpose,
      formatCurrency(item.nominal)
    ]);

    autoTable(doc, {
      startY: startY,
      head: [['No', 'Tanggal', 'Keperluan', 'Nominal']],
      body: rows,
      theme: 'grid',
      headStyles: { fillColor: [185, 28, 28] }, // red-700
      // Revisi: Footer warna merah juga
      footStyles: { fillColor: [185, 28, 28], textColor: [255, 255, 255], fontStyle: 'bold' },
      foot: [['', '', 'TOTAL', formatCurrency(data.expenses.reduce((a,b)=>a+b.nominal,0))]]
    });
  }

  // --- 5. REKAPITULASI (Only for All Financial) ---
  if (type === 'all_financial') {
      const totalPrev = data.previousFunds.reduce((a,b)=>a+b.nominal,0);
      const totalWeekly = data.weeklyData.reduce((a,b)=>a+b.netAmount,0);
      const totalDonor = data.donors.reduce((a,b)=>a+b.nominal,0);
      const totalIncome = totalPrev + totalWeekly + totalDonor;
      const totalExpense = data.expenses.reduce((a,b)=>a+b.nominal,0);
      const balance = totalIncome - totalExpense;

      // Cek halaman baru untuk rekap
      const lastTableY = (doc as any).lastAutoTable?.finalY || startY;
      let rekapY = lastTableY + 15;
      if (rekapY > 230) {
          doc.addPage();
          rekapY = 20;
      }

      doc.setFontSize(14);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(0, 0, 0);
      doc.text("REKAPITULASI AKHIR", 105, rekapY, { align: 'center' });

      autoTable(doc, {
          startY: rekapY + 5,
          head: [['KETERANGAN', 'NOMINAL']],
          body: [
              ['Total Dana Awal', formatCurrency(totalPrev)],
              ['Total Pemasukan Mingguan (Bersih)', formatCurrency(totalWeekly)],
              ['Total Pemasukan Donatur', formatCurrency(totalDonor)],
              [{ content: 'TOTAL SEMUA PEMASUKAN', styles: { fontStyle: 'bold', fillColor: [240, 253, 244] } }, { content: formatCurrency(totalIncome), styles: { fontStyle: 'bold', textColor: [6, 78, 59] } }],
              [{ content: 'TOTAL PENGELUARAN', styles: { fontStyle: 'bold', fillColor: [254, 242, 242] } }, { content: formatCurrency(totalExpense), styles: { fontStyle: 'bold', textColor: [185, 28, 28] } }],
              [{ content: 'SISA SALDO KAS', styles: { fontStyle: 'bold', fillColor: [255, 251, 235], fontSize: 12 } }, { content: formatCurrency(balance), styles: { fontStyle: 'bold', fontSize: 12, textColor: [0, 0, 0] } }]
          ],
          theme: 'grid',
          headStyles: { fillColor: [55, 65, 81], halign: 'center' },
          columnStyles: {
              1: { halign: 'right' }
          }
      });
  }

  // Footer for all
  const pageCount = doc.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setFont("helvetica", "italic");
    doc.setTextColor(100);
    doc.text(`Dicetak pada: ${new Date().toLocaleString('id-ID')}`, 15, doc.internal.pageSize.height - 10);
    doc.text(`Hal ${i} dari ${pageCount}`, 195, doc.internal.pageSize.height - 10, { align: 'right' });
  }

  doc.save(`Laporan_PHBI_${type}_${new Date().toISOString().slice(0,10)}.pdf`);
};

import * as XLSX from 'xlsx';
import { AppData } from '../types';
import { formatDate } from './format';

export const generateExcel = (data: AppData, type: 'weekly' | 'donor' | 'expense' | 'all_income' | 'all_financial') => {
  const wb = XLSX.utils.book_new();

  // Helper untuk membuat sheet dari JSON dan menambahkannya ke workbook
  const addToSheet = (sheetName: string, headers: string[], rowData: any[]) => {
    const wsData = [headers, ...rowData];
    const ws = XLSX.utils.aoa_to_sheet(wsData);

    // Auto-width column sederhana
    const wscols = headers.map(h => ({ wch: h.length + 10 }));
    ws['!cols'] = wscols;

    XLSX.utils.book_append_sheet(wb, ws, sheetName);
  };

  // --- PREVIOUS FUNDS (Dana Awal) ---
  if (type === 'all_financial') {
      const headers = ['No', 'Tanggal', 'Nominal'];
      const rows = data.previousFunds.map((item, idx) => [
          idx + 1,
          formatDate(item.date),
          item.nominal
      ]);
      const totalRow = ['', 'TOTAL', data.previousFunds.reduce((a,b)=>a+b.nominal,0)];
      rows.push(totalRow);
      addToSheet("Dana Awal", headers, rows);
  }

  // --- MINGGUAN ---
  if (type === 'weekly' || type === 'all_income' || type === 'all_financial') {
    const headers = ['Minggu', 'RT', 'Tanggal', 'Pemasukan Kotor', 'Potongan Konsumsi (5%)', 'Potongan Komisi (10%)', 'Jumlah Bersih'];
    const rows = data.weeklyData.map(item => [
      item.week,
      item.rt,
      formatDate(item.date),
      item.grossAmount,
      item.consumptionCut,
      item.commissionCut,
      item.netAmount
    ]);

    // Tambahkan Baris Total
    const totalRow = [
        'TOTAL', '', '',
        data.weeklyData.reduce((a,b)=>a+b.grossAmount,0),
        data.weeklyData.reduce((a,b)=>a+b.consumptionCut,0),
        data.weeklyData.reduce((a,b)=>a+b.commissionCut,0),
        data.weeklyData.reduce((a,b)=>a+b.netAmount,0)
    ];
    rows.push(totalRow);

    addToSheet("Mingguan", headers, rows);
  }

  // --- DONATUR ---
  if (type === 'donor' || type === 'all_income' || type === 'all_financial') {
    const headers = ['No', 'Tanggal', 'Nama Donatur', 'Nominal'];
    const rows = data.donors.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.name,
      item.nominal
    ]);

    const totalRow = ['', '', 'TOTAL', data.donors.reduce((a,b)=>a+b.nominal,0)];
    rows.push(totalRow);

    addToSheet("Donatur", headers, rows);
  }

  // --- PENGELUARAN ---
  if (type === 'expense' || type === 'all_financial') {
    const headers = ['No', 'Tanggal', 'Keperluan', 'Nominal'];
    const rows = data.expenses.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.purpose,
      item.nominal
    ]);

    const totalRow = ['', '', 'TOTAL', data.expenses.reduce((a,b)=>a+b.nominal,0)];
    rows.push(totalRow);

    addToSheet("Pengeluaran", headers, rows);
  }

  // --- REKAPITULASI (All Financial Only) ---
  if (type === 'all_financial') {
    const totalPrev = data.previousFunds.reduce((a,b)=>a+b.nominal,0);
    const totalWeekly = data.weeklyData.reduce((a,b)=>a+b.netAmount,0);
    const totalDonor = data.donors.reduce((a,b)=>a+b.nominal,0);
    const totalIncome = totalPrev + totalWeekly + totalDonor;
    const totalExpense = data.expenses.reduce((a,b)=>a+b.nominal,0);
    const balance = totalIncome - totalExpense;

    const headers = ['KATEGORI', 'TOTAL NOMINAL'];
    const rows = [
        ['Total Dana Awal', totalPrev],
        ['Total Pemasukan Mingguan (Bersih)', totalWeekly],
        ['Total Pemasukan Donatur', totalDonor],
        ['TOTAL SEMUA PEMASUKAN', totalIncome],
        ['TOTAL PENGELUARAN', totalExpense],
        ['SISA SALDO KAS', balance]
    ];
    addToSheet("Rekapitulasi", headers, rows);
  }

  // Tulis File
  XLSX.writeFile(wb, `Laporan_PHBI_${type}_${new Date().toISOString().slice(0,10)}.xlsx`);
};

