  getAdminUsers: () => Promise<any[]>;
  deleteAdminUser: (id: string, masterPass: string) => Promise<boolean>;
  // CRUD Actions (Effect Staged Data)
  addPreviousFund: (data: Omit<PreviousFund, 'id'>) => void;
  updatePreviousFund: (id: string, data: Partial<PreviousFund>) => void; // NEW
  deletePreviousFund: (id: string) => void;

  addWeeklyData: (data: Omit<WeeklyData, 'id'>) => void;
  updateWeeklyData: (id: string, data: Partial<WeeklyData>) => void; // NEW
  deleteWeeklyData: (id: string) => void;

  addDonor: (data: Omit<DonorData, 'id'>) => void;
  updateDonor: (id: string, data: Partial<DonorData>) => void; // NEW
  deleteDonor: (id: string) => void;

  addExpense: (data: Omit<ExpenseData, 'id'>) => void;
  updateExpense: (id: string, data: Partial<ExpenseData>) => void; // NEW
  deleteExpense: (id: string) => void;

  // System Actions
  publishData: (updateDate: string) => void;
  resetData: (type: 'all' | 'previous' | 'weekly' | 'donor' | 'expense') => void;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

const initialData: AppData = {
  lastUpdated: new Date().toISOString(),
  previousFunds: [],
  weeklyData: [],
  donors: [],
  expenses: [],
};

// --- PASSWORD ADMIN PUSAT (KUNCI UTAMA) ---
const MASTER_ADMIN_PASSWORD = "ALISHLAH2026"; 

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [publishedData, setPublishedData] = useState<AppData>(initialData);
  const [stagedData, setStagedData] = useState<AppData>(initialData);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<string | null>(null);

  // --- FETCH DATA (SUPABASE ONLY) ---
  const fetchSupabaseData = async (notifyError = false) => {
    try {
      // a. Fetch Previous Funds
      const { data: prevFunds, error: prevError } = await supabase.from('previous_funds').select('*');
      if (prevError) throw prevError;

      const mappedPrev = prevFunds?.map((item: any) => ({
          ...item,
          createdBy: item.created_by // Map from DB
      })) || [];

      // b. Fetch Weekly Data
      const { data: weekly, error: weeklyError } = await supabase.from('weekly_data').select('*');
      if (weeklyError) throw weeklyError;

      const mappedWeekly = weekly?.map((item: any) => ({
        id: item.id,
        date: item.date,
        week: item.week,
        rt: item.rt,
        grossAmount: item.gross_amount,
        consumptionCut: item.consumption_cut,
        commissionCut: item.commission_cut,
        netAmount: item.net_amount,
        createdBy: item.created_by // Map from DB
      })) || [];

      // c. Fetch Donors
      const { data: donors, error: donorError } = await supabase.from('donors').select('*');
      if (donorError) throw donorError;

      const mappedDonors = donors?.map((item: any) => ({
        ...item,
        createdBy: item.created_by // Map from DB
      })) || [];

      // d. Fetch Expenses
      const { data: expenses, error: expError } = await supabase.from('expenses').select('*');
      if (expError) throw expError;

      const mappedExpenses = expenses?.map((item: any) => ({
        ...item,
        createdBy: item.created_by // Map from DB
      })) || [];

      // e. Fetch Meta
      const { data: meta, error: metaError } = await supabase.from('app_meta').select('*').limit(1).single();

      setPublishedData({
        lastUpdated: meta?.last_updated || new Date().toISOString(),
        previousFunds: mappedPrev,
        weeklyData: mappedWeekly,
        donors: mappedDonors,
        expenses: mappedExpenses
      });

    } catch (error: any) {
      console.error("Error fetching data from Supabase:", error);

      if (notifyError || isLoggedIn) {
          Swal.fire({
            icon: 'error',
            title: 'Gagal Mengambil Data',
            text: 'Terjadi kesalahan saat menghubungkan ke Database Supabase.',
            footer: error.message
          });
      }
    }
  };

  // Load initial data
  useEffect(() => {
    fetchSupabaseData(false);

    // Load Staged Data from LocalStorage (Draft / Admin Work in Progress only)
    const storedStaged = localStorage.getItem('phbi_staged_data');
    if (storedStaged) setStagedData(JSON.parse(storedStaged));
  }, []);

  // Persist Staged Data whenever it changes
  useEffect(() => {
    localStorage.setItem('phbi_staged_data', JSON.stringify(stagedData));
  }, [stagedData]);

  const login = (username: string) => {
    setIsLoggedIn(true);
    setCurrentUser(username);
    // Refresh data from Supabase upon login
    setTimeout(() => fetchSupabaseData(true), 500);
  };

  const logout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  // --- AUTHENTICATION LOGIC (SUPABASE TABLE) ---
  const verifyUser = async (u: string, p: string): Promise<boolean> => {
    try {
        // Cek ke tabel admin_users di Supabase
        const { data, error } = await supabase
            .from('admin_users')
            .select('id, username')
            .eq('username', u)
            .eq('password', p)
            .single();

        if (error || !data) {
            console.error("Auth failed:", error?.message);
            return false;
        }
        return true;
    } catch (err) {
        console.error("Auth error:", err);
        return false;
    }
  };

  // --- ADMIN MANAGEMENT LOGIC ---
  const addAdminUser = async (newUsername: string, newPassword: string, masterPass: string): Promise<boolean> => {
      // 1. Validasi Master Password
      if (masterPass !== MASTER_ADMIN_PASSWORD) {
          Swal.fire('Akses Ditolak', 'Password Admin Pusat Salah!', 'error');
          return false;
      }

      try {
          // 2. Cek apakah username sudah ada
          const { data: existing } = await supabase
              .from('admin_users')
              .select('id')
              .eq('username', newUsername)
              .single();

          if (existing) {
              Swal.fire('Gagal', 'Username sudah terdaftar.', 'warning');
              return false;
          }

          // 3. Insert User Baru
          const { error } = await supabase
              .from('admin_users')
              .insert({ username: newUsername, password: newPassword });

          if (error) throw error;

          return true;
      } catch (error: any) {
          console.error(error);
          Swal.fire('Error', error.message, 'error');
          return false;
      }
  };

  const getAdminUsers = async () => {
      const { data, error } = await supabase
          .from('admin_users')
          .select('id, username, created_at')
          .order('created_at', { ascending: false });

      if (error) {
          console.error(error);
          return [];
      }
      return data || [];
  };

  const deleteAdminUser = async (id: string, masterPass: string): Promise<boolean> => {
      if (masterPass !== MASTER_ADMIN_PASSWORD) {
          Swal.fire('Akses Ditolak', 'Password Admin Pusat Salah!', 'error');
          return false;
      }
      const { error } = await supabase.from('admin_users').delete().eq('id', id);
      if (error) {
          Swal.fire('Error', error.message, 'error');
          return false;
      }
      return true;
  };

  // --- CRUD Operations (Operate on Staged Data - Client Side Only) ---
  // AUTOMATICALLY ATTACH CURRENT USERNAME TO DATA

  const addPreviousFund = (item: Omit<PreviousFund, 'id'>) => {
    const newItem = { 
        ...item, 
        id: crypto.randomUUID(),
        createdBy: currentUser || 'Admin' 
    };
    setStagedData(prev => ({ ...prev, previousFunds: [...prev.previousFunds, newItem] }));
  };
  const updatePreviousFund = (id: string, data: Partial<PreviousFund>) => {
    setStagedData(prev => ({
        ...prev,
        previousFunds: prev.previousFunds.map(item => item.id === id ? { ...item, ...data } : item)
    }));
  };
  const deletePreviousFund = (id: string) => {
    setStagedData(prev => ({ ...prev, previousFunds: prev.previousFunds.filter(i => i.id !== id) }));
  };


  const addWeeklyData = (item: Omit<WeeklyData, 'id'>) => {
    const newItem = { 
        ...item, 
        id: crypto.randomUUID(),
        createdBy: currentUser || 'Admin'
    };
    setStagedData(prev => ({ ...prev, weeklyData: [...prev.weeklyData, newItem] }));
  };
  const updateWeeklyData = (id: string, data: Partial<WeeklyData>) => {
    setStagedData(prev => ({
        ...prev,
        weeklyData: prev.weeklyData.map(item => item.id === id ? { ...item, ...data } : item)
    }));
  };
  const deleteWeeklyData = (id: string) => {
    setStagedData(prev => ({ ...prev, weeklyData: prev.weeklyData.filter(i => i.id !== id) }));
  };


  const addDonor = (item: Omit<DonorData, 'id'>) => {
    const newItem = { 
        ...item, 
        id: crypto.randomUUID(),
        createdBy: currentUser || 'Admin'
    };
    setStagedData(prev => ({ ...prev, donors: [...prev.donors, newItem] }));
  };
  const updateDonor = (id: string, data: Partial<DonorData>) => {
    setStagedData(prev => ({
        ...prev,
        donors: prev.donors.map(item => item.id === id ? { ...item, ...data } : item)
    }));
  };
  const deleteDonor = (id: string) => {
    setStagedData(prev => ({ ...prev, donors: prev.donors.filter(i => i.id !== id) }));
  };


  const addExpense = (item: Omit<ExpenseData, 'id'>) => {
    const newItem = { 
        ...item, 
        id: crypto.randomUUID(),
        createdBy: currentUser || 'Admin'
    };
    setStagedData(prev => ({ ...prev, expenses: [...prev.expenses, newItem] }));
  };
  const updateExpense = (id: string, data: Partial<ExpenseData>) => {
    setStagedData(prev => ({
        ...prev,
        expenses: prev.expenses.map(item => item.id === id ? { ...item, ...data } : item)
    }));
  };
  const deleteExpense = (id: string) => {
    setStagedData(prev => ({ ...prev, expenses: prev.expenses.filter(i => i.id !== id) }));
  };

  // --- System Actions ---

  const publishData = async (updateDate: string) => {
    Swal.fire({
      title: 'Menyimpan ke Database...',
      allowOutsideClick: false,
      didOpen: () => { Swal.showLoading(); }
    });

    // MODE ONLINE (SUPABASE)
    try {
      // 1. Insert Previous Funds
      if (stagedData.previousFunds.length > 0) {
        // Map camelCase to snake_case for DB
        const payload = stagedData.previousFunds.map(({ id, createdBy, ...rest }) => ({
            ...rest,
            created_by: createdBy
        }));

        const { error } = await supabase.from('previous_funds').insert(payload);
        if (error) throw error;
      }

      // 2. Insert Weekly Data
      if (stagedData.weeklyData.length > 0) {
        const weeklyPayload = stagedData.weeklyData.map(item => ({
          date: item.date,
          week: item.week,
          rt: item.rt,
          gross_amount: item.grossAmount,
          consumption_cut: item.consumptionCut,
          commission_cut: item.commissionCut,
          net_amount: item.netAmount,
          created_by: item.createdBy // Send to DB
        }));
        const { error } = await supabase.from('weekly_data').insert(weeklyPayload);
        if (error) throw error;
      }

      // 3. Insert Donors
      if (stagedData.donors.length > 0) {
        const payload = stagedData.donors.map(({ id, createdBy, ...rest }) => ({
            ...rest,
            created_by: createdBy
        }));
        const { error } = await supabase.from('donors').insert(payload);
        if (error) throw error;
      }

      // 4. Insert Expenses
      if (stagedData.expenses.length > 0) {
        const payload = stagedData.expenses.map(({ id, createdBy, ...rest }) => ({
            ...rest,
            created_by: createdBy
        }));
        const { error } = await supabase.from('expenses').insert(payload);
        if (error) throw error;
      }

      // 5. Update Meta
      const { error: metaError } = await supabase
        .from('app_meta')
        .update({ last_updated: updateDate })
        .gt('id', 0); 

      if (metaError) {
         await supabase.from('app_meta').insert({ last_updated: updateDate });
      }

      // 6. Clear Staged & Refresh
      setStagedData(initialData);
      await fetchSupabaseData(true);

      Swal.fire({
        icon: 'success',
        title: 'Sukses',
        text: 'Data berhasil disimpan ke database Supabase beserta jejak audit user.',
        confirmButtonColor: '#047857'
      });

    } catch (error: any) {
      console.error(error);
      Swal.fire({
        icon: 'error',
        title: 'Gagal Menyimpan',
        text: error.message || 'Terjadi kesalahan koneksi.',
      });
    }
  };

  const resetData = async (type: 'all' | 'previous' | 'weekly' | 'donor' | 'expense') => {
    // 1. Reset Local Staging first (Draft Admin)
    if (type === 'all') {
      setStagedData(initialData);
    } else {
      const keyMap: Record<string, keyof AppData> = {
        'previous': 'previousFunds',
        'weekly': 'weeklyData',
        'donor': 'donors',
        'expense': 'expenses'
      };
      const key = keyMap[type];
      // @ts-ignore
      setStagedData(prev => ({ ...prev, [key]: [] }));
    }

    // 2. Handle Published Data Reset (SUPABASE)
    Swal.fire({
        title: 'Mereset Database...',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
    });

    try {
        if (type === 'all') {
            await supabase.from('previous_funds').delete().neq('id', '00000000-0000-0000-0000-000000000000'); 
            await supabase.from('weekly_data').delete().neq('id', '00000000-0000-0000-0000-000000000000');
            await supabase.from('donors').delete().neq('id', '00000000-0000-0000-0000-000000000000');
            await supabase.from('expenses').delete().neq('id', '00000000-0000-0000-0000-000000000000');
        } else {
            // Map type to table name
            const tableMap: Record<string, string> = {
                'previous': 'previous_funds',
                'weekly': 'weekly_data',
                'donor': 'donors',
                'expense': 'expenses'
            };
            const tableName = tableMap[type];
            if (tableName) {
                const { error } = await supabase.from(tableName).delete().neq('id', '00000000-0000-0000-0000-000000000000');
                if (error) throw error;
            }
        }

        await fetchSupabaseData(true); 
        Swal.fire('Berhasil', 'Data di Database Supabase telah direset/dihapus.', 'success');
    } catch (error: any) {
        console.error(error);
        Swal.fire('Error', 'Gagal mereset database: ' + error.message, 'error');
    }
  };

  return (
    <DataContext.Provider value={{
      publishedData,
      stagedData,
      isLoggedIn,
      currentUser,
      login,
      logout,
      verifyUser,
      addAdminUser,
      getAdminUsers,
      deleteAdminUser,
      addPreviousFund,
      updatePreviousFund,
      deletePreviousFund,
      addWeeklyData,
      updateWeeklyData,
      deleteWeeklyData,
      addDonor,
      updateDonor,
      deleteDonor,
      addExpense,
      updateExpense,
      deleteExpense,
      publishData,
      resetData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatDate, formatCurrency, calculateWeeklyCuts } from '../../utils/format';
import Swal from 'sweetalert2';
import { Trash2, Save, Pencil, XCircle } from 'lucide-react';

const InputSection: React.FC = () => {
  const { 
    stagedData, 
    addPreviousFund, updatePreviousFund, deletePreviousFund, 
    addWeeklyData, updateWeeklyData, deleteWeeklyData, 
    addDonor, updateDonor, deleteDonor, 
    addExpense, updateExpense, deleteExpense 
  } = useData();

  const [activeTab, setActiveTab] = useState<'previous' | 'weekly' | 'donor' | 'expense'>('previous');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form States - Nominal disimpan sebagai string agar bisa menampilkan format titik (Rp. 1.000.000)
  const [prevForm, setPrevForm] = useState({ date: '', nominal: '' });
  const [weekForm, setWeekForm] = useState({ date: '', week: 'Minggu ke-1', rt: 'RT 01', gross: '' });
  const [donorForm, setDonorForm] = useState({ date: '', name: '', nominal: '' });
  const [expForm, setExpForm] = useState({ date: '', purpose: '', nominal: '' });

  // 1. Helper: Format tampilan saat mengetik (Visual: 1000000 -> 1.000.000)
  const formatNumberInput = (value: string | number) => {
    if (!value) return '';
    const valString = value.toString();
    // Hanya ambil angka
    const rawValue = valString.replace(/\D/g, ''); 
    // Format ke string dengan titik (id-ID)
    return new Intl.NumberFormat('id-ID').format(Number(rawValue));
  };

  // 2. Helper: Ubah kembali ke angka murni untuk disimpan ke Database/Context (Data: 1.000.000 -> 1000000)
  const parseNumberInput = (value: string) => {
    if (!value) return 0;
    // Hapus semua titik, lalu jadikan number
    return Number(value.replace(/\./g, ''));
  };

  // Helper untuk Reset Form dan Mode Editing
  const cancelEdit = () => {
    setEditingId(null);
    setPrevForm({ date: '', nominal: '' });
    setWeekForm({ date: '', week: 'Minggu ke-1', rt: 'RT 01', gross: '' });
    setDonorForm({ date: '', name: '', nominal: '' });
    setExpForm({ date: '', purpose: '', nominal: '' });
  };

  const confirmAction = (title: string, text: string, callback: () => void) => {
    Swal.fire({
      title: title,
      text: text,
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Lanjutkan',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        callback();
        Swal.fire('Berhasil!', 'Data telah disimpan.', 'success');
      }
    });
  };

  const confirmDelete = (id: string, deleteFn: (id: string) => void) => {
    Swal.fire({
      title: 'Hapus Data?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'Ya, Hapus',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        deleteFn(id);
        if (editingId === id) cancelEdit(); // Reset form jika data yang sedang diedit dihapus
        Swal.fire('Berhasil!', 'Data dihapus.', 'success');
      }
    });
  };

  // --- HANDLERS DENGAN VALIDASI & UPDATE ---

  // 1. PREVIOUS FUNDS
  const handleSavePrev = () => {
    if (!prevForm.date || !prevForm.nominal) return;
    const nominal = parseNumberInput(prevForm.nominal);

    if (editingId) {
       confirmAction('Update Data?', 'Apakah Anda yakin ingin mengubah data ini?', () => {
         updatePreviousFund(editingId, { date: prevForm.date, nominal: nominal });
         cancelEdit();
       });
    } else {
       confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
         addPreviousFund({ date: prevForm.date, nominal: nominal });
         cancelEdit();
       });
    }
  };

  const handleEditPrev = (data: any) => {
    setEditingId(data.id);
    setPrevForm({ date: data.date, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 2. WEEKLY DATA (DENGAN VALIDASI DUPLIKASI)
  const handleSaveWeek = () => {
    if (!weekForm.date || !weekForm.gross) return;

    // VALIDASI DUPLIKASI: Cek apakah RT dan Minggu sudah ada di stagedData
    // Jika sedang edit, abaikan pengecekan terhadap ID diri sendiri
    const existing = stagedData.weeklyData.find(
        d => d.week === weekForm.week && d.rt === weekForm.rt && d.id !== editingId
    );

    if (existing) {
        Swal.fire({
            title: 'Gagal Menyimpan',
            text: `Data untuk ${weekForm.week} dan ${weekForm.rt} sudah ada di daftar!`,
            icon: 'error',
            confirmButtonColor: '#d33'
        });
        return; // Hentikan proses
    }

    const gross = parseNumberInput(weekForm.gross);
    const { consumption, commission, net } = calculateWeeklyCuts(gross);

    const payload = {
        date: weekForm.date,
        week: weekForm.week,
        rt: weekForm.rt,
        grossAmount: gross,
        consumptionCut: consumption,
        commissionCut: commission,
        netAmount: net
    };

    if (editingId) {
        confirmAction('Update Data Mingguan?', 'Apakah Anda yakin ingin mengubah data ini?', () => {
            updateWeeklyData(editingId, payload);
            cancelEdit();
        });
    } else {
        confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
            addWeeklyData(payload);
            cancelEdit();
        });
    }
  };

  const handleEditWeek = (data: any) => {
    setEditingId(data.id);
    setWeekForm({ 
        date: data.date, 
        week: data.week, 
        rt: data.rt, 
        gross: formatNumberInput(data.grossAmount) 
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };


  // 3. DONOR DATA
  const handleSaveDonor = () => {
    if(!donorForm.name || !donorForm.nominal) return;
    const nominal = parseNumberInput(donorForm.nominal);

    if (editingId) {
        confirmAction('Update Data Donatur?', 'Apakah Anda yakin ingin mengubah data ini?', () => {
            updateDonor(editingId, { date: donorForm.date, name: donorForm.name, nominal: nominal });
            cancelEdit();
        });
    } else {
        confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
            addDonor({ date: donorForm.date, name: donorForm.name, nominal: nominal });
            cancelEdit();
        });
    }
  };

  const handleEditDonor = (data: any) => {
    setEditingId(data.id);
    setDonorForm({ date: data.date, name: data.name, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };


  // 4. EXPENSE DATA
  const handleSaveExp = () => {
    if(!expForm.purpose || !expForm.nominal) return;
    const nominal = parseNumberInput(expForm.nominal);

    if (editingId) {
        confirmAction('Update Pengeluaran?', 'Apakah Anda yakin ingin mengubah data ini?', () => {
            updateExpense(editingId, { date: expForm.date, purpose: expForm.purpose, nominal: nominal });
            cancelEdit();
        });
    } else {
        confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
            addExpense({ date: expForm.date, purpose: expForm.purpose, nominal: nominal });
            cancelEdit();
        });
    }
  };

  const handleEditExp = (data: any) => {
    setEditingId(data.id);
    setExpForm({ date: data.date, purpose: data.purpose, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };


  // --- UI HELPERS ---
  const tabClass = (tab: string) => 
    `flex-1 text-center md:flex-none px-2 py-2 md:px-4 md:py-3 rounded-t-lg font-bold text-xs md:text-sm transition-colors ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`;

  const inputClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg px-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm transition-shadow [&::-webkit-calendar-picker-indicator]:cursor-pointer";
  const inputRpClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg pl-8 md:pl-10 pr-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm transition-shadow font-mono tracking-wide";
