import React, { useState } from 'react';
import { DataProvider, useData } from './context/DataContext';
import Header from './components/Header';
import Footer from './components/Footer';
import PublicHome from './pages/PublicHome';
import AdminDashboard from './pages/admin/AdminDashboard';
import Modal from './components/ui/Modal';
import Swal from 'sweetalert2';
import { Eye, EyeOff, UserPlus } from 'lucide-react';

// Inner component to access context
const MainContent: React.FC = () => {
  const { isLoggedIn, login, verifyUser } = useData();
  const [isLoginModalOpen, setIsLoginModalOpen] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);

  const handleLoginSubmit = async () => {
    // 1. Validasi Kolom Wajib Diisi
    if (!username || !password) {
      Swal.fire({
        icon: 'warning',
        title: 'Input Belum Lengkap',
        text: 'Mohon lengkapi Username dan Password untuk masuk.',
        confirmButtonColor: '#d4af37' // Gold
      });
      return;
    }

    setIsLoading(true);

    try {
      // 2. Verifikasi Akun ke Database (Async)
      const isValid = await verifyUser(username, password);

      if (isValid) {
        login(username); // Set State Login Sukses
        setIsLoginModalOpen(false);
        // Reset form
        setUsername('');
        setPassword('');

        // 3. Ucapan Selamat Datang
        Swal.fire({
          icon: 'success',
          title: `Selamat Datang, ${username}!`,
          text: 'Anda berhasil masuk ke Panel Admin.',
          showConfirmButton: false,
          timer: 2000
        });
      } else {
        // 4. Gagal Login & Reset Form
        // Jangan reset username agar user tidak perlu ngetik ulang jika typo
        setPassword(''); 
        Swal.fire({
          icon: 'error',
          title: 'Gagal Masuk',
          text: 'Username atau Password salah. Silakan periksa kembali.',
          confirmButtonColor: '#064e3b'
        });
      }
    } catch (error) {
      console.error(error);
      Swal.fire({
        icon: 'error',
        title: 'Kesalahan Sistem',
        text: 'Terjadi gangguan koneksi ke server. Silakan coba lagi nanti.',
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleRegisterClick = () => {
    Swal.fire({
      title: 'Informasi Pendaftaran',
      text: 'Untuk pembuatan akun Admin baru, silakan hubungi Ketua Panitia atau Admin Pusat.',
      icon: 'info',
      confirmButtonText: 'Baik, Mengerti',
      confirmButtonColor: '#2563eb' // Blue
    });
  };

  if (isLoggedIn) {
    return <AdminDashboard />;
  }

  return (
    <div className="flex flex-col min-h-screen font-sans">
      <Header onLoginClick={() => setIsLoginModalOpen(true)} />

      <main className="flex-grow bg-gray-50">
        <PublicHome />
      </main>

      <Footer />

      {/* Login Modal */}
      {isLoginModalOpen && (
        <Modal title="Masuk Admin" onClose={() => setIsLoginModalOpen(false)}>
           <div className="space-y-3 md:space-y-5">
              <div>
                <label className="block text-xs md:text-sm font-semibold text-gray-700 mb-1">Username</label>
                <input 
                  type="text" 
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  className="w-full bg-white border border-gray-300 text-gray-900 rounded-lg px-3 py-2 md:px-4 md:py-3 text-xs md:text-sm focus:ring-1 focus:ring-primary focus:border-primary outline-none shadow-sm transition"
                  placeholder="Masukkan Username"
                  disabled={isLoading}
                />
              </div>
              <div>
                <label className="block text-xs md:text-sm font-semibold text-gray-700 mb-1">Password</label>
                <div className="relative">
                  <input 
                    type={showPassword ? "text" : "password"} 
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="w-full bg-white border border-gray-300 text-gray-900 rounded-lg px-3 py-2 md:px-4 md:py-3 pr-8 md:pr-10 text-xs md:text-sm focus:ring-1 focus:ring-primary focus:border-primary outline-none shadow-sm transition"
                    placeholder="Masukkan Password"
                    disabled={isLoading}
                  />
                  {/* Icon Mata */}
                  <button 
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-2 md:right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-primary transition"
                    type="button"
                  >
                    {showPassword ? <EyeOff size={16} className="md:w-5 md:h-5" /> : <Eye size={16} className="md:w-5 md:h-5" />}
                  </button>
                </div>
              </div>

              <div className="flex flex-col gap-2 md:gap-3 pt-2">
                <div className="flex gap-2 md:gap-3">
                  <button 
                    onClick={() => setIsLoginModalOpen(false)}
                    className="flex-1 bg-gray-100 text-gray-700 py-2 md:py-3 rounded-lg hover:bg-gray-200 font-bold border border-gray-300 transition text-xs md:text-sm"
                    disabled={isLoading}
                  >
                    Batal
                  </button>
                  <button 
                    onClick={handleLoginSubmit}
                    disabled={isLoading}
                    className="flex-1 bg-primary text-white py-2 md:py-3 rounded-lg hover:bg-emerald-800 font-bold shadow-md transition text-xs md:text-sm flex justify-center items-center"
                  >
                    {isLoading ? (
                      <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></span>
                    ) : (
                      'Masuk'
                    )}
                  </button>
                </div>

                {/* Tombol Daftar Biru */}
                <div className="relative flex py-1 md:py-2 items-center">
                    <div className="flex-grow border-t border-gray-200"></div>
                    <span className="flex-shrink-0 mx-3 text-gray-400 text-[10px] md:text-xs">Atau</span>
                    <div className="flex-grow border-t border-gray-200"></div>
                </div>

                <button 
                  onClick={handleRegisterClick}
                  className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 md:py-3 rounded-lg font-bold shadow-md transition flex items-center justify-center gap-2 text-xs md:text-sm"
                >
                  <UserPlus size={16} className="md:w-[18px] md:h-[18px]" /> Daftar Akun Baru
                </button>
              </div>
           </div>
        </Modal>
      )}
    </div>
  );
};

const App: React.FC = () => {
  return (
    <DataProvider>
      <MainContent />
    </DataProvider>
  );
};

export default App;

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppData, PreviousFund, WeeklyData, DonorData, ExpenseData } from '../types';
import Swal from 'sweetalert2';
import { supabase } from '../lib/supabaseClient';

interface DataContextType {
  publishedData: AppData;
  stagedData: AppData; // Admin working copy
  isLoggedIn: boolean;
  currentUser: string | null;
  login: (username: string) => void;
  logout: () => void;
  verifyUser: (username: string, password: string) => Promise<boolean>; 
  addAdminUser: (newUsername: string, newPassword: string, masterPass: string) => Promise<boolean>;
  getAdminUsers: () => Promise<any[]>;
  deleteAdminUser: (id: string, masterPass: string) => Promise<boolean>;
  // CRUD Actions (Effect Staged Data)
  addPreviousFund: (data: Omit<PreviousFund, 'id'>) => void;
  updatePreviousFund: (id: string, data: Partial<PreviousFund>) => void; // NEW
  deletePreviousFund: (id: string) => void;

  addWeeklyData: (data: Omit<WeeklyData, 'id'>) => void;
  updateWeeklyData: (id: string, data: Partial<WeeklyData>) => void; // NEW
  deleteWeeklyData: (id: string) => void;

  addDonor: (data: Omit<DonorData, 'id'>) => void;
  updateDonor: (id: string, data: Partial<DonorData>) => void; // NEW
  deleteDonor: (id: string) => void;

  addExpense: (data: Omit<ExpenseData, 'id'>) => void;
  updateExpense: (id: string, data: Partial<ExpenseData>) => void; // NEW
  deleteExpense: (id: string) => void;

  // System Actions
  publishData: (updateDate: string) => void;
  resetData: (type: 'all' | 'previous' | 'weekly' | 'donor' | 'expense') => void;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

const initialData: AppData = {
  lastUpdated: new Date().toISOString(),
  previousFunds: [],
  weeklyData: [],
  donors: [],
  expenses: [],
};

// --- PASSWORD ADMIN PUSAT (KUNCI UTAMA) ---
const MASTER_ADMIN_PASSWORD = "ALISHLAH2026"; 

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [publishedData, setPublishedData] = useState<AppData>(initialData);
  const [stagedData, setStagedData] = useState<AppData>(initialData);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState<string | null>(null);

  // --- FETCH DATA (SUPABASE ONLY) ---
  const fetchSupabaseData = async (notifyError = false) => {
    try {
      // a. Fetch Previous Funds
      const { data: prevFunds, error: prevError } = await supabase.from('previous_funds').select('*');
      if (prevError) throw prevError;

      const mappedPrev = prevFunds?.map((item: any) => ({
          ...item,
          createdBy: item.created_by // Map from DB
      })) || [];

      // b. Fetch Weekly Data
      const { data: weekly, error: weeklyError } = await supabase.from('weekly_data').select('*');
      if (weeklyError) throw weeklyError;

      const mappedWeekly = weekly?.map((item: any) => ({
        id: item.id,
        date: item.date,
        week: item.week,
        rt: item.rt,
        grossAmount: item.gross_amount,
        consumptionCut: item.consumption_cut,
        commissionCut: item.commission_cut,
        netAmount: item.net_amount,
        createdBy: item.created_by // Map from DB
      })) || [];

      // c. Fetch Donors
      const { data: donors, error: donorError } = await supabase.from('donors').select('*');
      if (donorError) throw donorError;

      const mappedDonors = donors?.map((item: any) => ({
        ...item,
        createdBy: item.created_by // Map from DB
      })) || [];

      // d. Fetch Expenses
      const { data: expenses, error: expError } = await supabase.from('expenses').select('*');
      if (expError) throw expError;

      const mappedExpenses = expenses?.map((item: any) => ({
        ...item,
        createdBy: item.created_by // Map from DB
      })) || [];

      // e. Fetch Meta
      const { data: meta, error: metaError } = await supabase.from('app_meta').select('*').limit(1).single();

      setPublishedData({
        lastUpdated: meta?.last_updated || new Date().toISOString(),
        previousFunds: mappedPrev,
        weeklyData: mappedWeekly,
        donors: mappedDonors,
        expenses: mappedExpenses
      });

    } catch (error: any) {
      console.error("Error fetching data from Supabase:", error);

      if (notifyError || isLoggedIn) {
          Swal.fire({
            icon: 'error',
            title: 'Gagal Mengambil Data',
            text: 'Terjadi kendala saat sinkronisasi data.',
            footer: error.message
          });
      }
    }
  };

  // Load initial data
  useEffect(() => {
    fetchSupabaseData(false);

    // Load Staged Data from LocalStorage (Draft / Admin Work in Progress only)
    const storedStaged = localStorage.getItem('phbi_staged_data');
    if (storedStaged) setStagedData(JSON.parse(storedStaged));
  }, []);

  // Persist Staged Data whenever it changes
  useEffect(() => {
    localStorage.setItem('phbi_staged_data', JSON.stringify(stagedData));
  }, [stagedData]);

  const login = (username: string) => {
    setIsLoggedIn(true);
    setCurrentUser(username);
    // Refresh data from Supabase upon login
    setTimeout(() => fetchSupabaseData(true), 500);
  };

  const logout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
  };

  // --- AUTHENTICATION LOGIC (SUPABASE TABLE) ---
  const verifyUser = async (u: string, p: string): Promise<boolean> => {
    try {
        // Cek ke tabel admin_users di Supabase
        const { data, error } = await supabase
            .from('admin_users')
            .select('id, username')
            .eq('username', u)
            .eq('password', p)
            .single();

        if (error || !data) {
            console.error("Auth failed:", error?.message);
            return false;
        }
        return true;
    } catch (err) {
        console.error("Auth error:", err);
        return false;
    }
  };

  // --- ADMIN MANAGEMENT LOGIC ---
  const addAdminUser = async (newUsername: string, newPassword: string, masterPass: string): Promise<boolean> => {
      // 1. Validasi Master Password
      if (masterPass !== MASTER_ADMIN_PASSWORD) {
          Swal.fire('Otorisasi Gagal', 'Kode Otorisasi (Master Password) tidak valid!', 'error');
          return false;
      }

      try {
          // 2. Cek apakah username sudah ada
          const { data: existing } = await supabase
              .from('admin_users')
              .select('id')
              .eq('username', newUsername)
              .single();

          if (existing) {
              Swal.fire('Gagal', 'Username tersebut sudah digunakan.', 'warning');
              return false;
          }

          // 3. Insert User Baru
          const { error } = await supabase
              .from('admin_users')
              .insert({ username: newUsername, password: newPassword });

          if (error) throw error;

          return true;
      } catch (error: any) {
          console.error(error);
          Swal.fire('Error', error.message, 'error');
          return false;
      }
  };

  const getAdminUsers = async () => {
      const { data, error } = await supabase
          .from('admin_users')
          .select('id, username, created_at')
          .order('created_at', { ascending: false });

      if (error) {
          console.error(error);
          return [];
      }
      return data || [];
  };

  const deleteAdminUser = async (id: string, masterPass: string): Promise<boolean> => {
      if (masterPass !== MASTER_ADMIN_PASSWORD) {
          Swal.fire('Otorisasi Gagal', 'Kode Otorisasi (Master Password) tidak valid!', 'error');
          return false;
      }
      const { error } = await supabase.from('admin_users').delete().eq('id', id);
      if (error) {
          Swal.fire('Error', error.message, 'error');
          return false;
      }
      return true;
  };

  // --- CRUD Operations (Operate on Staged Data - Client Side Only) ---
  // AUTOMATICALLY ATTACH CURRENT USERNAME TO DATA

  const addPreviousFund = (item: Omit<PreviousFund, 'id'>) => {
    const newItem = { 
        ...item, 
        id: crypto.randomUUID(),
        createdBy: currentUser || 'Admin' 
    };
    setStagedData(prev => ({ ...prev, previousFunds: [...prev.previousFunds, newItem] }));
  };
  const updatePreviousFund = (id: string, data: Partial<PreviousFund>) => {
    setStagedData(prev => ({
        ...prev,
        previousFunds: prev.previousFunds.map(item => item.id === id ? { ...item, ...data } : item)
    }));
  };
  const deletePreviousFund = (id: string) => {
    setStagedData(prev => ({ ...prev, previousFunds: prev.previousFunds.filter(i => i.id !== id) }));
  };


  const addWeeklyData = (item: Omit<WeeklyData, 'id'>) => {
    const newItem = { 
        ...item, 
        id: crypto.randomUUID(),
        createdBy: currentUser || 'Admin'
    };
    setStagedData(prev => ({ ...prev, weeklyData: [...prev.weeklyData, newItem] }));
  };
  const updateWeeklyData = (id: string, data: Partial<WeeklyData>) => {
    setStagedData(prev => ({
        ...prev,
        weeklyData: prev.weeklyData.map(item => item.id === id ? { ...item, ...data } : item)
    }));
  };
  const deleteWeeklyData = (id: string) => {
    setStagedData(prev => ({ ...prev, weeklyData: prev.weeklyData.filter(i => i.id !== id) }));
  };


  const addDonor = (item: Omit<DonorData, 'id'>) => {
    const newItem = { 
        ...item, 
        id: crypto.randomUUID(),
        createdBy: currentUser || 'Admin'
    };
    setStagedData(prev => ({ ...prev, donors: [...prev.donors, newItem] }));
  };
  const updateDonor = (id: string, data: Partial<DonorData>) => {
    setStagedData(prev => ({
        ...prev,
        donors: prev.donors.map(item => item.id === id ? { ...item, ...data } : item)
    }));
  };
  const deleteDonor = (id: string) => {
    setStagedData(prev => ({ ...prev, donors: prev.donors.filter(i => i.id !== id) }));
  };


  const addExpense = (item: Omit<ExpenseData, 'id'>) => {
    const newItem = { 
        ...item, 
        id: crypto.randomUUID(),
        createdBy: currentUser || 'Admin'
    };
    setStagedData(prev => ({ ...prev, expenses: [...prev.expenses, newItem] }));
  };
  const updateExpense = (id: string, data: Partial<ExpenseData>) => {
    setStagedData(prev => ({
        ...prev,
        expenses: prev.expenses.map(item => item.id === id ? { ...item, ...data } : item)
    }));
  };
  const deleteExpense = (id: string) => {
    setStagedData(prev => ({ ...prev, expenses: prev.expenses.filter(i => i.id !== id) }));
  };

  // --- System Actions ---

  const publishData = async (updateDate: string) => {
    Swal.fire({
      title: 'Memproses Data...',
      text: 'Mohon tunggu sebentar',
      allowOutsideClick: false,
      didOpen: () => { Swal.showLoading(); }
    });

    // MODE ONLINE (SUPABASE)
    try {
      // 1. Insert Previous Funds
      if (stagedData.previousFunds.length > 0) {
        // Map camelCase to snake_case for DB
        const payload = stagedData.previousFunds.map(({ id, createdBy, ...rest }) => ({
            ...rest,
            created_by: createdBy
        }));

        const { error } = await supabase.from('previous_funds').insert(payload);
        if (error) throw error;
      }

      // 2. Insert Weekly Data
      if (stagedData.weeklyData.length > 0) {
        const weeklyPayload = stagedData.weeklyData.map(item => ({
          date: item.date,
          week: item.week,
          rt: item.rt,
          gross_amount: item.grossAmount,
          consumption_cut: item.consumptionCut,
          commission_cut: item.commissionCut,
          net_amount: item.netAmount,
          created_by: item.createdBy // Send to DB
        }));
        const { error } = await supabase.from('weekly_data').insert(weeklyPayload);
        if (error) throw error;
      }

      // 3. Insert Donors
      if (stagedData.donors.length > 0) {
        const payload = stagedData.donors.map(({ id, createdBy, ...rest }) => ({
            ...rest,
            created_by: createdBy
        }));
        const { error } = await supabase.from('donors').insert(payload);
        if (error) throw error;
      }

      // 4. Insert Expenses
      if (stagedData.expenses.length > 0) {
        const payload = stagedData.expenses.map(({ id, createdBy, ...rest }) => ({
            ...rest,
            created_by: createdBy
        }));
        const { error } = await supabase.from('expenses').insert(payload);
        if (error) throw error;
      }

      // 5. Update Meta
      const { error: metaError } = await supabase
        .from('app_meta')
        .update({ last_updated: updateDate })
        .gt('id', 0); 

      if (metaError) {
         await supabase.from('app_meta').insert({ last_updated: updateDate });
      }

      // 6. Clear Staged & Refresh
      setStagedData(initialData);
      await fetchSupabaseData(true);

      Swal.fire({
        icon: 'success',
        title: 'Publikasi Berhasil',
        text: 'Laporan Keuangan telah berhasil diperbarui dan dipublikasikan ke Website.',
        confirmButtonColor: '#047857'
      });

    } catch (error: any) {
      console.error(error);
      Swal.fire({
        icon: 'error',
        title: 'Gagal Memproses',
        text: error.message || 'Terjadi kesalahan koneksi.',
      });
    }
  };

  const resetData = async (type: 'all' | 'previous' | 'weekly' | 'donor' | 'expense') => {
    // 1. Reset Local Staging first (Draft Admin)
    if (type === 'all') {
      setStagedData(initialData);
    } else {
      const keyMap: Record<string, keyof AppData> = {
        'previous': 'previousFunds',
        'weekly': 'weeklyData',
        'donor': 'donors',
        'expense': 'expenses'
      };
      const key = keyMap[type];
      // @ts-ignore
      setStagedData(prev => ({ ...prev, [key]: [] }));
    }

    // 2. Handle Published Data Reset (SUPABASE)
    Swal.fire({
        title: 'Mereset Database...',
        allowOutsideClick: false,
        didOpen: () => { Swal.showLoading(); }
    });

    try {
        if (type === 'all') {
            await supabase.from('previous_funds').delete().neq('id', '00000000-0000-0000-0000-000000000000'); 
            await supabase.from('weekly_data').delete().neq('id', '00000000-0000-0000-0000-000000000000');
            await supabase.from('donors').delete().neq('id', '00000000-0000-0000-0000-000000000000');
            await supabase.from('expenses').delete().neq('id', '00000000-0000-0000-0000-000000000000');
        } else {
            // Map type to table name
            const tableMap: Record<string, string> = {
                'previous': 'previous_funds',
                'weekly': 'weekly_data',
                'donor': 'donors',
                'expense': 'expenses'
            };
            const tableName = tableMap[type];
            if (tableName) {
                const { error } = await supabase.from(tableName).delete().neq('id', '00000000-0000-0000-0000-000000000000');
                if (error) throw error;
            }
        }

        await fetchSupabaseData(true); 
        Swal.fire('Berhasil', 'Data di Database Supabase telah direset/dihapus.', 'success');
    } catch (error: any) {
        console.error(error);
        Swal.fire('Error', 'Gagal mereset database: ' + error.message, 'error');
    }
  };

  return (
    <DataContext.Provider value={{
      publishedData,
      stagedData,
      isLoggedIn,
      currentUser,
      login,
      logout,
      verifyUser,
      addAdminUser,
      getAdminUsers,
      deleteAdminUser,
      addPreviousFund,
      updatePreviousFund,
      deletePreviousFund,
      addWeeklyData,
      updateWeeklyData,
      deleteWeeklyData,
      addDonor,
      updateDonor,
      deleteDonor,
      addExpense,
      updateExpense,
      deleteExpense,
      publishData,
      resetData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatCurrency, formatDate } from '../../utils/format';
import Swal from 'sweetalert2';
import { UploadCloud, AlertCircle } from 'lucide-react';

const PreviewSection: React.FC = () => {
  const { stagedData, publishData } = useData();
  const [updateDate, setUpdateDate] = useState(new Date().toISOString().split('T')[0]);

  const handlePublish = () => {
    // 1. Validasi Tanggal
    if (!updateDate) {
        Swal.fire('Pilih Tanggal', 'Mohon tentukan tanggal update laporan terlebih dahulu.', 'warning');
        return;
    }

    // 2. Validasi Ketersediaan Data (FIX)
    const hasData = 
        stagedData.previousFunds.length > 0 || 
        stagedData.weeklyData.length > 0 || 
        stagedData.donors.length > 0 || 
        stagedData.expenses.length > 0;

    if (!hasData) {
        Swal.fire({
            icon: 'info',
            title: 'Data Masih Kosong',
            text: 'Belum ada data baru untuk dipublikasikan. Silakan input data transaksi terlebih dahulu pada menu "Input Data".',
            confirmButtonColor: '#3b82f6'
        });
        return;
    }

    // 3. Konfirmasi Eksekusi
    Swal.fire({
      title: 'Publikasikan Data?',
      text: "Data yang telah diinput akan ditampilkan di Halaman Utama (Publik).",
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Publikasikan',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        publishData(updateDate);
      }
    });
  };

  const totalStagedIncome = 
    stagedData.previousFunds.reduce((a,b)=>a+b.nominal,0) + 
    stagedData.weeklyData.reduce((a,b)=>a+b.netAmount,0) + 
    stagedData.donors.reduce((a,b)=>a+b.nominal,0);

  const totalStagedExpense = stagedData.expenses.reduce((a,b)=>a+b.nominal,0);

  return (
    <div className="space-y-4 md:space-y-8">
      <div className="flex flex-col md:flex-row justify-between items-center border-b pb-4 gap-4">
        <div>
           <h2 className="text-sm md:text-2xl font-bold text-gray-800">Preview Data (Draft)</h2>
           <p className="text-[10px] md:text-sm text-gray-500">Data ini belum dilihat publik sampai Anda menekan tombol Publikasikan.</p>
        </div>

        <div className="flex flex-col md:flex-row items-center gap-3 w-full md:w-auto">
             {/* Date Selection for Update Status */}
             <div className="w-full md:w-auto">
                 <label className="block text-[10px] md:text-xs font-bold text-gray-600 mb-1">Tanggal Update Realtime</label>
                 <input 
                    type="date" 
                    value={updateDate}
                    onChange={(e) => setUpdateDate(e.target.value)}
                    className="w-full bg-white border border-gray-300 rounded px-3 py-2 text-xs md:text-sm focus:ring-1 focus:ring-primary outline-none"
                    style={{colorScheme: 'light'}}
                 />
             </div>

             <button 
                onClick={handlePublish}
                className="w-full md:w-auto bg-secondary hover:bg-primary text-white px-4 py-2 md:px-6 md:py-3 rounded-lg font-bold shadow-lg flex items-center justify-center gap-2 animate-pulse mt-2 md:mt-0 text-xs md:text-base"
            >
                <UploadCloud size={16} className="md:w-5 md:h-5" /> PUBLIKASIKAN DATA
            </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3 md:gap-6">
        <div className="bg-emerald-50 p-3 md:p-4 rounded-lg border border-emerald-200">
            <h3 className="font-bold text-emerald-800 text-[10px] md:text-base uppercase tracking-wider">Total Pemasukan (Draft)</h3>
            <p className="text-sm md:text-2xl font-bold text-emerald-900 mt-1">{formatCurrency(totalStagedIncome)}</p>
        </div>
        <div className="bg-red-50 p-3 md:p-4 rounded-lg border border-red-200">
            <h3 className="font-bold text-red-800 text-[10px] md:text-base uppercase tracking-wider">Total Pengeluaran (Draft)</h3>
            <p className="text-sm md:text-2xl font-bold text-red-900 mt-1">{formatCurrency(totalStagedExpense)}</p>
        </div>
      </div>

      {/* Tables Preview - Simplified view */}
      <div className="space-y-3 md:space-y-4">
        <h3 className="font-bold text-gray-700 text-xs md:text-base">Ringkasan Item Belum Dipublikasi</h3>

        {stagedData.previousFunds.length > 0 && (
            <div className="bg-white border rounded p-3 md:p-4">
                <h4 className="font-bold mb-2 text-[10px] md:text-sm text-purple-700 uppercase">Dana Awal ({stagedData.previousFunds.length} items)</h4>
                <div className="max-h-40 overflow-y-auto text-[10px] md:text-sm space-y-1">
                    {stagedData.previousFunds.map(d => (
                        <div key={d.id} className="flex justify-between py-1 border-b border-gray-50 last:border-0">
                            <span>{formatDate(d.date)}</span>
                            <span className="font-mono font-medium">{formatCurrency(d.nominal)}</span>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {stagedData.weeklyData.length > 0 && (
            <div className="bg-white border rounded p-3 md:p-4">
                <h4 className="font-bold mb-2 text-[10px] md:text-sm text-gray-600 uppercase">Mingguan ({stagedData.weeklyData.length} items)</h4>
                <div className="max-h-40 overflow-y-auto text-[10px] md:text-sm space-y-1">
                    {stagedData.weeklyData.map(d => (
                        <div key={d.id} className="flex justify-between py-1 border-b border-gray-50 last:border-0">
                            <span>{d.week} - {d.rt}</span>
                            <span className="font-mono font-medium">{formatCurrency(d.netAmount)}</span>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {stagedData.donors.length > 0 && (
             <div className="bg-white border rounded p-3 md:p-4">
             <h4 className="font-bold mb-2 text-[10px] md:text-sm text-blue-700 uppercase">Proposal / Amplop ({stagedData.donors.length} items)</h4>
             <div className="max-h-40 overflow-y-auto text-[10px] md:text-sm space-y-1">
                 {stagedData.donors.map(d => (
                     <div key={d.id} className="flex justify-between py-1 border-b border-gray-50 last:border-0">
                         <span>{d.name}</span>
                         <span className="font-mono font-medium">{formatCurrency(d.nominal)}</span>
                     </div>
                 ))}
             </div>
         </div>
        )}

        {stagedData.expenses.length > 0 && (
             <div className="bg-white border rounded p-3 md:p-4">
             <h4 className="font-bold mb-2 text-[10px] md:text-sm text-red-700 uppercase">Pengeluaran ({stagedData.expenses.length} items)</h4>
             <div className="max-h-40 overflow-y-auto text-[10px] md:text-sm space-y-1">
                 {stagedData.expenses.map(d => (
                     <div key={d.id} className="flex justify-between py-1 border-b border-gray-50 last:border-0">
                         <span>{d.purpose}</span>
                         <span className="font-mono text-red-600 font-medium">{formatCurrency(d.nominal)}</span>
                     </div>
                 ))}
             </div>
         </div>
        )}

        {stagedData.previousFunds.length === 0 && stagedData.weeklyData.length === 0 && stagedData.donors.length === 0 && stagedData.expenses.length === 0 && (
            <div className="text-center py-8 md:py-10 bg-gray-50 text-gray-400 rounded-lg flex flex-col items-center">
                <AlertCircle size={24} className="mb-2 md:w-12 md:h-12"/>
                <p className="text-xs md:text-base">Tidak ada data baru untuk dipublikasikan.</p>
            </div>
        )}

      </div>

    </div>
  );
};

export default PreviewSection;

import React, { useState, useEffect } from 'react';
import { useData } from '../../context/DataContext';
import Swal from 'sweetalert2';
import { UserPlus, ShieldAlert, Users, Trash2 } from 'lucide-react';

const UserManagementSection: React.FC = () => {
  const { addAdminUser, getAdminUsers, deleteAdminUser } = useData();
  const [users, setUsers] = useState<any[]>([]);
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    confirmPassword: '',
    masterPassword: ''
  });

  const loadUsers = async () => {
      const data = await getAdminUsers();
      setUsers(data);
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!formData.username || !formData.password || !formData.masterPassword) {
        Swal.fire('Peringatan', 'Semua kolom wajib diisi!', 'warning');
        return;
    }

    if (formData.password !== formData.confirmPassword) {
        Swal.fire('Peringatan', 'Konfirmasi password tidak cocok!', 'warning');
        return;
    }

    // Call Context Function
    const success = await addAdminUser(formData.username, formData.password, formData.masterPassword);

    // REVISI 1: Hapus isi konten form baik berhasil maupun gagal
    setFormData({ username: '', password: '', confirmPassword: '', masterPassword: '' });

    if (success) {
        Swal.fire({
            title: 'Berhasil',
            text: `Admin user baru berhasil ditambahkan.`,
            icon: 'success',
            timer: 1500,
            showConfirmButton: false
        });
        loadUsers(); // Reload list
    }
  };

  const handleDelete = async (id: string, username: string) => {
      const { value: masterPass } = await Swal.fire({
          title: 'Hapus Admin?',
          text: `Hapus user: ${username}`,
          input: 'password',
          inputPlaceholder: 'Masukkan Kode Otorisasi',
          showCancelButton: true,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Hapus',
          cancelButtonText: 'Batal',
          customClass: {
            title: 'text-lg',
            input: 'text-sm'
          }
      });

      if (masterPass) {
          const success = await deleteAdminUser(id, masterPass);
          if (success) {
              Swal.fire({
                  title: 'Terhapus',
                  text: 'User dihapus.',
                  icon: 'success',
                  timer: 1000,
                  showConfirmButton: false
              });
              loadUsers();
          }
      }
  };

  const inputClass = "w-full bg-white border rounded-lg px-3 py-1.5 md:py-2 text-xs md:text-sm focus:ring-1 focus:ring-primary outline-none shadow-sm placeholder:text-gray-300";
  const labelClass = "block text-[10px] md:text-xs font-bold text-gray-600 mb-0.5 md:mb-1";

  return (
    <div className="space-y-4 md:space-y-6">
      {/* Header Kecil */}
      <div className="border-b pb-2 md:pb-4">
        <h2 className="text-lg md:text-2xl font-bold text-gray-800 flex items-center gap-2">
            <UserPlus className="text-primary w-5 h-5 md:w-6 md:h-6" /> 
            <span>Kelola Admin</span>
        </h2>
        <p className="text-[10px] md:text-sm text-gray-500 mt-0.5 leading-tight">
            Tambahkan akun pengurus untuk akses dashboard.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-8">

          {/* FORM INPUT COMPACT */}
          <div className="bg-gray-50 p-4 md:p-6 rounded-lg border border-gray-200 shadow-sm h-fit">
              <h3 className="font-bold text-sm md:text-lg mb-3 text-gray-700 border-b border-gray-200 pb-2">Tambah Admin Baru</h3>
              <form onSubmit={handleSubmit} className="space-y-2 md:space-y-4">
                  <div>
                      <label className={labelClass}>Username</label>
                      <input 
                        type="text" 
                        value={formData.username}
                        onChange={e => setFormData({...formData, username: e.target.value})}
                        className={inputClass}
                        placeholder="Contoh: bendahara2"
                      />
                  </div>

                  <div className="grid grid-cols-2 gap-2 md:gap-3">
                    <div>
                        <label className={labelClass}>Password</label>
                        <input 
                            type="text" 
                            value={formData.password}
                            onChange={e => setFormData({...formData, password: e.target.value})}
                            className={inputClass}
                            placeholder="******"
                        />
                    </div>
                    <div>
                        <label className={labelClass}>Ulangi Pass</label>
                        <input 
                            type="text" 
                            value={formData.confirmPassword}
                            onChange={e => setFormData({...formData, confirmPassword: e.target.value})}
                            className={inputClass}
                            placeholder="******"
                        />
                    </div>
                  </div>

                  <hr className="border-gray-200 my-1 md:my-2" />

                  <div className="bg-red-50 p-2 md:p-3 rounded border border-red-100">
                      <label className="block text-[10px] md:text-xs font-bold text-red-700 mb-1 flex items-center gap-1">
                          <ShieldAlert size={12} className="md:w-3.5 md:h-3.5" /> Masukkan Kode Otorisasi
                      </label>
                      <input 
                        type="password" 
                        value={formData.masterPassword}
                        onChange={e => setFormData({...formData, masterPassword: e.target.value})}
                        className={`${inputClass} border-red-200 focus:ring-red-500`}
                        placeholder="Kode Otorisasi..."
                      />
                  </div>

                  <button 
                    type="submit"
                    className="w-full bg-primary hover:bg-emerald-800 text-white font-bold py-2 md:py-2.5 rounded-lg shadow-sm text-xs md:text-sm transition active:scale-95 flex justify-center items-center gap-2 mt-2"
                  >
                      <UserPlus size={14} className="md:w-[18px] md:h-[18px]" /> SIMPAN USER
                  </button>
              </form>
          </div>

          {/* LIST ADMIN COMPACT */}
          <div>
              <h3 className="font-bold text-sm md:text-lg mb-2 md:mb-4 text-gray-700 flex items-center gap-2">
                  <Users size={16} className="md:w-5 md:h-5" /> Daftar Admin
              </h3>
              <div className="bg-white border rounded-lg overflow-hidden shadow-sm">
                  {users.length === 0 ? (
                      <div className="p-4 text-center text-gray-400 text-xs">Belum ada user tambahan.</div>
                  ) : (
                      <ul className="divide-y divide-gray-100">
                          {users.map((user, idx) => (
                              <li key={user.id} className="p-3 md:p-4 flex justify-between items-center hover:bg-gray-50 transition">
                                  <div className="flex items-center gap-2 md:gap-3">
                                      <div className="bg-gray-100 w-6 h-6 md:w-8 md:h-8 flex items-center justify-center rounded-full text-gray-600 font-bold text-[10px] md:text-xs">
                                          {idx + 1}
                                      </div>
                                      <div>
                                          <p className="font-bold text-gray-800 text-xs md:text-sm leading-tight">{user.username}</p>
                                          <p className="text-[9px] md:text-[10px] text-gray-400 leading-tight mt-0.5">
                                            {new Date(user.created_at).toLocaleDateString('id-ID')}
                                          </p>
                                      </div>
                                  </div>
                                  <button 
                                    onClick={() => handleDelete(user.id, user.username)}
                                    className="text-red-500 hover:text-red-700 hover:bg-red-50 p-1.5 md:p-2 rounded transition"
                                    title="Hapus"
                                  >
                                      <Trash2 size={14} className="md:w-4 md:h-4" />
                                  </button>
                              </li>
                          ))}
                      </ul>
                  )}
              </div>
          </div>

      </div>
    </div>
  );
};

export default UserManagementSection;

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatDate, formatCurrency, calculateWeeklyCuts } from '../../utils/format';
import Swal from 'sweetalert2';
import { Trash2, Save, Pencil, XCircle } from 'lucide-react';

const InputSection: React.FC = () => {
  const { 
    stagedData, 
    publishedData, 
    addPreviousFund, updatePreviousFund, deletePreviousFund, 
    addWeeklyData, updateWeeklyData, deleteWeeklyData, 
    addDonor, updateDonor, deleteDonor, 
    addExpense, updateExpense, deleteExpense 
  } = useData();

  const [activeTab, setActiveTab] = useState<'previous' | 'weekly' | 'donor' | 'expense'>('previous');
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form States
  const [prevForm, setPrevForm] = useState({ date: '', nominal: '' });
  const [weekForm, setWeekForm] = useState({ date: '', week: 'Minggu ke-1', rt: 'RT 01', gross: '' });
  const [donorForm, setDonorForm] = useState({ date: '', name: '', nominal: '' });
  const [expForm, setExpForm] = useState({ date: '', purpose: '', nominal: '' });

  // Helper: Format tampilan saat mengetik
  const formatNumberInput = (value: string | number) => {
    if (!value) return '';
    const valString = value.toString();
    const rawValue = valString.replace(/\D/g, ''); 
    return new Intl.NumberFormat('id-ID').format(Number(rawValue));
  };

  // Helper: Ubah kembali ke angka murni untuk disimpan
  const parseNumberInput = (value: string) => {
    if (!value) return 0;
    return Number(value.replace(/\./g, ''));
  };

  const cancelEdit = () => {
    setEditingId(null);
    setPrevForm({ date: '', nominal: '' });
    setWeekForm({ date: '', week: 'Minggu ke-1', rt: 'RT 01', gross: '' });
    setDonorForm({ date: '', name: '', nominal: '' });
    setExpForm({ date: '', purpose: '', nominal: '' });
  };

  const confirmAction = (title: string, text: string, callback: () => void) => {
    Swal.fire({
      title: title,
      text: text,
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Lanjutkan',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        callback();
        Swal.fire('Berhasil!', 'Data telah disimpan.', 'success');
      }
    });
  };

  const confirmDelete = (id: string, deleteFn: (id: string) => void) => {
    Swal.fire({
      title: 'Hapus Data?',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'Ya, Hapus',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        deleteFn(id);
        if (editingId === id) cancelEdit(); 
        Swal.fire('Berhasil!', 'Data dihapus.', 'success');
      }
    });
  };

  // --- HANDLERS ---

  // 1. PREVIOUS FUNDS (PANITIA)
  const handleSavePrev = () => {
    if (!prevForm.date || !prevForm.nominal) return;
    const nominal = parseNumberInput(prevForm.nominal);

    if (editingId) {
       confirmAction('Update Data?', 'Apakah Anda yakin ingin mengubah data ini?', () => {
         updatePreviousFund(editingId, { date: prevForm.date, nominal: nominal });
         cancelEdit(); // Kalau edit, reset form
       });
    } else {
       confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
         addPreviousFund({ date: prevForm.date, nominal: nominal });
         // REVISI 2: JANGAN HILANGKAN HASIL INPUTAN (TIDAK ADA RESET FORM)
         // cancelEdit(); <- Dihapus agar form tetap terisi
         setEditingId(null); // Hanya memastikan tidak dalam mode edit
       });
    }
  };

  const handleEditPrev = (data: any) => {
    setEditingId(data.id);
    setPrevForm({ date: data.date, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 2. WEEKLY DATA
  const handleSaveWeek = () => {
    if (!weekForm.date || !weekForm.gross) return;

    // Cek Duplikasi
    const duplicateInStaged = stagedData.weeklyData.some(
        d => d.week === weekForm.week && d.rt === weekForm.rt && d.id !== editingId
    );

    const duplicateInPublished = publishedData.weeklyData.some(
        d => d.week === weekForm.week && d.rt === weekForm.rt
    );

    if (duplicateInStaged || duplicateInPublished) {
        Swal.fire({
            title: 'Data Duplikat!',
            text: `Data untuk ${weekForm.week} dan ${weekForm.rt} sudah terdaftar (di Draft atau Database).`,
            icon: 'error',
            confirmButtonColor: '#d33'
        });
        return; 
    }

    const gross = parseNumberInput(weekForm.gross);
    const { consumption, commission, net } = calculateWeeklyCuts(gross);

    const payload = {
        date: weekForm.date,
        week: weekForm.week,
        rt: weekForm.rt,
        grossAmount: gross,
        consumptionCut: consumption,
        commissionCut: commission,
        netAmount: net
    };

    if (editingId) {
        confirmAction('Update Data Mingguan?', 'Apakah Anda yakin ingin mengubah data ini?', () => {
            updateWeeklyData(editingId, payload);
            cancelEdit();
        });
    } else {
        confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
            addWeeklyData(payload);
            // REVISI 3: Hapus konten Pemasukan Kotor dan RT saja. TANGGAL & MINGGU KE TETAP.
            setWeekForm(prev => ({
                ...prev,
                rt: '', // Reset RT ke kosong (agar user pilih lagi) atau bisa default 'RT 01'
                gross: '' // Reset Nominal Kotor
                // Date dan Week tidak diubah
            }));
            setEditingId(null);
        });
    }
  };

  const handleEditWeek = (data: any) => {
    setEditingId(data.id);
    setWeekForm({ 
        date: data.date, 
        week: data.week, 
        rt: data.rt, 
        gross: formatNumberInput(data.grossAmount) 
    });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };


  // 3. DONOR DATA
  const handleSaveDonor = () => {
    if(!donorForm.name || !donorForm.nominal) return;
    const nominal = parseNumberInput(donorForm.nominal);

    if (editingId) {
        confirmAction('Update Data Donatur?', 'Apakah Anda yakin ingin mengubah data ini?', () => {
            updateDonor(editingId, { date: donorForm.date, name: donorForm.name, nominal: nominal });
            cancelEdit();
        });
    } else {
        confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
            addDonor({ date: donorForm.date, name: donorForm.name, nominal: nominal });
            cancelEdit();
        });
    }
  };

  const handleEditDonor = (data: any) => {
    setEditingId(data.id);
    setDonorForm({ date: data.date, name: data.name, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };


  // 4. EXPENSE DATA
  const handleSaveExp = () => {
    if(!expForm.purpose || !expForm.nominal) return;
    const nominal = parseNumberInput(expForm.nominal);

    if (editingId) {
        confirmAction('Update Pengeluaran?', 'Apakah Anda yakin ingin mengubah data ini?', () => {
            updateExpense(editingId, { date: expForm.date, purpose: expForm.purpose, nominal: nominal });
            cancelEdit();
        });
    } else {
        confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
            addExpense({ date: expForm.date, purpose: expForm.purpose, nominal: nominal });
            cancelEdit();
        });
    }
  };

  const handleEditExp = (data: any) => {
    setEditingId(data.id);
    setExpForm({ date: data.date, purpose: data.purpose, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };


  // --- UI HELPERS ---
  const tabClass = (tab: string) => 
    `flex-1 text-center md:flex-none px-2 py-2 md:px-4 md:py-3 rounded-t-lg font-bold text-xs md:text-sm transition-colors ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`;

  const inputClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg px-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm transition-shadow [&::-webkit-calendar-picker-indicator]:cursor-pointer";
  const inputRpClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg pl-8 md:pl-10 pr-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm transition-shadow font-mono tracking-wide";

  const ActionButtons = ({ onSave }: { onSave: () => void }) => (
    <div className="flex gap-2">
       {editingId && (
          <button onClick={cancelEdit} className="w-1/3 bg-gray-500 hover:bg-gray-600 text-white py-2 rounded-lg font-bold text-xs md:text-sm flex items-center justify-center gap-2 shadow-md transition">
             <XCircle size={16}/> BATAL
          </button>
       )}
       <button onClick={onSave} className={`flex-1 ${editingId ? 'bg-blue-600 hover:bg-blue-700' : 'bg-primary hover:bg-emerald-800'} text-white py-2 rounded-lg font-bold text-xs md:text-sm flex items-center justify-center gap-2 shadow-md transform active:scale-95 transition`}>
          {editingId ? <Pencil size={16}/> : <Save size={16}/>} 
          {editingId ? 'UPDATE' : 'SIMPAN'}
       </button>
    </div>
  );

  const EditButton = ({ onClick }: { onClick: () => void }) => (
     <button onClick={onClick} className="text-blue-600 hover:text-blue-800 bg-blue-50 p-2 rounded-full mr-2" title="Edit Data">
        <Pencil size={16}/>
     </button>
  );

  return (
    <div className="space-y-4 md:space-y-6">
      <h2 className="text-sm md:text-xl font-bold text-gray-800 border-b pb-2">
          {editingId ? 'Edit Data Terpilih' : 'Input Data Keuangan'}
      </h2>

      {/* Tabs */}
      <div className={`flex flex-row gap-1 overflow-x-auto no-scrollbar ${editingId ? 'opacity-50 pointer-events-none' : ''}`}>
        <button onClick={() => setActiveTab('previous')} className={tabClass('previous')}>Panitia</button>
        <button onClick={() => setActiveTab('weekly')} className={tabClass('weekly')}>Mingguan</button>
        <button onClick={() => setActiveTab('donor')} className={tabClass('donor')}>Donatur</button>
        <button onClick={() => setActiveTab('expense')} className={tabClass('expense')}>Keluar</button>
      </div>

      <div className="bg-white p-3 md:p-6 rounded-b-lg shadow-md border border-gray-200">

        {/* PREVIOUS FUND FORM */}
        {activeTab === 'previous' && (
          <div className="space-y-4 md:space-y-6">
            <div className={`grid grid-cols-1 md:grid-cols-3 gap-3 bg-gray-50 p-3 rounded-lg border ${editingId ? 'border-blue-400 bg-blue-50' : 'border-gray-200'}`}>
                <div className="w-full">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input 
                    type="date" 
                    value={prevForm.date} 
                    onChange={e => setPrevForm({...prevForm, date: e.target.value})} 
                    className={inputClass} 
                    style={{colorScheme: 'light'}} 
                    />
                </div>

                <div className="w-full">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Nominal</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input 
                            type="text" 
                            inputMode="numeric"
                            placeholder="0" 
                            value={prevForm.nominal} 
                            onChange={e => setPrevForm({...prevForm, nominal: formatNumberInput(e.target.value)})} 
                            className={inputRpClass} 
                        />
                    </div>
                </div>

                <div className="flex items-end">
                     <div className="w-full"><ActionButtons onSave={handleSavePrev} /></div>
                </div>
            </div>

            {/* Desktop Table */}
            <div className="hidden md:block">
              <table className="w-full text-sm text-left">
                  <thead className="bg-gray-100 uppercase text-gray-700"><tr><th className="p-3">Tgl</th><th className="p-3">Nominal</th><th className="p-3">Aksi</th></tr></thead>
                  <tbody>
                      {stagedData.previousFunds.map(d => (
                          <tr key={d.id} className={`border-b ${editingId === d.id ? 'bg-blue-50' : ''}`}>
                              <td className="p-3">{formatDate(d.date)}</td>
                              <td className="p-3 font-bold">{formatCurrency(d.nominal)}</td>
                              <td className="p-3 flex">
                                  <EditButton onClick={() => handleEditPrev(d)} />
                                  <button onClick={() => confirmDelete(d.id, deletePreviousFund)} className="text-red-600 hover:text-red-800 bg-red-50 p-2 rounded-full"><Trash2 size={16}/></button>
                              </td>
                          </tr>
                      ))}
                  </tbody>
              </table>
            </div>

            {/* Mobile Cards */}
            <div className="md:hidden space-y-2">
               {stagedData.previousFunds.map(d => (
                 <div key={d.id} className={`border border-gray-200 p-3 rounded-lg shadow-sm flex justify-between items-center ${editingId === d.id ? 'bg-blue-50 border-blue-300' : 'bg-white'}`}>
                    <div>
                        <p className="text-[10px] text-gray-500">{formatDate(d.date)}</p>
                        <p className="font-bold text-gray-800 text-sm">{formatCurrency(d.nominal)}</p>
                    </div>
                    <div className="flex">
                        <EditButton onClick={() => handleEditPrev(d)} />
                        <button onClick={() => confirmDelete(d.id, deletePreviousFund)} className="bg-red-50 text-red-600 p-1.5 rounded-lg"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* WEEKLY FORM */}
        {activeTab === 'weekly' && (
          <div className="space-y-4 md:space-y-6">
            <div className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3 bg-gray-50 p-3 rounded-lg border ${editingId ? 'border-blue-400 bg-blue-50' : 'border-gray-200'}`}>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input 
                    type="date"
                    value={weekForm.date} 
                    onChange={e => setWeekForm({...weekForm, date: e.target.value})} 
                    className={inputClass} 
                    style={{colorScheme: 'light'}}
                    />
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Minggu Ke</label>
                    <select value={weekForm.week} onChange={e => setWeekForm({...weekForm, week: e.target.value})} className={inputClass}>
                        <option value="">Pilih Minggu</option>
                        {[...Array(30)].map((_, i) => <option key={i} value={`Minggu ke-${i+1}`}>Minggu ke-{i+1}</option>)}
                    </select>
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">RT</label>
                    <select value={weekForm.rt} onChange={e => setWeekForm({...weekForm, rt: e.target.value})} className={inputClass}>
                        <option value="">Pilih RT</option>
                        {[...Array(6)].map((_, i) => <option key={i} value={`RT 0${i+1}`}>RT 0{i+1}</option>)}
                    </select>
                </div>

                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Pemasukan Kotor</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input 
                            type="text" 
                            inputMode="numeric"
                            placeholder="0" 
                            value={weekForm.gross} 
                            onChange={e => setWeekForm({...weekForm, gross: formatNumberInput(e.target.value)})} 
                            className={inputRpClass} 
                        />
                    </div>
                </div>

                <div className="col-span-1 md:col-span-2 lg:col-span-1 flex items-end">
                    <div className="w-full"><ActionButtons onSave={handleSaveWeek} /></div>
                </div>
            </div>

            {/* Desktop Table */}
            <div className="hidden md:block overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-100 uppercase text-gray-700">
                        <tr>
                            <th className="p-3">Minggu/RT</th>
