                if (!ws[cellRef].s) ws[cellRef].s = {};
                ws[cellRef].s.border = borderStyle;

                // Apply Header Style (Bold, Centered)
                if (R === 0) {
                    ws[cellRef].s = { ...ws[cellRef].s, ...headerStyle };
                }

                // Apply Currency Format to Number Cells (excluding headers)
                if (R > 0 && ws[cellRef].t === 'n') {
                    ws[cellRef].z = '"Rp" #,##0';
                }
            }
        }

        XLSX.utils.book_append_sheet(wb, ws, sheetName);
      };

      // --- PREVIOUS FUNDS (Dana Awal) ---
      if (type === 'all_financial') {
          const headers = ['No', 'Tanggal', 'Nominal'];
          const rows = data.previousFunds.map((item, idx) => [
              idx + 1,
              formatDate(item.date),
              item.nominal
          ]);
          const totalRow = ['', 'TOTAL', data.previousFunds.reduce((a,b)=>a+b.nominal,0)];
          rows.push(totalRow);
          addToSheet("Dana Awal", headers, rows);
      }

      // --- MINGGUAN ---
      if (type === 'weekly' || type === 'all_income' || type === 'all_financial') {
        const headers = ['Minggu', 'RT', 'Tanggal', 'Pemasukan Kotor', 'Potongan Konsumsi (5%)', 'Potongan Komisi (10%)', 'Jumlah Bersih'];
        const rows = data.weeklyData.map(item => [
          item.week,
          item.rt,
          formatDate(item.date),
          item.grossAmount,
          item.consumptionCut,
          item.commissionCut,
          item.netAmount
        ]);

        const totalRow = [
            'TOTAL', '', '',
            data.weeklyData.reduce((a,b)=>a+b.grossAmount,0),
            data.weeklyData.reduce((a,b)=>a+b.consumptionCut,0),
            data.weeklyData.reduce((a,b)=>a+b.commissionCut,0),
            data.weeklyData.reduce((a,b)=>a+b.netAmount,0)
        ];
        rows.push(totalRow);

        addToSheet("Mingguan", headers, rows);
      }

      // --- DONATUR ---
      if (type === 'donor' || type === 'all_income' || type === 'all_financial') {
        const headers = ['No', 'Tanggal', 'Sumber Dana', 'Nominal'];
        const rows = data.donors.map((item, idx) => [
          idx + 1,
          formatDate(item.date),
          item.name,
          item.nominal
        ]);

        const totalRow = ['', '', 'TOTAL', data.donors.reduce((a,b)=>a+b.nominal,0)];
        rows.push(totalRow);

        addToSheet("Donatur", headers, rows);
      }

      // --- PENGELUARAN ---
      if (type === 'expense' || type === 'all_financial') {
        const headers = ['No', 'Tanggal', 'Keperluan', 'Nominal'];
        const rows = data.expenses.map((item, idx) => [
          idx + 1,
          formatDate(item.date),
          item.purpose,
          item.nominal
        ]);

        const totalRow = ['', '', 'TOTAL', data.expenses.reduce((a,b)=>a+b.nominal,0)];
        rows.push(totalRow);

        addToSheet("Pengeluaran", headers, rows);
      }

      // --- REKAPITULASI ---
      if (type === 'all_financial') {
        const totalPrev = data.previousFunds.reduce((a,b)=>a+b.nominal,0);
        const totalWeekly = data.weeklyData.reduce((a,b)=>a+b.netAmount,0);
        const totalDonor = data.donors.reduce((a,b)=>a+b.nominal,0);
        const totalIncome = totalPrev + totalWeekly + totalDonor;
        const totalExpense = data.expenses.reduce((a,b)=>a+b.nominal,0);
        const balance = totalIncome - totalExpense;

        const headers = ['KATEGORI', 'TOTAL NOMINAL'];
        const rows = [
            ['Total Dana Panitia Sebelumnya', totalPrev],
            ['Total Pemasukan Mingguan (Bersih)', totalWeekly],
            ['Total Pemasukan Proposal / Amplop', totalDonor],
            ['TOTAL SEMUA PEMASUKAN', totalIncome],
            ['TOTAL PENGELUARAN', totalExpense],
            ['SISA SALDO SAAT INI', balance]
        ];
        addToSheet("Rekapitulasi", headers, rows);
      }

      // Tulis File
      XLSX.writeFile(wb, `Laporan_PHBI_${type}_${new Date().toISOString().slice(0,10)}.xlsx`);

  } catch (error: any) {
      console.error("Excel Error:", error);
      Swal.fire({
          icon: 'error',
          title: 'Gagal Download Excel',
          text: 'Terjadi kesalahan saat membuat file excel. Pastikan browser mendukung fitur ini.',
          footer: error.message
      });
  }
};

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatDate, formatCurrency, calculateWeeklyCuts } from '../../utils/format';
import Swal from 'sweetalert2';
import { Trash2, Save, Pencil, XCircle, CheckCircle, Clock } from 'lucide-react';

const InputSection: React.FC = () => {
  const { 
    stagedData, 
    publishedData, 
    addPreviousFund, updatePreviousFund, deletePreviousFund, 
    addWeeklyData, updateWeeklyData, deleteWeeklyData, 
    addDonor, updateDonor, deleteDonor, 
    addExpense, updateExpense, deleteExpense,
    // New Context Methods for Direct DB Manipulation
    updatePublishedItem, deletePublishedItem
  } = useData();

  const [activeTab, setActiveTab] = useState<'previous' | 'weekly' | 'donor' | 'expense'>('previous');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingSource, setEditingSource] = useState<'staged' | 'published'>('staged');

  // Form States
  const [prevForm, setPrevForm] = useState({ date: '', nominal: '' });
  const [weekForm, setWeekForm] = useState({ date: '', week: 'Minggu ke-1', rt: 'RT 01', gross: '' });
  const [donorForm, setDonorForm] = useState({ date: '', name: '', nominal: '' });
  const [expForm, setExpForm] = useState({ date: '', purpose: '', nominal: '' });

  // --- MERGE LIST FOR DISPLAY (Previous Funds Only, as requested) ---
  const allPreviousFunds = [
      ...stagedData.previousFunds.map(i => ({ ...i, source: 'staged' })),
      ...publishedData.previousFunds.map(i => ({ ...i, source: 'published' }))
  ];

  // Helper: Format tampilan saat mengetik
  const formatNumberInput = (value: string | number) => {
    if (!value) return '';
    const valString = value.toString();
    const rawValue = valString.replace(/\D/g, ''); 
    return new Intl.NumberFormat('id-ID').format(Number(rawValue));
  };

  const parseNumberInput = (value: string) => {
    if (!value) return 0;
    return Number(value.replace(/\./g, ''));
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditingSource('staged');
    setPrevForm({ date: '', nominal: '' });
    setWeekForm({ date: '', week: 'Minggu ke-1', rt: 'RT 01', gross: '' });
    setDonorForm({ date: '', name: '', nominal: '' });
    setExpForm({ date: '', purpose: '', nominal: '' });
  };

  const confirmAction = (title: string, text: string, callback: () => void) => {
    Swal.fire({
      title: title,
      text: text,
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Lanjutkan',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        callback();
      }
    });
  };

  const confirmDelete = (id: string, source: 'staged' | 'published', type: 'previous' | 'weekly' | 'donor' | 'expense') => {
    Swal.fire({
      title: source === 'published' ? 'Hapus dari Database?' : 'Hapus Draft?',
      text: source === 'published' ? 'Data ini sudah dipublikasikan. Menghapusnya akan langsung hilang dari website publik.' : 'Data ini belum dipublikasikan.',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'Ya, Hapus',
      cancelButtonText: 'Batal'
    }).then(async (result) => {
      if (result.isConfirmed) {
         if (source === 'staged') {
             // Local Deletion
             if (type === 'previous') deletePreviousFund(id);
             if (type === 'weekly') deleteWeeklyData(id);
             if (type === 'donor') deleteDonor(id);
             if (type === 'expense') deleteExpense(id);
             Swal.fire('Terhapus', 'Data draft dihapus.', 'success');
         } else {
             // Direct DB Deletion
             let table = '';
             if (type === 'previous') table = 'previous_funds';
             // if (type === 'weekly') table = 'weekly_data'; // Not implemented for others yet based on req

             if (table) {
                const success = await deletePublishedItem(table, id);
                if (success) Swal.fire('Terhapus', 'Data database berhasil dihapus.', 'success');
             }
         }
         if (editingId === id) cancelEdit(); 
      }
    });
  };

  // --- HANDLERS ---

  // 1. PREVIOUS FUNDS (PANITIA) - FULL HYBRID CRUD
  const handleSavePrev = () => {
    if (!prevForm.date || !prevForm.nominal) return;
    const nominal = parseNumberInput(prevForm.nominal);

    if (editingId) {
       confirmAction('Update Data?', editingSource === 'published' ? 'Ini akan langsung mengubah data di database!' : 'Ubah data draft ini?', async () => {
         if (editingSource === 'published') {
             // Direct DB Update
             const success = await updatePublishedItem('previous_funds', editingId, { 
                 date: prevForm.date, 
                 nominal: nominal 
             });
             if (success) {
                 Swal.fire('Sukses', 'Data database diperbarui.', 'success');
                 cancelEdit();
             }
         } else {
             // Local Update
             updatePreviousFund(editingId, { date: prevForm.date, nominal: nominal });
             cancelEdit();
             Swal.fire('Sukses', 'Data draft diperbarui.', 'success');
         }
       });
    } else {
       confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview (Draft).', () => {
         addPreviousFund({ date: prevForm.date, nominal: nominal });
         // DO NOT RESET FORM as per request
         setEditingId(null); 
         Swal.fire('Berhasil!', 'Data disimpan ke draft.', 'success');
       });
    }
  };

  const handleEditPrev = (data: any) => {
    setEditingId(data.id);
    setEditingSource(data.source || 'staged'); // Default to staged if prop missing
    setPrevForm({ date: data.date, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 2. WEEKLY DATA (Standard Local CRUD)
  const handleSaveWeek = () => {
    if (!weekForm.date || !weekForm.gross) return;

    // --- RESTORED VALIDATION START ---
    // Check if data already exists in Staged (Draft)
    const isDuplicateStaged = stagedData.weeklyData.some(
        item => item.week === weekForm.week && item.rt === weekForm.rt && item.id !== editingId
    );
    // Check if data already exists in Published (DB)
    const isDuplicatePublished = publishedData.weeklyData.some(
        item => item.week === weekForm.week && item.rt === weekForm.rt
    );

    if (isDuplicateStaged || isDuplicatePublished) {
        Swal.fire({
            icon: 'warning',
            title: 'Data Duplikat',
            text: `Data untuk ${weekForm.week} - ${weekForm.rt} sudah ada (di Draft atau Database). Mohon periksa kembali.`,
            confirmButtonColor: '#d33'
        });
        return;
    }
    // --- RESTORED VALIDATION END ---

    const gross = parseNumberInput(weekForm.gross);
    const { consumption, commission, net } = calculateWeeklyCuts(gross);

    const payload = {
        date: weekForm.date,
        week: weekForm.week,
        rt: weekForm.rt,
        grossAmount: gross,
        consumptionCut: consumption,
        commissionCut: commission,
        netAmount: net
    };

    if (editingId) {
        confirmAction('Update Data?', 'Ubah data draft ini?', () => {
            updateWeeklyData(editingId, payload);
            cancelEdit();
            Swal.fire('Berhasil!', 'Data telah diupdate.', 'success');
        });
    } else {
        confirmAction('Simpan Data?', 'Data akan masuk ke dashboard Preview', () => {
            addWeeklyData(payload);
            // REVISI 3: Partial Reset
            setWeekForm(prev => ({ ...prev, rt: '', gross: '' }));
            setEditingId(null);
            Swal.fire('Berhasil!', 'Data disimpan.', 'success');
        });
    }
  };

  const handleEditWeek = (data: any) => {
    setEditingId(data.id);
    setWeekForm({ date: data.date, week: data.week, rt: data.rt, gross: formatNumberInput(data.grossAmount) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 3. DONOR & EXPENSE (Standard Local CRUD for now)
  const handleSaveDonor = () => {
    if(!donorForm.name || !donorForm.nominal) return;
    const nominal = parseNumberInput(donorForm.nominal);
    if (editingId) {
        updateDonor(editingId, { date: donorForm.date, name: donorForm.name, nominal: nominal });
        cancelEdit();
    } else {
        addDonor({ date: donorForm.date, name: donorForm.name, nominal: nominal });
        cancelEdit();
    }
    Swal.fire('Berhasil', 'Data tersimpan', 'success');
  };
  const handleEditDonor = (data: any) => {
    setEditingId(data.id);
    setDonorForm({ date: data.date, name: data.name, nominal: formatNumberInput(data.nominal) });
  };

  const handleSaveExp = () => {
    if(!expForm.purpose || !expForm.nominal) return;
    const nominal = parseNumberInput(expForm.nominal);
    if (editingId) {
        updateExpense(editingId, { date: expForm.date, purpose: expForm.purpose, nominal: nominal });
        cancelEdit();
    } else {
        addExpense({ date: expForm.date, purpose: expForm.purpose, nominal: nominal });
        cancelEdit();
    }
    Swal.fire('Berhasil', 'Data tersimpan', 'success');
  };
  const handleEditExp = (data: any) => {
    setEditingId(data.id);
    setExpForm({ date: data.date, purpose: data.purpose, nominal: formatNumberInput(data.nominal) });
  };

  // UI HELPERS
  const tabClass = (tab: string) => 
    `flex-1 text-center md:flex-none px-2 py-2 md:px-4 md:py-3 rounded-t-lg font-bold text-xs md:text-sm transition-colors ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`;
  const inputClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg px-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm";
  const inputRpClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg pl-8 md:pl-10 pr-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm font-mono tracking-wide";

  return (
    <div className="space-y-4 md:space-y-6">
      <h2 className="text-sm md:text-xl font-bold text-gray-800 border-b pb-2">
          {editingId ? `Edit Data ${editingSource === 'published' ? '(Database)' : '(Draft)'}` : 'Input Data Keuangan'}
      </h2>

      {/* Tabs */}
      <div className={`flex flex-row gap-1 overflow-x-auto no-scrollbar ${editingId ? 'opacity-50 pointer-events-none' : ''}`}>
        <button onClick={() => setActiveTab('previous')} className={tabClass('previous')}>Panitia</button>
        <button onClick={() => setActiveTab('weekly')} className={tabClass('weekly')}>Mingguan</button>
        <button onClick={() => setActiveTab('donor')} className={tabClass('donor')}>Donatur</button>
        <button onClick={() => setActiveTab('expense')} className={tabClass('expense')}>Keluar</button>
      </div>

      <div className="bg-white p-3 md:p-6 rounded-b-lg shadow-md border border-gray-200">

        {/* === 1. PREVIOUS FUNDS (HYBRID LIST) === */}
        {activeTab === 'previous' && (
          <div className="space-y-4 md:space-y-6">
            <div className={`grid grid-cols-1 md:grid-cols-3 gap-3 bg-gray-50 p-3 rounded-lg border ${editingId ? 'border-blue-400 bg-blue-50' : 'border-gray-200'}`}>
                <div className="w-full">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input type="date" value={prevForm.date} onChange={e => setPrevForm({...prevForm, date: e.target.value})} className={inputClass} style={{colorScheme: 'light'}} />
                </div>
                <div className="w-full">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Nominal</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input type="text" inputMode="numeric" placeholder="0" value={prevForm.nominal} onChange={e => setPrevForm({...prevForm, nominal: formatNumberInput(e.target.value)})} className={inputRpClass} />
                    </div>
                </div>
                <div className="flex items-end w-full">
                     <div className="flex gap-2 w-full">
                        {editingId && (
                            <button onClick={cancelEdit} className="w-1/3 bg-gray-500 text-white py-2 rounded-lg font-bold text-xs flex items-center justify-center gap-1"><XCircle size={14}/> Batal</button>
                        )}
                        <button onClick={handleSavePrev} className="flex-1 bg-primary hover:bg-emerald-800 text-white py-2 rounded-lg font-bold text-xs flex items-center justify-center gap-2">
                            {editingId ? <Pencil size={14}/> : <Save size={14}/>} {editingId ? (editingSource === 'published' ? 'UPDATE DB' : 'UPDATE DRAFT') : 'SIMPAN'}
                        </button>
                     </div>
                </div>
            </div>

            {/* Desktop Table - HYBRID */}
            <div className="hidden md:block">
              <table className="w-full text-sm text-left">
                  <thead className="bg-gray-100 uppercase text-gray-700"><tr><th className="p-3">Status</th><th className="p-3">Tgl</th><th className="p-3">Nominal</th><th className="p-3">Aksi</th></tr></thead>
                  <tbody>
                      {allPreviousFunds.map((d: any) => (
                          <tr key={d.id} className={`border-b ${editingId === d.id ? 'bg-blue-50' : ''}`}>
                              <td className="p-3">
                                  {d.source === 'published' ? 
                                    <span className="flex items-center gap-1 text-green-600 text-[10px] font-bold bg-green-50 px-2 py-0.5 rounded-full w-fit"><CheckCircle size={10}/> Publish</span> : 
                                    <span className="flex items-center gap-1 text-orange-600 text-[10px] font-bold bg-orange-50 px-2 py-0.5 rounded-full w-fit"><Clock size={10}/> Draft</span>
                                  }
                              </td>
                              <td className="p-3">{formatDate(d.date)}</td>
                              <td className="p-3 font-bold">{formatCurrency(d.nominal)}</td>
                              <td className="p-3 flex gap-2">
                                  <button onClick={() => handleEditPrev(d)} className="text-blue-600 bg-blue-50 p-2 rounded-full hover:bg-blue-100"><Pencil size={14}/></button>
                                  <button onClick={() => confirmDelete(d.id, d.source, 'previous')} className="text-red-600 bg-red-50 p-2 rounded-full hover:bg-red-100"><Trash2 size={14}/></button>
                              </td>
                          </tr>
                      ))}
                  </tbody>
              </table>
            </div>

             {/* Mobile Cards - HYBRID */}
             <div className="md:hidden space-y-2">
               {allPreviousFunds.map((d: any) => (
                 <div key={d.id} className={`border p-3 rounded-lg shadow-sm flex justify-between items-center ${d.source === 'published' ? 'border-green-200 bg-white' : 'border-orange-200 bg-orange-50/30'}`}>
                    <div>
                        <div className="flex gap-2 items-center mb-1">
                            <span className={`text-[9px] font-bold px-1.5 rounded ${d.source === 'published' ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>
                                {d.source === 'published' ? 'PUBLISH' : 'DRAFT'}
                            </span>
                            <span className="text-[10px] text-gray-500">{formatDate(d.date)}</span>
                        </div>
                        <p className="font-bold text-gray-800 text-sm">{formatCurrency(d.nominal)}</p>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={() => handleEditPrev(d)} className="bg-blue-50 text-blue-600 p-2 rounded-lg"><Pencil size={16}/></button>
                        <button onClick={() => confirmDelete(d.id, d.source, 'previous')} className="bg-red-50 text-red-600 p-2 rounded-lg"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* === 2. WEEKLY FORM (Draft Only View) === */}
        {activeTab === 'weekly' && (
          <div className="space-y-4 md:space-y-6">
            <div className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3 bg-gray-50 p-3 rounded-lg border ${editingId ? 'border-blue-400 bg-blue-50' : 'border-gray-200'}`}>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input type="date" value={weekForm.date} onChange={e => setWeekForm({...weekForm, date: e.target.value})} className={inputClass} style={{colorScheme: 'light'}} />
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Minggu Ke</label>
                    <select value={weekForm.week} onChange={e => setWeekForm({...weekForm, week: e.target.value})} className={inputClass}>
                        {[...Array(30)].map((_, i) => <option key={i} value={`Minggu ke-${i+1}`}>Minggu ke-{i+1}</option>)}
                    </select>
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">RT</label>
                    <select value={weekForm.rt} onChange={e => setWeekForm({...weekForm, rt: e.target.value})} className={inputClass}>
                        <option value="">Pilih RT</option>
                        {[...Array(6)].map((_, i) => <option key={i} value={`RT 0${i+1}`}>RT 0{i+1}</option>)}
                    </select>
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Pemasukan Kotor</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input type="text" inputMode="numeric" placeholder="0" value={weekForm.gross} onChange={e => setWeekForm({...weekForm, gross: formatNumberInput(e.target.value)})} className={inputRpClass} />
                    </div>
                </div>
                <div className="col-span-1 md:col-span-2 lg:col-span-1 flex items-end">
                    <button onClick={handleSaveWeek} className="w-full bg-primary hover:bg-emerald-800 text-white py-2 rounded-lg font-bold text-xs flex items-center justify-center gap-2">
                        <Save size={14}/> SIMPAN
                    </button>
                </div>
            </div>

            <div className="hidden md:block overflow-x-auto">
                <table className="w-full text-sm text-left">
                    <thead className="bg-gray-100 uppercase text-gray-700">
                        <tr><th className="p-3">Minggu/RT</th><th className="p-3">Kotor</th><th className="p-3 text-red-500">5%</th><th className="p-3 text-red-500">10%</th><th className="p-3 text-green-700">Bersih</th><th className="p-3">Aksi</th></tr>
                    </thead>
                    <tbody>
                        {stagedData.weeklyData.map(d => (
                            <tr key={d.id} className="border-b hover:bg-gray-50">
                                <td className="p-3 font-medium">{d.week} - {d.rt}</td>
                                <td className="p-3">{formatCurrency(d.grossAmount)}</td>
                                <td className="p-3 text-red-500">-{formatCurrency(d.consumptionCut)}</td>
                                <td className="p-3 text-red-500">-{formatCurrency(d.commissionCut)}</td>
                                <td className="p-3 font-bold text-green-700">{formatCurrency(d.netAmount)}</td>
                                <td className="p-3 flex gap-2">
                                    <button onClick={() => handleEditWeek(d)} className="text-blue-600 bg-blue-50 p-2 rounded-full"><Pencil size={14}/></button>
                                    <button onClick={() => confirmDelete(d.id, 'staged', 'weekly')} className="text-red-600 bg-red-50 p-2 rounded-full"><Trash2 size={14}/></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            <div className="md:hidden space-y-2">
               {stagedData.weeklyData.map(d => (
                 <div key={d.id} className="border border-gray-200 p-3 rounded-lg shadow-sm bg-white">
                    <div className="flex justify-between items-center mb-2 pb-1 border-b border-gray-100">
                        <div className="flex items-center gap-2">
                             <span className="font-bold text-gray-800 text-xs">{d.week}</span>
                             <span className="bg-emerald-50 text-emerald-700 text-[10px] px-1.5 py-0.5 rounded border border-emerald-100">{d.rt}</span>
                        </div>
                        <div className="flex gap-2">
                            <button onClick={() => handleEditWeek(d)} className="text-blue-600 bg-blue-50 p-1.5 rounded"><Pencil size={14}/></button>
                            <button onClick={() => confirmDelete(d.id, 'staged', 'weekly')} className="text-red-600 bg-red-50 p-1.5 rounded"><Trash2 size={14}/></button>
                        </div>
                    </div>
                    <div className="text-[10px] space-y-1">
                        <div className="flex justify-between text-gray-600"><span>Kotor:</span><span className="font-medium">{formatCurrency(d.grossAmount)}</span></div>
                        <div className="flex justify-between font-bold text-primary border-t pt-1 mt-1"><span>Bersih:</span><span className="text-xs">{formatCurrency(d.netAmount)}</span></div>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* === 3. DONOR & EXPENSE (Simple Views) === */}
        {(activeTab === 'donor' || activeTab === 'expense') && (
            <div className="text-center py-10 text-gray-400 text-sm">
                <p>Form {activeTab === 'donor' ? 'Donatur' : 'Pengeluaran'} (Implementasi serupa dengan Panitia/Mingguan)</p>
                {activeTab === 'donor' ? (
                     <div className="mt-4 text-left">
                         {/* Simple Donor Form */}
                         <div className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-gray-50 p-3 rounded-lg border mb-4">
                             <div className="col-span-1"><input type="date" value={donorForm.date} onChange={e=>setDonorForm({...donorForm, date: e.target.value})} className={inputClass} /></div>
                             <div className="col-span-1 md:col-span-2"><input type="text" placeholder="Sumber Dana" value={donorForm.name} onChange={e=>setDonorForm({...donorForm, name: e.target.value})} className={inputClass} /></div>
                             <div className="col-span-1"><input type="text" placeholder="Rp" value={donorForm.nominal} onChange={e=>setDonorForm({...donorForm, nominal: formatNumberInput(e.target.value)})} className={inputRpClass} /></div>
                             <div className="col-span-full"><button onClick={handleSaveDonor} className="w-full bg-primary text-white py-2 rounded-lg font-bold text-xs"><Save size={14} className="inline mr-2"/>SIMPAN</button></div>
                         </div>
                         {stagedData.donors.map(d => (
                             <div key={d.id} className="flex justify-between p-2 border-b text-sm">
                                 <span>{d.name}</span><span>{formatCurrency(d.nominal)}</span>
                                 <button onClick={()=>confirmDelete(d.id, 'staged', 'donor')} className="text-red-500"><Trash2 size={14}/></button>
                             </div>
                         ))}
                     </div>
                ) : (
                    <div className="mt-4 text-left">
                        {/* Simple Expense Form */}
                         <div className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-gray-50 p-3 rounded-lg border mb-4">
                             <div className="col-span-1"><input type="date" value={expForm.date} onChange={e=>setExpForm({...expForm, date: e.target.value})} className={inputClass} /></div>
                             <div className="col-span-1 md:col-span-2"><input type="text" placeholder="Keperluan" value={expForm.purpose} onChange={e=>setExpForm({...expForm, purpose: e.target.value})} className={inputClass} /></div>
                             <div className="col-span-1"><input type="text" placeholder="Rp" value={expForm.nominal} onChange={e=>setExpForm({...expForm, nominal: formatNumberInput(e.target.value)})} className={inputRpClass} /></div>
                             <div className="col-span-full"><button onClick={handleSaveExp} className="w-full bg-primary text-white py-2 rounded-lg font-bold text-xs"><Save size={14} className="inline mr-2"/>SIMPAN</button></div>
                         </div>
                         {stagedData.expenses.map(d => (
                             <div key={d.id} className="flex justify-between p-2 border-b text-sm">
                                 <span>{d.purpose}</span><span className="text-red-600">{formatCurrency(d.nominal)}</span>
                                 <button onClick={()=>confirmDelete(d.id, 'staged', 'expense')} className="text-red-500"><Trash2 size={14}/></button>
                             </div>
                         ))}
                    </div>
                )}
            </div>
        )}

      </div>
    </div>
  );
};

export default InputSection;

import React, { useState } from 'react';
import { useData } from '../../context/DataContext';
import { formatDate, formatCurrency, calculateWeeklyCuts } from '../../utils/format';
import Swal from 'sweetalert2';
import { Trash2, Save, Pencil, XCircle, CheckCircle, Clock } from 'lucide-react';

const InputSection: React.FC = () => {
  const { 
    stagedData, 
    publishedData, 
    addPreviousFund, updatePreviousFund, deletePreviousFund, 
    addWeeklyData, updateWeeklyData, deleteWeeklyData, 
    addDonor, updateDonor, deleteDonor, 
    addExpense, updateExpense, deleteExpense,
    // New Context Methods for Direct DB Manipulation
    updatePublishedItem, deletePublishedItem
  } = useData();

  const [activeTab, setActiveTab] = useState<'previous' | 'weekly' | 'donor' | 'expense'>('previous');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingSource, setEditingSource] = useState<'staged' | 'published'>('staged');

  // Form States
  const [prevForm, setPrevForm] = useState({ date: '', nominal: '' });
  const [weekForm, setWeekForm] = useState({ date: '', week: 'Minggu ke-1', rt: 'RT 01', gross: '' });
  const [donorForm, setDonorForm] = useState({ date: '', name: '', nominal: '' });
  const [expForm, setExpForm] = useState({ date: '', purpose: '', nominal: '' });

  // --- MERGE LIST FOR DISPLAY (HYBRID: STAGED + PUBLISHED) ---
  const allPreviousFunds = [
      ...stagedData.previousFunds.map(i => ({ ...i, source: 'staged' })),
      ...publishedData.previousFunds.map(i => ({ ...i, source: 'published' }))
  ];

  const allDonors = [
      ...stagedData.donors.map(i => ({ ...i, source: 'staged' })),
      ...publishedData.donors.map(i => ({ ...i, source: 'published' }))
  ];

  const allExpenses = [
      ...stagedData.expenses.map(i => ({ ...i, source: 'staged' })),
      ...publishedData.expenses.map(i => ({ ...i, source: 'published' }))
  ];

  // Helper: Format tampilan saat mengetik
  const formatNumberInput = (value: string | number) => {
    if (!value) return '';
    const valString = value.toString();
    const rawValue = valString.replace(/\D/g, ''); 
    return new Intl.NumberFormat('id-ID').format(Number(rawValue));
  };

  const parseNumberInput = (value: string) => {
    if (!value) return 0;
    return Number(value.replace(/\./g, ''));
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditingSource('staged');
    setPrevForm({ date: '', nominal: '' });
    setWeekForm({ date: '', week: 'Minggu ke-1', rt: 'RT 01', gross: '' });
    setDonorForm({ date: '', name: '', nominal: '' });
    setExpForm({ date: '', purpose: '', nominal: '' });
  };

  const confirmAction = (title: string, text: string, callback: () => void) => {
    Swal.fire({
      title: title,
      text: text,
      icon: 'question',
      showCancelButton: true,
      confirmButtonColor: '#047857',
      cancelButtonColor: '#d33',
      confirmButtonText: 'Ya, Lanjutkan',
      cancelButtonText: 'Batal'
    }).then((result) => {
      if (result.isConfirmed) {
        callback();
      }
    });
  };

  const confirmDelete = (id: string, source: 'staged' | 'published', type: 'previous' | 'weekly' | 'donor' | 'expense') => {
    Swal.fire({
      title: source === 'published' ? 'Hapus dari Database?' : 'Hapus Draft?',
      text: source === 'published' ? 'Data ini sudah dipublikasikan. Menghapusnya akan langsung hilang dari website publik.' : 'Data ini belum dipublikasikan.',
      icon: 'warning',
      showCancelButton: true,
      confirmButtonColor: '#d33',
      cancelButtonColor: '#3085d6',
      confirmButtonText: 'Ya, Hapus',
      cancelButtonText: 'Batal'
    }).then(async (result) => {
      if (result.isConfirmed) {
         if (source === 'staged') {
             // Local Deletion
             if (type === 'previous') deletePreviousFund(id);
             if (type === 'weekly') deleteWeeklyData(id);
             if (type === 'donor') deleteDonor(id);
             if (type === 'expense') deleteExpense(id);
             Swal.fire('Terhapus', 'Data draft dihapus.', 'success');
         } else {
             // Direct DB Deletion
             let table = '';
             if (type === 'previous') table = 'previous_funds';
             if (type === 'weekly') table = 'weekly_data'; 
             if (type === 'donor') table = 'donors';
             if (type === 'expense') table = 'expenses';

             if (table) {
                const success = await deletePublishedItem(table, id);
                if (success) Swal.fire('Terhapus', 'Data database berhasil dihapus.', 'success');
             }
         }
         if (editingId === id) cancelEdit(); 
      }
    });
  };

  // --- HANDLERS ---

  // 1. PREVIOUS FUNDS (PANITIA)
  const handleSavePrev = () => {
    if (!prevForm.date || !prevForm.nominal) return;
    const nominal = parseNumberInput(prevForm.nominal);

    if (editingId) {
       confirmAction('Update Data?', editingSource === 'published' ? 'Update Database Langsung?' : 'Update Draft?', async () => {
         if (editingSource === 'published') {
             const success = await updatePublishedItem('previous_funds', editingId, { date: prevForm.date, nominal: nominal });
             if (success) { Swal.fire('Sukses', 'Database updated', 'success'); cancelEdit(); }
         } else {
             updatePreviousFund(editingId, { date: prevForm.date, nominal: nominal });
             cancelEdit();
             Swal.fire('Sukses', 'Draft updated', 'success');
         }
       });
    } else {
       confirmAction('Simpan Data?', 'Simpan ke Draft?', () => {
         addPreviousFund({ date: prevForm.date, nominal: nominal });
         setEditingId(null); 
         Swal.fire('Berhasil!', 'Data disimpan ke draft.', 'success');
       });
    }
  };

  const handleEditPrev = (data: any) => {
    setEditingId(data.id);
    setEditingSource(data.source || 'staged');
    setPrevForm({ date: data.date, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 2. WEEKLY DATA
  const handleSaveWeek = () => {
    if (!weekForm.date || !weekForm.gross) return;

    // Check Duplicate
    const isDuplicateStaged = stagedData.weeklyData.some(i => i.week === weekForm.week && i.rt === weekForm.rt && i.id !== editingId);
    const isDuplicatePublished = publishedData.weeklyData.some(i => i.week === weekForm.week && i.rt === weekForm.rt);

    if (isDuplicateStaged || isDuplicatePublished) {
        Swal.fire({ icon: 'warning', title: 'Data Duplikat', text: `${weekForm.week} - ${weekForm.rt} sudah ada.` });
        return;
    }

    const gross = parseNumberInput(weekForm.gross);
    const { consumption, commission, net } = calculateWeeklyCuts(gross);
    const payload = { date: weekForm.date, week: weekForm.week, rt: weekForm.rt, grossAmount: gross, consumptionCut: consumption, commissionCut: commission, netAmount: net };

    if (editingId) {
        confirmAction('Update Data?', 'Update Draft?', () => {
            updateWeeklyData(editingId, payload);
            cancelEdit();
            Swal.fire('Berhasil!', 'Data diupdate.', 'success');
        });
    } else {
        confirmAction('Simpan Data?', 'Simpan ke Draft?', () => {
            addWeeklyData(payload);
            setWeekForm(prev => ({ ...prev, rt: '', gross: '' }));
            setEditingId(null);
            Swal.fire('Berhasil!', 'Data disimpan.', 'success');
        });
    }
  };

  const handleEditWeek = (data: any) => {
    setEditingId(data.id);
    setWeekForm({ date: data.date, week: data.week, rt: data.rt, gross: formatNumberInput(data.grossAmount) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 3. DONOR DATA (Full UI)
  const handleSaveDonor = () => {
    if(!donorForm.name || !donorForm.nominal) return;
    const nominal = parseNumberInput(donorForm.nominal);

    if (editingId) {
        confirmAction('Update Data?', editingSource === 'published' ? 'Update Database Langsung?' : 'Update Draft?', async () => {
            if (editingSource === 'published') {
                const success = await updatePublishedItem('donors', editingId, { date: donorForm.date, name: donorForm.name, nominal: nominal });
                if (success) { Swal.fire('Sukses', 'Database updated', 'success'); cancelEdit(); }
            } else {
                updateDonor(editingId, { date: donorForm.date, name: donorForm.name, nominal: nominal });
                cancelEdit();
                Swal.fire('Sukses', 'Draft updated', 'success');
            }
        });
    } else {
        confirmAction('Simpan Data?', 'Simpan ke Draft?', () => {
            addDonor({ date: donorForm.date, name: donorForm.name, nominal: nominal });
            // Partial Reset: Keep Date, clear Name & Nominal
            setDonorForm(prev => ({ ...prev, name: '', nominal: '' }));
            setEditingId(null);
            Swal.fire('Berhasil', 'Data tersimpan', 'success');
        });
    }
  };

  const handleEditDonor = (data: any) => {
    setEditingId(data.id);
    setEditingSource(data.source || 'staged');
    setDonorForm({ date: data.date, name: data.name, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // 4. EXPENSE DATA (Full UI)
  const handleSaveExp = () => {
    if(!expForm.purpose || !expForm.nominal) return;
    const nominal = parseNumberInput(expForm.nominal);

    if (editingId) {
        confirmAction('Update Data?', editingSource === 'published' ? 'Update Database Langsung?' : 'Update Draft?', async () => {
            if (editingSource === 'published') {
                const success = await updatePublishedItem('expenses', editingId, { date: expForm.date, purpose: expForm.purpose, nominal: nominal });
                if (success) { Swal.fire('Sukses', 'Database updated', 'success'); cancelEdit(); }
            } else {
                updateExpense(editingId, { date: expForm.date, purpose: expForm.purpose, nominal: nominal });
                cancelEdit();
                Swal.fire('Sukses', 'Draft updated', 'success');
            }
        });
    } else {
        confirmAction('Simpan Data?', 'Simpan ke Draft?', () => {
            addExpense({ date: expForm.date, purpose: expForm.purpose, nominal: nominal });
            // Partial Reset: Keep Date, clear Purpose & Nominal
            setExpForm(prev => ({ ...prev, purpose: '', nominal: '' }));
            setEditingId(null);
            Swal.fire('Berhasil', 'Data tersimpan', 'success');
        });
    }
  };

  const handleEditExp = (data: any) => {
    setEditingId(data.id);
    setEditingSource(data.source || 'staged');
    setExpForm({ date: data.date, purpose: data.purpose, nominal: formatNumberInput(data.nominal) });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // UI HELPERS
  const tabClass = (tab: string) => 
    `flex-1 text-center md:flex-none px-2 py-2 md:px-4 md:py-3 rounded-t-lg font-bold text-xs md:text-sm transition-colors ${activeTab === tab ? 'bg-primary text-white shadow-lg' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`;
  const inputClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg px-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm";
  const inputRpClass = "w-full bg-white border border-gray-300 text-gray-900 text-xs md:text-sm rounded-lg pl-8 md:pl-10 pr-3 py-2 focus:outline-none focus:ring-1 focus:ring-primary focus:border-primary shadow-sm font-mono tracking-wide";

  const renderStatusBadge = (source: string) => (
      source === 'published' ? 
      <span className="flex items-center gap-1 text-green-600 text-[10px] font-bold bg-green-50 px-2 py-0.5 rounded-full w-fit"><CheckCircle size={10}/> Publish</span> : 
      <span className="flex items-center gap-1 text-orange-600 text-[10px] font-bold bg-orange-50 px-2 py-0.5 rounded-full w-fit"><Clock size={10}/> Draft</span>
  );

  return (
    <div className="space-y-4 md:space-y-6">
      <h2 className="text-sm md:text-xl font-bold text-gray-800 border-b pb-2">
          {editingId ? `Edit Data ${editingSource === 'published' ? '(Database)' : '(Draft)'}` : 'Input Data Keuangan'}
      </h2>

      {/* Tabs */}
      <div className={`flex flex-row gap-1 overflow-x-auto no-scrollbar ${editingId ? 'opacity-50 pointer-events-none' : ''}`}>
        <button onClick={() => setActiveTab('previous')} className={tabClass('previous')}>Panitia</button>
        <button onClick={() => setActiveTab('weekly')} className={tabClass('weekly')}>Mingguan</button>
        <button onClick={() => setActiveTab('donor')} className={tabClass('donor')}>Donatur</button>
        <button onClick={() => setActiveTab('expense')} className={tabClass('expense')}>Keluar</button>
      </div>

      <div className="bg-white p-3 md:p-6 rounded-b-lg shadow-md border border-gray-200">

        {/* === 1. PREVIOUS FUNDS === */}
        {activeTab === 'previous' && (
          <div className="space-y-4 md:space-y-6">
            <div className={`grid grid-cols-1 md:grid-cols-3 gap-3 bg-gray-50 p-3 rounded-lg border ${editingId ? 'border-blue-400 bg-blue-50' : 'border-gray-200'}`}>
                <div className="w-full">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input type="date" value={prevForm.date} onChange={e => setPrevForm({...prevForm, date: e.target.value})} className={inputClass} style={{colorScheme: 'light'}} />
                </div>
                <div className="w-full">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Nominal</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input type="text" inputMode="numeric" placeholder="0" value={prevForm.nominal} onChange={e => setPrevForm({...prevForm, nominal: formatNumberInput(e.target.value)})} className={inputRpClass} />
                    </div>
                </div>
                <div className="flex items-end w-full">
                     <div className="flex gap-2 w-full">
                        {editingId && (
                            <button onClick={cancelEdit} className="w-1/3 bg-gray-500 text-white py-2 rounded-lg font-bold text-xs flex items-center justify-center gap-1"><XCircle size={14}/> Batal</button>
                        )}
                        <button onClick={handleSavePrev} className="flex-1 bg-primary hover:bg-emerald-800 text-white py-2 rounded-lg font-bold text-xs flex items-center justify-center gap-2">
                            {editingId ? <Pencil size={14}/> : <Save size={14}/>} {editingId ? (editingSource === 'published' ? 'UPDATE DB' : 'UPDATE DRAFT') : 'SIMPAN'}
                        </button>
                     </div>
                </div>
            </div>

            {/* Table Hybrid */}
            <div className="hidden md:block">
              <table className="w-full text-sm text-left">
                  <thead className="bg-gray-100 uppercase text-gray-700"><tr><th className="p-3">Status</th><th className="p-3">Tgl</th><th className="p-3">Nominal</th><th className="p-3">Aksi</th></tr></thead>
                  <tbody>
                      {allPreviousFunds.map((d: any) => (
                          <tr key={d.id} className={`border-b ${editingId === d.id ? 'bg-blue-50' : ''}`}>
                              <td className="p-3">{renderStatusBadge(d.source)}</td>
                              <td className="p-3">{formatDate(d.date)}</td>
                              <td className="p-3 font-bold">{formatCurrency(d.nominal)}</td>
                              <td className="p-3 flex gap-2">
                                  <button onClick={() => handleEditPrev(d)} className="text-blue-600 bg-blue-50 p-2 rounded-full"><Pencil size={14}/></button>
                                  <button onClick={() => confirmDelete(d.id, d.source, 'previous')} className="text-red-600 bg-red-50 p-2 rounded-full"><Trash2 size={14}/></button>
                              </td>
                          </tr>
                      ))}
                  </tbody>
              </table>
            </div>

             {/* Mobile Cards */}
             <div className="md:hidden space-y-2">
               {allPreviousFunds.map((d: any) => (
                 <div key={d.id} className={`border p-3 rounded-lg shadow-sm flex justify-between items-center ${d.source === 'published' ? 'border-green-200 bg-white' : 'border-orange-200 bg-orange-50/30'}`}>
                    <div>
                        <div className="flex gap-2 items-center mb-1">{renderStatusBadge(d.source)}<span className="text-[10px] text-gray-500">{formatDate(d.date)}</span></div>
                        <p className="font-bold text-gray-800 text-sm">{formatCurrency(d.nominal)}</p>
                    </div>
                    <div className="flex gap-2">
                        <button onClick={() => handleEditPrev(d)} className="bg-blue-50 text-blue-600 p-2 rounded-lg"><Pencil size={16}/></button>
                        <button onClick={() => confirmDelete(d.id, d.source, 'previous')} className="bg-red-50 text-red-600 p-2 rounded-lg"><Trash2 size={16}/></button>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}

        {/* === 2. WEEKLY FORM === */}
        {activeTab === 'weekly' && (
          <div className="space-y-4 md:space-y-6">
            <div className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-3 bg-gray-50 p-3 rounded-lg border ${editingId ? 'border-blue-400 bg-blue-50' : 'border-gray-200'}`}>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Tanggal</label>
                    <input type="date" value={weekForm.date} onChange={e => setWeekForm({...weekForm, date: e.target.value})} className={inputClass} style={{colorScheme: 'light'}} />
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Minggu Ke</label>
                    <select value={weekForm.week} onChange={e => setWeekForm({...weekForm, week: e.target.value})} className={inputClass}>
                        {[...Array(30)].map((_, i) => <option key={i} value={`Minggu ke-${i+1}`}>Minggu ke-{i+1}</option>)}
                    </select>
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">RT</label>
                    <select value={weekForm.rt} onChange={e => setWeekForm({...weekForm, rt: e.target.value})} className={inputClass}>
                        <option value="">Pilih RT</option>
                        {[...Array(6)].map((_, i) => <option key={i} value={`RT 0${i+1}`}>RT 0{i+1}</option>)}
                    </select>
                </div>
                <div className="col-span-1">
                    <label className="block text-[10px] text-gray-500 mb-1 font-semibold">Pemasukan Kotor</label>
                    <div className="relative">
                        <span className="absolute left-2 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold text-xs pointer-events-none">Rp.</span>
                        <input type="text" inputMode="numeric" placeholder="0" value={weekForm.gross} onChange={e => setWeekForm({...weekForm, gross: formatNumberInput(e.target.value)})} className={inputRpClass} />
                    </div>
                </div>
                <div className="col-span-1 md:col-span-2 lg:col-span-1 flex items-end">
                    <button onClick={handleSaveWeek} className="w-full bg-primary hover:bg-emerald-800 text-white py-2 rounded-lg font-bold text-xs flex items-center justify-center gap-2">
                        <Save size={14}/> SIMPAN
                    </button>
                </div>
            </div>

            <div className="hidden md:block overflow-x-auto">
