             cancelEdit();
             Swal.fire('Sukses', 'Draft updated', 'success');
         }
       });
    } else {
       confirmAction('Simpan Data?', 'Simpan ke Draft?', () => {
         addPreviousFund({ date: prevForm.date, nominal: nominal });
         setEditingId(null); 
         Swal.fire('Berhasil!', 'Data disimpan ke draft.', 'success');
