                <div className="col-span-1 md:col-span-2 lg:col-span-1 flex items-end">
                    <div className="flex gap-2 w-full">
                        {editingId && (
                            <button onClick={cancelEdit} className="w-1/3 bg-gray-500 text-white py-1.5 md:py-2 rounded-lg font-bold text-[10px] md:text-xs flex items-center justify-center gap-1"><XCircle size={12} className="md:w-3.5 md:h-3.5"/> Batal</button>
