                { content: formatCurrency(subNet), styles: { fontStyle: 'bold', halign: 'right', textColor: [6, 78, 59], fillColor: [236, 253, 245] } }
            ]);
            // Reset subtotal
            subGross = 0; subCons = 0; subComm = 0; subNet = 0;
        }

        currentWeek = item.week;
        subGross += item.grossAmount;
        subCons += item.consumptionCut;
        subComm += item.commissionCut;
        subNet += item.netAmount;

        // Masukkan baris data
        rows.push([
            item.week,
            item.rt,
            formatDate(item.date),
            formatCurrency(item.grossAmount),
            formatCurrency(item.consumptionCut),
            formatCurrency(item.commissionCut),
            formatCurrency(item.netAmount)
        ]);

        // Jika ini item terakhir, jangan lupa masukkan subtotal terakhir
        if (index === sortedWeekly.length - 1) {
             rows.push([
                { content: `Total ${currentWeek}`, colSpan: 3, styles: { fontStyle: 'bold', halign: 'right', fillColor: [236, 253, 245] } },
                { content: formatCurrency(subGross), styles: { fontStyle: 'bold', halign: 'right', fillColor: [236, 253, 245] } },
                { content: formatCurrency(subCons), styles: { fontStyle: 'bold', halign: 'right', textColor: [220, 38, 38], fillColor: [236, 253, 245] } },
                { content: formatCurrency(subComm), styles: { fontStyle: 'bold', halign: 'right', textColor: [220, 38, 38], fillColor: [236, 253, 245] } },
                { content: formatCurrency(subNet), styles: { fontStyle: 'bold', halign: 'right', textColor: [6, 78, 59], fillColor: [236, 253, 245] } }
            ]);
        }
    });

    autoTable(doc, {
      startY: startY,
      head: [['Minggu', 'RT', 'Tanggal', 'Pemasukan Kotor', 'Potongan 5%', 'Potongan 10%', 'Pendapatan Bersih']],
      body: rows,
      theme: 'grid',
      styles: compactStyles,
      headStyles: { ...compactHeadStyles, fillColor: [6, 78, 59] }, 
      margin: { top: 20, bottom: 20 },
      columnStyles: {
          0: { cellWidth: 25, halign: 'center' }, // Minggu
          1: { cellWidth: 15, halign: 'center' }, // RT
          2: { cellWidth: 25, halign: 'center' }, // Tanggal
          3: { halign: 'right' },
          4: { halign: 'right', textColor: [220, 38, 38] }, // Merah
          5: { halign: 'right', textColor: [220, 38, 38] }, // Merah
          6: { halign: 'right', fontStyle: 'bold' }
      },
      footStyles: { ...compactStyles, fontStyle: 'bold', fillColor: [209, 250, 229], textColor: [0, 0, 0] },
      foot: [[
        { content: 'TOTAL PENDAPATAN BERSIH', colSpan: 3, styles: { halign: 'right', fontSize: 8 } },
        { content: formatCurrency(data.weeklyData.reduce((a,b)=>a+b.grossAmount,0)), styles: { halign: 'right' } },
        { content: formatCurrency(data.weeklyData.reduce((a,b)=>a+b.consumptionCut,0)), styles: { halign: 'right' } },
        { content: formatCurrency(data.weeklyData.reduce((a,b)=>a+b.commissionCut,0)), styles: { halign: 'right' } },
