// Helper: Fungsi Terbilang (Angka ke Kata)
const terbilang = (nilai: number): string => {
  const bilangan = Math.abs(nilai);
  const angka = ["", "Satu", "Dua", "Tiga", "Empat", "Lima", "Enam", "Tujuh", "Delapan", "Sembilan", "Sepuluh", "Sebelas"];
  let temp = "";

  if (bilangan < 12) {
    temp = " " + angka[bilangan];
  } else if (bilangan < 20) {
    temp = terbilang(bilangan - 10) + " Belas ";
  } else if (bilangan < 100) {
    temp = terbilang(Math.floor(bilangan / 10)) + " Puluh " + terbilang(bilangan % 10);
  } else if (bilangan < 200) {
    temp = " Seratus" + terbilang(bilangan - 100);
  } else if (bilangan < 1000) {
    temp = terbilang(Math.floor(bilangan / 100)) + " Ratus " + terbilang(bilangan % 100);
  } else if (bilangan < 2000) {
    temp = " Seribu" + terbilang(bilangan - 1000);
  } else if (bilangan < 1000000) {
    temp = terbilang(Math.floor(bilangan / 1000)) + " Ribu " + terbilang(bilangan % 1000);
  } else if (bilangan < 1000000000) {
    temp = terbilang(Math.floor(bilangan / 1000000)) + " Juta " + terbilang(bilangan % 1000000);
  } else if (bilangan < 1000000000000) {
    temp = terbilang(Math.floor(bilangan / 1000000000)) + " Milyar" + terbilang(bilangan % 1000000000);
  }

  return temp.trim();
}

// Helper untuk memuat gambar menjadi Base64
const getBase64ImageFromURL = (url: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "Anonymous";
    img.src = url;
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext("2d");
      ctx?.drawImage(img, 0, 0);
      const dataURL = canvas.toDataURL("image/png");
      resolve(dataURL);
    };
    img.onerror = (error) => {
      reject(error);
    };
  });
};

export const generatePDF = async (data: AppData, type: 'weekly' | 'donor' | 'expense' | 'all_income' | 'all_financial') => {
  // SETTING UKURAN KERTAS F4 (210mm x 330mm)
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: [210, 330] 
  });

  // --- 1. RENDER KOP LAPORAN (KONSISTEN UNTUK SEMUA TIPE) ---

  // A. Render Logo (Try-Catch agar text tetap muncul meski logo gagal)
  try {
    const logoBase64 = await getBase64ImageFromURL(LOGO_URL);
    // Posisi Logo: x=15, y=10, (Lebar Besar Logo w=25, h=25
    doc.addImage(logoBase64, 'PNG', 15, 8, 26, 26); 
  } catch (error) {
    console.error("Gagal memuat Logo", error);
    // Jika logo gagal, biarkan kosong, teks tetap dirender di bawah
  }

  // B. Render Teks Kop (Selalu Tampil Sama)
  const centerX = 112; // Titik tengah horizontal (sedikit offset karena ada logo di kiri)

  doc.setTextColor(0, 0, 0); // Hitam

  // Baris 1: PANITIA HARI BESAR ISLAM
  doc.setFont("times", "bold");
  doc.setFontSize(14); 
  doc.text("PANITIA HARI BESAR ISLAM", centerX, 15, { align: 'center' });

  // Baris 2: MAULID NABI MUHAMMAD SAW
  doc.setFontSize(14); 
  doc.text("MAULID NABI MUHAMMAD SAW", centerX, 21, { align: 'center' });

  // Baris 3: DEWAN KEMAKMURAN MASJID...
  doc.setFontSize(14);
  doc.text("DEWAN KEMAKMURAN MASJID (DKM) JAMI' AL-ISHLAH", centerX, 27, { align: 'center' });

  // Baris 4: Alamat
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text("Jl. H.A Djuminta Kp. Teriti Rw. 04 Desa Karet Kec. Sepatan Kab. Tangerang", centerX, 33, { align: 'center' });

  // C. Garis Pembatas (Double Line)
  doc.setLineWidth(0.7);
  doc.line(10, 37, 200, 37); // Garis Tebal

  doc.setLineWidth(0.3); 
  doc.line(10, 38, 200, 38); // Garis Tipis

  doc.setLineWidth(0.1); // Reset default width untuk tabel

  // --- END KOP LAPORAN ---


  // 2. Tentukan Posisi Awal Tabel
  let startY = 46; 

  // --- CONFIG GAYA TABEL SUPER COMPACT (HEMAT KERTAS) ---
  const compactStyles: any = {
      fontSize: 8,
      textColor: [0, 0, 0],       
      cellPadding: 1.5,  
      valign: 'middle',
      overflow: 'linebreak'
  };

  const compactHeadStyles: any = {
      fontSize: 8,
      textColor: [255, 255, 255],       
      valign: 'middle',
      halign: 'center'
  };

  // Helper untuk menambah judul section dan cek halaman baru
  const addTitle = (title: string, isFirstSection = false, color: [number, number, number] = [0, 0, 0]) => {
    // Jika bukan section pertama, kita cek apakah perlu halaman baru atau space tambahan
    if (!isFirstSection) {
        const lastTableY = (doc as any).lastAutoTable?.finalY || startY;
        startY = lastTableY + 8; // Jarak antar SECTION tabel diperkecil

        // REVISI: Batas bawah diperketat (280mm) agar tabel tidak terpotong di kaki halaman
        // Kertas F4 tinggi 330mm. 280mm menyisakan 50mm untuk footer & margin.
        if (startY > 280) {
            doc.addPage();
            startY = 20; // Margin atas halaman baru
        }
    }

    doc.setFontSize(9); // Font judul section diperkecil
    doc.setFont("helvetica", "bold");
    doc.setTextColor(color[0], color[1], color[2]); 
    doc.text(title, 105, startY, { align: 'center' });
    doc.setTextColor(0, 0, 0); 
    startY += 5; // Jarak judul ke tabel di bawahnya (Default)
  };

  // --- 1. PREVIOUS FUNDS (Hanya jika All Financial) ---
  if (type === 'all_financial') {
     addTitle('LAPORAN DANA AWAL (PANITIA SEBELUMNYA)', true);

     if (data.previousFunds.length > 0) {
        const rows = data.previousFunds.map((item, idx) => [
            idx + 1,
            formatDate(item.date),
            formatCurrency(item.nominal)
        ]);

        autoTable(doc, {
            startY: startY,
            head: [['No', 'TANGGAL', 'NOMINAL']],
            body: rows,
            theme: 'grid',
            styles: compactStyles,
            headStyles: { ...compactHeadStyles, fillColor: [88, 28, 135] }, 
            footStyles: { ...compactStyles, fillColor: [233, 213, 255], textColor: [0, 0, 0], fontStyle: 'bold' },
            columnStyles: { 0: { halign: 'center', textColor: [0, 0, 0], cellWidth: 15 }, 2: { halign: 'right', textColor: [0, 0, 0]} },
            margin: { top: 20, bottom: 20 }, // Margin halaman untuk auto page break
            foot: [[
                { content: '', colSpan: 1, styles: { textColor: [0, 0, 0] }},
                { content: 'TOTAL', styles: { halign: 'right'} },
                { content: formatCurrency(data.previousFunds.reduce((a,b)=>a+b.nominal,0)), styles: { halign: 'right', textColor: [0, 0, 0] } }
            ]]
        });
     } else {
         doc.setFontSize(8);
         doc.setFont("helvetica", "italic");
         doc.text("(Tidak ada data dana awal)", 105, startY + 4, { align: 'center' });
         (doc as any).lastAutoTable = { finalY: startY + 8 }; 
     }
  }

  // --- 2. WEEKLY DATA (UPDATE: MATRIX LAYOUT / PIVOT TABLE) ---
  if (type === 'weekly' || type === 'all_income' || type === 'all_financial') {
    addTitle('LAPORAN PEMASUKAN MINGGUAN (PER RT)', type !== 'all_financial');

    // Grouping Data by Week
    const groupedByWeek: Record<string, { date: string, items: any[] }> = {};

    data.weeklyData.forEach(item => {
        if (!groupedByWeek[item.week]) {
            groupedByWeek[item.week] = { date: item.date, items: [] };
        }
        groupedByWeek[item.week].items.push(item);
    });

    // Sort Weeks (Minggu 1, Minggu 2, ...)
    const sortedWeeks = Object.keys(groupedByWeek).sort((a, b) => {
        const numA = parseInt(a.match(/\d+/)?.[0] || '0');
        const numB = parseInt(b.match(/\d+/)?.[0] || '0');
        return numA - numB;
    });

    // Definisi Kolom RT Tetap (01 s/d 06) sesuai format Masjid
    const rtColumns = ['RT 01', 'RT 02', 'RT 03', 'RT 04', 'RT 05', 'RT 06'];

    // Loop setiap minggu dan buat tabel terpisah
    sortedWeeks.forEach((weekKey, index) => {
        const weekData = groupedByWeek[weekKey];
        const items = weekData.items;

        const lastAutoTableY = (doc as any).lastAutoTable?.finalY;

        // --- PENGATURAN SPASI & POSISI Y ---
        if (index === 0) {
            startY = startY + 1; 
        } else {
            if (lastAutoTableY > 280) {
                doc.addPage();
                startY = 20;
            } else {
                // REVISI: Jarak tabel rincian mingguan 5mm
                startY = lastAutoTableY + 5; 
            }
        }

        // Tampilkan Judul Minggu & Tanggal
        doc.setFontSize(8);
        doc.setFont("helvetica", "bold");
        doc.text(weekKey.toUpperCase(), 14, startY);

        doc.setFont("helvetica", "normal");
        const dateText = `Tanggal : ${formatDate(weekData.date)}`;
        const dateWidth = doc.getTextWidth(dateText);
        doc.text(dateText, 196 - dateWidth, startY);

        startY += 2; 

        // --- KONSTRUKSI DATA MATRIKS PER MINGGU ---
        let totalGross = 0;
        let totalCons = 0;
        let totalComm = 0;
        let totalNet = 0;

        const rowGross: any[] = ['1', 'PEMASUKAN'];
        const rowCons: any[] = ['2', 'PERSENTASI 5%'];
        const rowComm: any[] = ['3', 'PERSENTASI 10%'];
        const rowNet: any[] = ['4', 'PENDAPATAN BERSIH'];

        rtColumns.forEach(rtLabel => {
            const dataItem = items.find(i => i.rt === rtLabel);
            if (dataItem) {
                rowGross.push(formatCurrency(dataItem.grossAmount));
                rowCons.push(formatCurrency(dataItem.consumptionCut));
                rowComm.push(formatCurrency(dataItem.commissionCut));
                rowNet.push(formatCurrency(dataItem.netAmount));

                totalGross += dataItem.grossAmount;
                totalCons += dataItem.consumptionCut;
                totalComm += dataItem.commissionCut;
                totalNet += dataItem.netAmount;
            } else {
                const zero = formatCurrency(0);
                rowGross.push(zero);
                rowCons.push(zero);
                rowComm.push(zero);
                rowNet.push(zero);
            }
        });

        rowGross.push(formatCurrency(totalGross));
        rowCons.push(formatCurrency(totalCons));
        rowComm.push(formatCurrency(totalComm));
        rowNet.push(formatCurrency(totalNet));

        autoTable(doc, {
            startY: startY,
            head: [
                ['NO', 'PEMASUKAN', 'RT 01', 'RT 02', 'RT 03', 'RT 04', 'RT 05', 'RT 06', 'TOTAL']
            ],
            body: [rowGross, rowCons, rowComm, rowNet],
            theme: 'grid',
            styles: { ...compactStyles, cellPadding: 1.5, fontSize: 7 },
            headStyles: {
                ...compactHeadStyles,
                // REVISI: Warna Header Rincian Mingguan Jadi TOSCA
                fillColor: [13, 148, 136], // Hijau Tosca (Teal 600)
                fontSize: 7,
                lineWidth: 0.1,
                lineColor: [200, 200, 200]
            },
            columnStyles: {
                0: { halign: 'center', cellWidth: 8 },
                1: { cellWidth: 36 },
                2: { halign: 'right', cellWidth: 18 },
                3: { halign: 'right', cellWidth: 18 },
                4: { halign: 'right', cellWidth: 18 },
                5: { halign: 'right', cellWidth: 18 },
                6: { halign: 'right', cellWidth: 18 },
                7: { halign: 'right', cellWidth: 18 },
                8: { halign: 'right', fontStyle: 'bold', cellWidth: 30 }
            },
            didParseCell: (data) => {
                if (data.section === 'body') {
                    const rowIndex = data.row.index;
                    if (rowIndex === 1 || rowIndex === 2) {
                        if (data.column.index > 1) { 
                            data.cell.styles.textColor = [220, 38, 38];
                        }
                    }
                    if (rowIndex === 3) {
                        data.cell.styles.fontStyle = 'bold';
                        // REVISI: Baris Pendapatan Bersih Mingguan Jadi Background Tosca Muda
                        data.cell.styles.fillColor = [204, 251, 241]; // Teal 50
                        if (data.column.index > 1) {
                            data.cell.styles.textColor = [15, 118, 110]; // Teal 800
                        }
                    }
                }
            }
        });
    });

    // --- REKAPITULASI DANA MINGGUAN (MATRIX TOTAL) ---
    // Dipasang SETELAH looping semua minggu selesai

    // 1. Hitung Total Akumulasi per RT
    const rtTotalSummary: Record<string, { gross: number, cons: number, comm: number, net: number }> = {};
    const rtKeys = ['RT 01', 'RT 02', 'RT 03', 'RT 04', 'RT 05', 'RT 06'];

    // Inisialisasi 0
    rtKeys.forEach(key => {
        rtTotalSummary[key] = { gross: 0, cons: 0, comm: 0, net: 0 };
    });

    // Jumlahkan semua data mingguan ke dalam bucket RT masing-masing
    data.weeklyData.forEach(item => {
        if(rtTotalSummary[item.rt]) {
            rtTotalSummary[item.rt].gross += item.grossAmount;
            rtTotalSummary[item.rt].cons += item.consumptionCut;
            rtTotalSummary[item.rt].comm += item.commissionCut;
            rtTotalSummary[item.rt].net += item.netAmount;
        }
    });

    // 2. Tentukan Posisi Y
    // REVISI: Jarak tabel REKAP DANA MINGGUAN dengan tabel atasnya 5mm
    let rekapWeeklyY = (doc as any).lastAutoTable?.finalY + 5; 

    // Cek Page Break sebelum judul Rekap Mingguan
    if (rekapWeeklyY > 250) {
        doc.addPage();
        rekapWeeklyY = 20;
    }

    // 3. Render Judul
    doc.setFontSize(8);
    doc.setFont("helvetica", "bold");
    doc.text("REKAP DANA MINGGUAN", 14, rekapWeeklyY); // Rata Kiri sesuai tabel

    // 4. Siapkan Data Row Matrix
    // Baris 1: Pemasukan
    const recRowGross: any[] = ['1', 'PEMASUKAN'];
    // Baris 2: Potongan 5%
    const recRowCons: any[] = ['2', 'PERSENTASI 5%'];
    // Baris 3: Potongan 10%
    const recRowComm: any[] = ['3', 'PERSENTASI 10%'];
    // Baris 4: Pendapatan Bersih
    const recRowNet: any[] = ['4', 'PENDAPATAN BERSIH'];

    let grandTotalGross = 0;
    let grandTotalCons = 0;
    let grandTotalComm = 0;
    let grandTotalNet = 0;

    rtKeys.forEach(rt => {
        const val = rtTotalSummary[rt];
        recRowGross.push(formatCurrency(val.gross));
        recRowCons.push(formatCurrency(val.cons));
        recRowComm.push(formatCurrency(val.comm));
        recRowNet.push(formatCurrency(val.net));

        grandTotalGross += val.gross;
        grandTotalCons += val.cons;
        grandTotalComm += val.comm;
        grandTotalNet += val.net;
    });

    // Tambah Kolom TOTAL (Paling Kanan)
    recRowGross.push(formatCurrency(grandTotalGross));
    recRowCons.push(formatCurrency(grandTotalCons));
    recRowComm.push(formatCurrency(grandTotalComm));
    recRowNet.push(formatCurrency(grandTotalNet));

    // 5. Render Tabel Rekap Matrix
    autoTable(doc, {
        startY: rekapWeeklyY + 2,
        // Header Custom: 1 Baris Saja
        head: [
            ['NO', 'PEMASUKAN', 'RT 01', 'RT 02', 'RT 03', 'RT 04', 'RT 05', 'RT 06', 'TOTAL']
        ],
        body: [recRowGross, recRowCons, recRowComm, recRowNet],
        theme: 'grid',
        styles: { ...compactStyles, cellPadding: 1.5, fontSize: 7 },
        headStyles: {
            ...compactHeadStyles,
            // REVISI: Warna Header Rekap Mingguan Jadi HIJAU TUA (Primary)
            fillColor: [6, 78, 59], // Hijau Tua
            fontSize: 7,
            lineWidth: 0.1,
            lineColor: [200, 200, 200]
        },
        columnStyles: {
            0: { halign: 'center', cellWidth: 8 },
            1: { cellWidth: 36 },
            2: { halign: 'right', cellWidth: 18 },
            3: { halign: 'right', cellWidth: 18 },
            4: { halign: 'right', cellWidth: 18 },
            5: { halign: 'right', cellWidth: 18 },
            6: { halign: 'right', cellWidth: 18 },
            7: { halign: 'right', cellWidth: 18 },
            8: { halign: 'right', fontStyle: 'bold', cellWidth: 30 }
        },
        // Styling Baris (Merah untuk potongan, Hijau Mint untuk Bersih)
        didParseCell: (data) => {
            if (data.section === 'body') {
                const rowIndex = data.row.index;
                // Baris 1 (Index 1) & 2 (Index 2) adalah Potongan -> Merah
                if (rowIndex === 1 || rowIndex === 2) {
                    if (data.column.index > 1) { 
                        data.cell.styles.textColor = [220, 38, 38];
                    }
                }
                // Baris 3 (Index 3) adalah PENDAPATAN BERSIH
                // REVISI: Baris Pendapatan Bersih Rekap Jadi Background Mint (Hijau Muda)
                if (rowIndex === 3) {
                    data.cell.styles.fontStyle = 'bold';
                    data.cell.styles.fillColor = [236, 253, 245]; // Mint 50
                    if (data.column.index > 1) {
                        data.cell.styles.textColor = [6, 78, 59]; // Hijau Tua
                    }
                }
            }
        }
    });

  }

  // --- 3. EXPENSE DATA (Judul Disesuaikan) - PINDAH KE URUTAN 3 ---
  if (type === 'expense' || type === 'all_financial') {
    addTitle('LAPORAN DANA PENGELUARAN', type === 'expense');

    const rows = data.expenses.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.purpose,
      formatCurrency(item.nominal)
    ]);

    autoTable(doc, {
      startY: startY,
      head: [['NO', 'TANGGAL', 'KEPERLUAN', 'NOMINAL']],
      body: rows,
      theme: 'grid',
      styles: compactStyles,
      margin: { top: 20, bottom: 20 },
      headStyles: { ...compactHeadStyles, fillColor: [185, 28, 28] }, 
      footStyles: { ...compactStyles, fillColor: [254, 226, 226], textColor: [0, 0, 0], fontStyle: 'bold' },
      // REVISI KOLOM: Tanggal fixed, Keperluan auto
      columnStyles: { 
          0: { halign: 'center', cellWidth: 12 }, 
          1: { cellWidth: 28, halign: 'center' }, // Tanggal fixed
          2: { cellWidth: 'auto' }, // Keperluan auto
          3: { halign: 'right', cellWidth: 35 } 
      },
      foot: [[
          { content: '', colSpan: 2 },
          { content: 'TOTAL', styles: { halign: 'right' } },
          { content: formatCurrency(data.expenses.reduce((a,b)=>a+b.nominal,0)), styles: { halign: 'right' } }
      ]]
    });
  }

  // --- 4. DONOR DATA (Judul Disesuaikan) - PINDAH KE URUTAN 4 ---
  if (type === 'donor' || type === 'all_income' || type === 'all_financial') {
    addTitle('LAPORAN PEMASUKAN PROPOSAL / AMPLOP', type === 'donor');

    const rows = data.donors.map((item, idx) => [
      idx + 1,
      formatDate(item.date),
      item.name,
      formatCurrency(item.nominal)
    ]);

    autoTable(doc, {
      startY: startY,
      head: [['NO', 'TANGGAL', 'SUMBER DANA', 'NOMINAL']],
      body: rows,
      theme: 'grid',
      styles: compactStyles,
      margin: { top: 20, bottom: 20 },
      headStyles: { ...compactHeadStyles, fillColor: [30, 64, 175] }, 
      footStyles: { ...compactStyles, fillColor: [219, 234, 254], textColor: [0, 0, 0], fontStyle: 'bold' },
      // REVISI KOLOM: Tanggal fixed, Sumber Dana auto
      columnStyles: { 
          0: { halign: 'center', cellWidth: 12 }, 
          1: { cellWidth: 28, halign: 'center' }, // Tanggal fixed
          2: { cellWidth: 'auto' }, // Sumber Dana auto
          3: { halign: 'right', cellWidth: 35 } 
      },
      foot: [[
          { content: '', colSpan: 2 },
          { content: 'TOTAL', styles: { halign: 'right' } }, 
          { content: formatCurrency(data.donors.reduce((a,b)=>a+b.nominal,0)), styles: { halign: 'right' } }
      ]]
    });
  }

  // --- 5. REKAPITULASI (Only for All Financial) ---
  if (type === 'all_financial') {
      const totalPrev = data.previousFunds.reduce((a,b)=>a+b.nominal,0);
      const totalWeekly = data.weeklyData.reduce((a,b)=>a+b.netAmount,0);
      const totalDonor = data.donors.reduce((a,b)=>a+b.nominal,0);
      const totalIncome = totalPrev + totalWeekly + totalDonor;
      const totalExpense = data.expenses.reduce((a,b)=>a+b.nominal,0);
      const balance = totalIncome - totalExpense;

      // Cek halaman baru untuk rekap
      const lastTableY = (doc as any).lastAutoTable?.finalY || startY;
      let rekapY = lastTableY + 10; // Beri jarak sedikit dari tabel sebelumnya

      // REVISI PENTING: Ambang batas (Threshold) Page Break Diperketat
      // Jika posisi Y > 250mm, kemungkinan besar tabel tidak muat di sisa kertas.
      // Kita paksa pindah halaman agar Judul dan Tabel selalu bersama.
      if (rekapY > 250) {
          doc.addPage();
          rekapY = 20; // Margin atas halaman baru
      }

      doc.setFontSize(10);
      doc.setFont("helvetica", "bold");
      doc.setTextColor(0, 0, 0);
      doc.text("LAPORAN REKAPITULASI DANA PHBI", 105, rekapY, { align: 'center' });

      autoTable(doc, {
          startY: rekapY + 4, // REVISI: Jarak +4 (Standar) agar konsisten dengan tabel lainnya (mirip addTitle +5)
          head: [['KETERANGAN', 'NOMINAL']],
          body: [
              [{ content: 'Total Dana Panitia Sebelumnya', styles: { textColor: [0, 0, 0], fontSize: 9 } }, { content: formatCurrency(totalPrev), styles: { fontStyle: 'bold', fontSize: 9, textColor: [0, 0, 0], halign: 'right' } }],
              [{ content: 'Total Pemasukan Mingguan (Bersih)', styles: { textColor: [0, 0, 0], fontSize: 9 } }, { content: formatCurrency(totalWeekly), styles: { fontStyle: 'bold', fontSize: 9, textColor: [0, 0, 0], halign: 'right' } }],
              [{ content: 'Total Pemasukan Proposal / Amplop', styles: { textColor: [0, 0, 0], fontSize: 9 } }, { content: formatCurrency(totalDonor), styles: { fontStyle: 'bold', fontSize: 9, textColor: [0, 0, 0], halign: 'right' } }],
              [{ content: 'TOTAL SEMUA PEMASUKAN', styles: { fontStyle: 'bold', textColor: [6, 78, 59], fontSize: 10 } }, { content: formatCurrency(totalIncome), styles: { fontStyle: 'bold', fontSize: 10, textColor: [6, 78, 59], halign: 'right' } }],
              [{ content: 'TOTAL PENGELUARAN', styles: { fontStyle: 'bold', textColor: [185, 28, 28], fontSize: 10 } }, { content: formatCurrency(totalExpense), styles: { fontStyle: 'bold', fontSize: 10, textColor: [185, 28, 28], halign: 'right' } }],
              // UPDATE: Kolom Teks Bersih (Tanggal akan di-draw manual agar italic)
              [{ content: `SISA SALDO SAAT INI `, styles: { fontStyle: 'bold', textColor: [30, 64, 175], fontSize: 10 } }, { content: formatCurrency(balance), styles: { fontStyle: 'bold', fontSize: 10, textColor: [30, 64, 175], halign: 'right' } }]
          ],
          theme: 'grid',
          styles: compactStyles,
          margin: { top: 20, bottom: 20 },
          pageBreak: 'avoid', // REVISI: Tabel Rekapitulasi dilarang terpotong halaman
          headStyles: { ...compactHeadStyles, fillColor: [2, 201, 39] }, // REVISI: Warna Header Hijau Terang (#02c927)
          columnStyles: {
            0: { halign: 'left', cellWidth: 'auto' }, 
            1: { halign: 'right', cellWidth: 'auto' } 
          },
          // REVISI: Hook untuk menggambar tanggal dengan style italic (miring) di sebelah teks Bold
          didDrawCell: (hookData) => {
               if (hookData.section === 'body' && hookData.row.index === 5 && hookData.column.index === 0) {
                   const doc = hookData.doc;

                   // 1. Hitung lebar teks "SISA SALDO SAAT INI" (Bold)
                   doc.setFont("helvetica", "bold");
                   doc.setFontSize(10);
                   const baseTextWidth = doc.getTextWidth("SISA SALDO SAAT INI ");

                   // 2. Siapkan teks Tanggal
                   const dateText = ` (Update: ${formatDate(data.lastUpdated)})`;

                   // 3. Set Font Italic untuk Tanggal
                   doc.setFont("helvetica", "italic");
                   doc.setFontSize(8);
                   doc.setTextColor(100);

                   // 4. Hitung Posisi X dan Y
                   const cellX = hookData.cell.x;
                   const paddingLeft = hookData.cell.padding('left');
                   const finalX = cellX + paddingLeft + baseTextWidth;

                   // Gunakan textPos.y jika ada (baseline), jika tidak estimasi tengah
                   // @ts-ignore
                   const finalY = hookData.cell.textPos ? hookData.cell.textPos.y : (hookData.cell.y + hookData.cell.height / 2 + 1);

                   // 5. Gambar Teks
                   doc.text(dateText, finalX, finalY);
               }
          }
      });

      // --- TERBILANG SECTION (BARU) ---
      // Ambil posisi Y terakhir setelah tabel selesai
      const finalY = (doc as any).lastAutoTable?.finalY;
      if (finalY) {
          const textTerbilang = terbilang(balance);
          doc.setFontSize(8);
          doc.setFont("helvetica", "italic"); // Font Miring
          doc.setTextColor(0, 0, 0); // Warna Hitam
          // REVISI: Geser ke Kanan (align: right, x: 196)
          doc.text(`Terbilang : ${textTerbilang} Rupiah`, 196, finalY + 6, { align: 'right' }); 
      }
  }

  // Footer for all
  const pageCount = doc.getNumberOfPages();
  for(let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(7);
    doc.setFont("helvetica", "italic");
    doc.setTextColor(100);

    // REVISI FOOTER: Menambahkan teks "Pukul :" antara tanggal dan jam
    const now = new Date();
    const dateStr = now.toLocaleDateString('id-ID');
    const timeStr = now.toLocaleTimeString('id-ID');

    doc.text(`Diunduh pada: ${dateStr}, Pukul : ${timeStr}`, 15, doc.internal.pageSize.height - 10);
    doc.text(`Hal ${i} dari ${pageCount}`, 195, doc.internal.pageSize.height - 10, { align: 'right' });
  }

  // Logika Penamaan File
  const getFileName = (reportType: string) => {
      switch (reportType) {
          case 'all_financial': return 'Laporan_PHBI_Rekapitulasi';
          case 'weekly': return 'Laporan_PHBI_Mingguan_Per_RT';
          case 'donor': return 'Laporan_PHBI_Proposal_Amplop';
          case 'expense': return 'Laporan_PHBI_Pengeluaran';
          case 'all_income': return 'Laporan_PHBI_Gabungan_Pemasukan';
          default: return `Laporan_PHBI_${reportType}`;
      }
  };

  const fileName = `${getFileName(type)}_${new Date().toISOString().slice(0,10)}.pdf`;
  doc.save(fileName);
};

