            await supabase.from('Pengeluaran_data').delete().neq('id', '00000000-0000-0000-0000-000000000000');
        } else {
            const tableMap: Record<string, string> = {
                'previous': 'DanaSebelumnya_data',
                'weekly': 'Mingguan_data',
                'donor': 'Donatur_data',
                'expense': 'Pengeluaran_data'
            };
            const tableName = tableMap[type];
            if (tableName) {
                const { error } = await supabase.from(tableName).delete().neq('id', '00000000-0000-0000-0000-000000000000');
                if (error) throw error;
            }
        }

        await fetchSupabaseData(true); 
        Swal.fire('Berhasil', 'Database telah direset/dihapus.', 'success');
    } catch (error: any) {
        console.error(error);
        Swal.fire('Error', 'Gagal mereset database: ' + error.message, 'error');
    }
  };

  return (
    <DataContext.Provider value={{
      publishedData,
      stagedData,
      isLoggedIn,
      currentUser,
      login,
      logout,
      verifyUser,
      addAdminUser,
      getAdminUsers,
      deleteAdminUser,
      addPreviousFund,
      updatePreviousFund,
      deletePreviousFund,
      addWeeklyData,
      updateWeeklyData,
      deleteWeeklyData,
      addDonor,
      updateDonor,
      deleteDonor,
      addExpense,
      updateExpense,
      deleteExpense,
      updatePublishedItem,
      deletePublishedItem,
      publishData,
      resetData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

