      login,
      logout,
      verifyUser,
      addAdminUser,
      getAdminUsers,
      deleteAdminUser,
      addPreviousFund,
      updatePreviousFund,
      deletePreviousFund,
      addWeeklyData,
      updateWeeklyData,
      deleteWeeklyData,
      addDonor,
      updateDonor,
      deleteDonor,
      addExpense,
      updateExpense,
      deleteExpense,
      updatePublishedItem,
      deletePublishedItem,
      publishData,
      resetData
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};

