            columnStyles: {
                0: { cellWidth: 20, halign: 'center' }, 
                1: { cellWidth: 25, halign: 'center' }, 
                2: { cellWidth: 12, halign: 'center' }, 
                3: { halign: 'right' },
                4: { halign: 'right' },
                5: { halign: 'right' },
                6: { halign: 'right' },
