                netTotal: 0,
                name: item.week
            };
        }
        groupedWeeks[item.week].netTotal += item.netAmount;
     });

     const summaryWeeks = Object.values(groupedWeeks).sort((a, b) => {
        const numA = parseInt(a.name.match(/\d+/)?.[0] || '0');
