      fontSize: 8,
      textColor: [0, 0, 0],       
      cellPadding: 1.5,  
      valign: 'middle',
      overflow: 'linebreak'
  };

  const compactHeadStyles: any = {
      fontSize: 8,
      textColor: [255, 255, 255],       
      valign: 'middle',
      halign: 'center'
  };

  // --- CONFIG GAYA KHUSUS LPJ (Revisi: Padding Kecil agar height tabel kecil) ---
