        // Kunci Lebar Kolom
        columnStyles: { 
            0: { halign: 'center', cellWidth: colWidthNo }, // NO 10mm
            1: { halign: 'center', cellWidth: colWidthDate }, // TANGGAL 30mm
            2: { halign: 'left', cellWidth: 'auto' }, // KEPERLUAN (Auto)
