      // Tambahkan Jarak setelah Judul Utama sebelum masuk ke Tabel I
      // Jarak dikurangi agar tidak memakan tempat (25mm space)
      startY += 25;

      // 1. SALDO AWAL (PREVIOUS FUNDS)
