            formatDate(item.date),
            formatCurrency(item.nominal)
        ]);

        autoTable(doc, {
            startY: startY,
            head: [['NO', 'TANGGAL', 'NOMINAL']],
            body: rows,
            theme: 'grid',
            styles: lpjStyles, 
            showHead: 'firstPage', // REVISI: Only show header on first page of table
            showFoot: 'lastPage',
