            footStyles: { ...lpjStyles, fillColor: [233, 213, 255], textColor: [0, 0, 0], fontStyle: 'bold' },
            // REVISI: Lebar kolom NO, TANGGAL, NOMINAL disamakan agar LURUS
            columnStyles: { 
                0: { halign: 'center', cellWidth: colWidthNo }, 
