            },
            margin: tableMargin,
            foot: [[
                { content: '', colSpan: 1 },
                { content: 'TOTAL', styles: { halign: 'right'} },
                { content: formatCurrency(data.previousFunds.reduce((a,b)=>a+b.nominal,0)), styles: { halign: 'right' } }
            ]]
        });
     } else {
