      }
      const { error } = await supabase.from('admin_users').delete().eq('id', id);
      if (error) {
          Swal.fire('Error', error.message, 'error');
          return false;
      }
      return true;
  };

  // --- CRUD Operations (Operate on Staged Data - Client Side Only) ---

  const addPreviousFund = (item: Omit<PreviousFund, 'id'>) => {
