                                <td className="py-2 px-2 text-right text-emerald-800 border-r border-gray-100">
                                    {formatCurrency(allPreviousFunds.reduce((a,b) => a + b.nominal, 0))}
                                </td>
                                <td></td>
                            </tr>
                        </tfoot>
                   </table>
               </div>
            </div>
          </div>
        )}

        {/* === 2. WEEKLY FORM === */}
        {activeTab === 'weekly' && (
          <div className="space-y-2 md:space-y-6">
             {/* ... Form Inputs with Readonly Fields ... */}
