  const handleSaveDonor = () => {
    if(!donorForm.date || !donorForm.name || !donorForm.nominal) { Swal.fire({ icon: 'warning', title: 'Opss...', text: 'Mohon lengkapi kolom yang kosong', confirmButtonColor: '#d4af37' }); return; }
