    doc.setTextColor(0, 0, 0); 
    startY += 5; 
  };

  // Helper KHUSUS LPJ: Judul Rata Kiri + Penomoran + Jarak Rapat
  const addLeftTitle = (numberStr: string, title: string, isFirstSection = false) => {
