          input: 'password',
          inputPlaceholder: 'Kode ID Server...',
          showCancelButton: true,
          confirmButtonColor: '#047857',
          cancelButtonColor: '#d33',
          confirmButtonText: 'Ya, Update Data',
          cancelButtonText: 'Batal'
      }).then((result) => {
          if (result.isConfirmed) {
              if (result.value === AUTH_CODE) {
