        <p className="text-xs md:text-xl text-secondary font-medium tracking-wide">Maulid Nabi Muhammad SAW 1448 H | 2026 M</p>
      </div>

      <div className="container mx-auto px-4 mt-4 md:mt-8 space-y-4 md:space-y-12">

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3 md:gap-6 animate-fade-in-up">
          <SummaryCard title="Total Pemasukan" amount={totalIncome} type="income" onDetailClick={() => setActiveDetail('income')} />
          <SummaryCard title="Total Pengeluaran" amount={totalExpense} type="expense" onDetailClick={() => { const el = document.getElementById('expense-section'); el?.scrollIntoView({ behavior: 'smooth' }); }} />
          <SummaryCard title="Saldo Saat Ini" amount={balance} type="balance" subtitle={`Update: ${formatDateTime(publishedData.lastUpdated)}`} />
        </div>

        {/* Section: Mingguan (Per RT) */}
        <section className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden">
          <div className="p-3 md:p-6 bg-emerald-50 border-b border-emerald-100 flex flex-col md:flex-row justify-between items-start md:items-center gap-2 md:gap-3">
            <div className="flex items-center gap-2">
                <div className="bg-emerald-600 p-1 md:p-1.5 rounded-lg text-white"><TrendingUp size={16} className="md:w-5 md:h-5" /></div>
                <h3 className="text-sm md:text-xl font-serif font-bold text-primary">Pemasukan Mingguan (Per RT)</h3>
            </div>
            <div className="flex flex-col-reverse md:flex-row items-end md:items-center gap-2 w-full md:w-auto">
               <div className="hidden md:flex items-center gap-1.5 px-2">
                  <Calendar size={10} className="text-gray-600" />
                  <span className="text-[9px] font-bold text-gray-700 italic">{currentWeekDate}</span>
               </div>
               <div className="relative w-full md:w-auto">
                <select value={selectedWeek} onChange={(e) => setSelectedWeek(e.target.value)} className="w-full md:w-56 appearance-none bg-white border border-emerald-300 text-gray-700 text-[10px] md:text-sm rounded-full pl-3 pr-8 py-1.5 md:py-2 focus:ring-1 focus:ring-primary shadow-sm font-medium">
                  <option value="all">Tampilkan Semua Minggu</option>
                  {weeks.map(w => <option key={w} value={w}>{w}</option>)}
                </select>
                <div className="absolute right-3 top-1/2 transform -translate-y-1/2 pointer-events-none text-emerald-600"><ChevronDown size={14} /></div>
              </div>
            </div>
          </div>

          {/* Desktop Detail View */}
          <div className="hidden md:block">
            <table className="w-full text-[10px] table-fixed border-collapse">
              <thead className="bg-gray-100 text-gray-600 font-bold uppercase sticky top-0 z-20 shadow-sm">
                <tr><th className="w-12 py-2">No</th><th className="w-20">RT</th><th className="w-40">Kotor</th><th className="w-32 text-red-500">5%</th><th className="w-32 text-red-500">10%</th><th className="w-48 text-emerald-700 bg-emerald-50">Bersih</th></tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {processedWeeklyData.map((item, idx) => (
                  <tr key={idx} className="hover:bg-emerald-50/30 transition text-center">
                    <td className="py-2 text-gray-500">{idx + 1}</td><td className="font-bold text-gray-700">{item.rt}</td><td className="text-right px-4">{formatCurrency(item.grossAmount)}</td>
                    <td className="text-right px-4 text-red-400">-{formatCurrency(item.consumptionCut)}</td><td className="text-right px-4 text-red-400">-{formatCurrency(item.commissionCut)}</td>
                    <td className="text-right px-4 font-bold text-emerald-700 bg-emerald-50/20">{formatCurrency(item.netAmount)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Mobile Detailed Card View */}
          <div className="md:hidden bg-gray-50 p-2 space-y-2">
            {processedWeeklyData.map((item) => (
                (item.grossAmount > 0 || selectedWeek === 'all') && (
                <div key={item.id} className="bg-white p-3 rounded-md shadow-sm border border-gray-200 relative">
                    <div className="absolute top-0 left-0 w-1 h-full bg-emerald-500"></div>
