import * as XLSX from 'xlsx';
import { AppData } from '../types';
import { formatDate, formatDateTime } from './format';
import Swal from 'sweetalert2';

export const generateExcel = (data: AppData, type: 'weekly' | 'donor' | 'expense' | 'all_income' | 'all_financial' | 'accountability') => {
  try {
      const wb = XLSX.utils.book_new();

      // --- SORTING HELPER (Tanggal Kecil di Atas / Ascending) ---
      const sortByDateAsc = (a: any, b: any) => new Date(a.date).getTime() - new Date(b.date).getTime();

      // Helper untuk menambahkan Sheet dengan Style
      const addToSheet = (sheetName: string, headers: string[], rowData: any[]) => {
        const wsData = [headers, ...rowData];
        const ws = XLSX.utils.aoa_to_sheet(wsData);

        // --- AUTO FIT COLUMN WIDTH CALCULATION ---
        const wscols = headers.map((header, colIndex) => {
            let maxLength = header.toString().length;
            rowData.forEach(row => {
                const cellValue = row[colIndex];
                if (cellValue) {
                    let cellLength = cellValue.toString().length;
                    if (typeof cellValue === 'number') {
                         cellLength = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR' }).format(cellValue).length;
                    }
                    if (cellLength > maxLength) {
                        maxLength = cellLength;
                    }
                }
            });
            return { wch: maxLength + 5 }; 
        });

        ws['!cols'] = wscols;

        // --- BORDER STYLING & CURRENCY FORMATTING ---
        const borderStyle = {
            top: { style: "thin", color: { rgb: "000000" } },
            bottom: { style: "thin", color: { rgb: "000000" } },
            left: { style: "thin", color: { rgb: "000000" } },
            right: { style: "thin", color: { rgb: "000000" } }
        };

        const headerStyle = {
            font: { bold: true },
            alignment: { horizontal: "center", vertical: "center" },
            fill: { fgColor: { rgb: "E5E7EB" } }, // Light Gray
            border: borderStyle
        };

        const nonCurrencyHeaders = ['No', 'Minggu', 'RT', 'No.', 'Tanggal', 'Keterangan', 'Sumber Dana / Donatur', 'Keperluan'];

        const range = XLSX.utils.decode_range(ws['!ref'] || "A1");
        for (let R = range.s.r; R <= range.e.r; ++R) {
            for (let C = range.s.c; C <= range.e.c; ++C) {
                const cellRef = XLSX.utils.encode_cell({r: R, c: C});
                if (!ws[cellRef]) continue;

                if (!ws[cellRef].s) ws[cellRef].s = {};
                ws[cellRef].s.border = borderStyle;

                if (R === 0) {
                    ws[cellRef].s = { ...ws[cellRef].s, ...headerStyle };
                }

                if (R > 0 && ws[cellRef].t === 'n') {
                    const currentHeader = headers[C]; 
                    if (!nonCurrencyHeaders.includes(currentHeader)) {
                        ws[cellRef].z = '"Rp" #,##0';
                    } else {
                         ws[cellRef].s.alignment = { horizontal: "center", vertical: "center" };
                    }
                }
            }
        }

        XLSX.utils.book_append_sheet(wb, ws, sheetName);
      };

      // --- 1. SALDO AWAL ---
      if (type === 'all_financial' || type === 'all_income' || type === 'accountability') {
          const headers = ['No', 'Tanggal', 'Nominal'];
          // SORT
          const sortedPrev = [...data.previousFunds].sort(sortByDateAsc);
          const rows = sortedPrev.map((item, idx) => [
              idx + 1,
              formatDate(item.date),
              item.nominal
          ]);
          const totalPrev = data.previousFunds.reduce((a,b)=>a+b.nominal,0);
          rows.push(['', 'TOTAL SALDO AWAL', totalPrev]);
          addToSheet("Dana Awal", headers, rows);
      }

      // --- 2. MINGGUAN (Ada 2 Mode: Detail vs Summary) ---

      // MODE A: DETAIL (Untuk type weekly, all_income, all_financial)
      if (type === 'weekly' || type === 'all_income' || type === 'all_financial') {
        const headers = ['Minggu', 'Tanggal', 'RT', 'Pemasukan Kotor', 'Potongan Konsumsi (5%)', 'Potongan Komisi (10%)', 'Jumlah Bersih'];

        // SORT
        const sortedWeekly = [...data.weeklyData].sort(sortByDateAsc);

        const rows = sortedWeekly.map(item => [
          item.week,
          formatDate(item.date), 
          item.rt, 
          item.grossAmount,
          item.consumptionCut,
          item.commissionCut,
          item.netAmount
        ]);

        const totalRow = [
            'TOTAL PENDAPATAN BERSIH', '', '',
            data.weeklyData.reduce((a,b)=>a+b.grossAmount,0),
            data.weeklyData.reduce((a,b)=>a+b.consumptionCut,0),
            data.weeklyData.reduce((a,b)=>a+b.commissionCut,0),
            data.weeklyData.reduce((a,b)=>a+b.netAmount,0)
        ];
        rows.push(totalRow);

        addToSheet("Mingguan Detail", headers, rows);
      }

      // MODE B: SUMMARY / RINGKASAN (KHUSUS ACCOUNTABILITY)
      if (type === 'accountability') {
          const headers = ['No', 'Tanggal', 'Nominal Bersih', 'Keterangan'];

          const groupedWeeks: Record<string, { date: string, netTotal: number, name: string }> = {};

          // SORT RAW DATA FOR GROUPING
          const sortedWeeklyRaw = [...data.weeklyData].sort(sortByDateAsc);

          sortedWeeklyRaw.forEach(item => {
             if (!groupedWeeks[item.week]) {
                 groupedWeeks[item.week] = { date: item.date, netTotal: 0, name: item.week };
             }
             groupedWeeks[item.week].netTotal += item.netAmount;
          });

          const summaryWeeks = Object.values(groupedWeeks).sort((a, b) => {
             const numA = parseInt(a.name.match(/\d+/)?.[0] || '0');
             const numB = parseInt(b.name.match(/\d+/)?.[0] || '0');
             return numA - numB;
          });

          const rows = summaryWeeks.map((item, idx) => [
              idx + 1,
              formatDate(item.date),
              item.netTotal,
              item.name
          ]);

          const totalRow = ['', 'TOTAL', summaryWeeks.reduce((a,b)=>a+b.netTotal,0), ''];
          rows.push(totalRow);

          addToSheet("Mingguan Ringkasan", headers, rows);
      }

      // --- 3. DONATUR ---
      if (type === 'donor' || type === 'all_income' || type === 'all_financial' || type === 'accountability') {
        const headers = ['No', 'Tanggal', 'Sumber Dana / Donatur', 'Nominal'];
        // SORT
        const sortedDonors = [...data.donors].sort(sortByDateAsc);
        const rows = sortedDonors.map((item, idx) => [
          idx + 1,
          formatDate(item.date),
          item.name,
          item.nominal
        ]);

        const totalDonor = data.donors.reduce((a,b)=>a+b.nominal,0);
        rows.push(['', '', 'TOTAL PEMASUKAN PROPOSAL/AMPLOP', totalDonor]);

        addToSheet("Donatur", headers, rows);
      }

      // --- 4. PENGELUARAN ---
      if (type === 'expense' || type === 'all_financial' || type === 'accountability') {
        const headers = ['No', 'Tanggal', 'Keperluan', 'Nominal'];
        // SORT
        const sortedExpenses = [...data.expenses].sort(sortByDateAsc);
        const rows = sortedExpenses.map((item, idx) => [
          idx + 1,
          formatDate(item.date),
          item.purpose,
          item.nominal
        ]);

        const totalExpense = data.expenses.reduce((a,b)=>a+b.nominal,0);
        rows.push(['', '', 'TOTAL DANA PENGELUARAN', totalExpense]);

        addToSheet("Pengeluaran", headers, rows);
      }

      // --- 5. REKAPITULASI ---
      if (type === 'all_financial' || type === 'accountability') {
        const totalPrev = data.previousFunds.reduce((a,b)=>a+b.nominal,0);
        const totalWeekly = data.weeklyData.reduce((a,b)=>a+b.netAmount,0);
        const totalDonor = data.donors.reduce((a,b)=>a+b.nominal,0);
        const totalIncome = totalPrev + totalWeekly + totalDonor;
        const totalExpense = data.expenses.reduce((a,b)=>a+b.nominal,0);
        const balance = totalIncome - totalExpense;

        const headers = ['KATEGORI', 'TOTAL NOMINAL'];
        const rows = [
            ['Total Dana Panitia Sebelumnya', totalPrev],
            ['Total Pemasukan Mingguan (Bersih)', totalWeekly],
            ['Total Pemasukan Proposal / Amplop', totalDonor],
            ['TOTAL SEMUA PEMASUKAN', totalIncome],
            ['TOTAL PENGELUARAN', totalExpense],
            ['SISA SALDO SAAT INI (Update: ' + formatDateTime(data.lastUpdated) + ')', balance]
        ];
        addToSheet("Rekapitulasi", headers, rows);
      }

      // Helper for unified file naming
      const getFileName = (reportType: string) => {
        switch (reportType) {
            case 'all_financial': return 'Laporan_PHBI_Rekapitulasi';
            case 'weekly': return 'Laporan_PHBI_Mingguan_Per_RT';
            case 'donor': return 'Laporan_PHBI_Proposal_Amplop';
            case 'expense': return 'Laporan_PHBI_Pengeluaran';
            case 'all_income': return 'Laporan_PHBI_Gabungan_Pemasukan';
            case 'accountability': return 'LAPORAN_PERTANGGUNG_JAWABAN_PHBI';
            default: return `Laporan_PHBI_${reportType}`;
        }
      };

      const fileName = `${getFileName(type)}_${new Date().toISOString().slice(0,10)}.xlsx`;
      XLSX.writeFile(wb, fileName);

  } catch (error: any) {
      console.error("Excel Error:", error);
      Swal.fire({
          icon: 'error',
          title: 'Gagal Download Excel',
          text: 'Terjadi kesalahan saat membuat file excel. Pastikan browser mendukung fitur ini.',
          footer: error.message
      });
  }
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppData, PreviousFund, WeeklyData, DonorData, ExpenseData } from '../types';
import Swal from 'sweetalert2';
import { supabase } from '../lib/supabaseClient';

interface DataContextType {
  publishedData: AppData;
  stagedData: AppData; // Admin working copy
  isLoggedIn: boolean;
  currentUser: string | null;
  login: (username: string) => void;
  logout: () => void;
  verifyUser: (username: string, password: string) => Promise<boolean>; 
  addAdminUser: (newUsername: string, newPassword: string, masterPass: string) => Promise<boolean>;
  getAdminUsers: () => Promise<any[]>;
  deleteAdminUser: (id: string, masterPass: string) => Promise<boolean>;

  // CRUD Actions (Effect Staged Data)
  addPreviousFund: (data: Omit<PreviousFund, 'id'>) => void;
  updatePreviousFund: (id: string, data: Partial<PreviousFund>) => void; 
  deletePreviousFund: (id: string) => void;

  addWeeklyData: (data: Omit<WeeklyData, 'id'>) => void;
  updateWeeklyData: (id: string, data: Partial<WeeklyData>) => void; 
  deleteWeeklyData: (id: string) => void;

  addDonor: (data: Omit<DonorData, 'id'>) => void;
  updateDonor: (id: string, data: Partial<DonorData>) => void; 
  deleteDonor: (id: string) => void;

  addExpense: (data: Omit<ExpenseData, 'id'>) => void;
  updateExpense: (id: string, data: Partial<ExpenseData>) => void; 
  deleteExpense: (id: string) => void;

  // DIRECT DB ACTIONS (Untuk Edit/Hapus data yang sudah terpublish)
  updatePublishedItem: (table: string, id: string, data: any) => Promise<boolean>;
  deletePublishedItem: (table: string, id: string) => Promise<boolean>;

  // System Actions
  publishData: (updateDate: string) => void;
  resetData: (type: 'all' | 'previous' | 'weekly' | 'donor' | 'expense') => void;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

const initialData: AppData = {
  lastUpdated: new Date().toISOString(),
  previousFunds: [],
  weeklyData: [],
  donors: [],
  expenses: [],
};

// --- PASSWORD ADMIN PUSAT (KUNCI UTAMA) ---
const MASTER_ADMIN_PASSWORD = "ALISHLAH2026"; 
const SESSION_KEY = 'phbi_admin_session'; // Key untuk localStorage
const IDLE_TIMEOUT_MS = 5 * 60 * 1000; // 5 Menit Auto Logout

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [publishedData, setPublishedData] = useState<AppData>(initialData);
  const [stagedData, setStagedData] = useState<AppData>(initialData);

  const [isLoggedIn, setIsLoggedIn] = useState<boolean>(() => {
    const session = localStorage.getItem(SESSION_KEY);
    return !!session; 
  });

  const [currentUser, setCurrentUser] = useState<string | null>(() => {
    const session = localStorage.getItem(SESSION_KEY);
    return session ? JSON.parse(session).username : null;
  });

  const fetchSupabaseData = async (notifyError = false) => {
    if (!notifyError && !isLoggedIn) {
        Swal.fire({
            title: 'بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ',
            text: 'Sedang proses ambil data base....',
            allowOutsideClick: false,
            showConfirmButton: false,
            didOpen: () => {
                Swal.showLoading();
            }
        });
    }

    try {
      const { data: prevFunds, error: prevError } = await supabase.from('DanaSebelumnya_data').select('*');
      if (prevError) throw prevError;
      const mappedPrev = prevFunds?.map((item: any) => ({ ...item, createdBy: item.created_by, editedBy: item.edited_by })) || [];

      const { data: weekly, error: weeklyError } = await supabase.from('Mingguan_data').select('*');
      if (weeklyError) throw weeklyError;
      const mappedWeekly = weekly?.map((item: any) => ({
        id: item.id,
        date: item.date,
        week: item.week,
        rt: item.rt,
        grossAmount: item.gross_amount,
        consumptionCut: item.consumption_cut,
        commissionCut: item.commission_cut,
        netAmount: item.net_amount,
        createdBy: item.created_by,
        editedBy: item.edited_by
      })) || [];

      const { data: donors, error: donorError } = await supabase.from('Donatur_data').select('*');
      if (donorError) throw donorError;
      const mappedDonors = donors?.map((item: any) => ({ ...item, createdBy: item.created_by, editedBy: item.edited_by })) || [];

      const { data: expenses, error: expError } = await supabase.from('Pengeluaran_data').select('*');
      if (expError) throw expError;
      const mappedExpenses = expenses?.map((item: any) => ({ ...item, createdBy: item.created_by, editedBy: item.edited_by })) || [];

      const { data: meta } = await supabase.from('app_meta').select('*').limit(1).single();

      setPublishedData({
        lastUpdated: meta?.last_updated || new Date().toISOString(),
        previousFunds: mappedPrev,
        weeklyData: mappedWeekly,
        donors: mappedDonors,
        expenses: mappedExpenses
      });

      if (!notifyError) { Swal.close(); }
    } catch (error: any) {
      console.error("Error fetching data:", error);
      if (notifyError || isLoggedIn) {
          Swal.fire({ icon: 'error', title: 'Gagal Mengambil Data', text: 'Terjadi kendala saat sinkronisasi data.' });
      } else { Swal.close(); }
    }
  };

  const login = (username: string) => {
    setIsLoggedIn(true);
    setCurrentUser(username);
    localStorage.setItem(SESSION_KEY, JSON.stringify({ username }));
    setTimeout(() => fetchSupabaseData(true), 500);
  };

  const logout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    localStorage.removeItem(SESSION_KEY);
  };

  useEffect(() => {
    fetchSupabaseData(false);
    const storedStaged = localStorage.getItem('phbi_staged_data');
    if (storedStaged) setStagedData(JSON.parse(storedStaged));
  }, []);

  useEffect(() => {
    localStorage.setItem('phbi_staged_data', JSON.stringify(stagedData));
  }, [stagedData]);

  // LOGIKA AUTO-LOGOUT (IDLE TIMEOUT) YANG DIPERBAIKI
  useEffect(() => {
    let idleTimer: ReturnType<typeof setTimeout>;

    const handleIdleLogout = () => {
      if (isLoggedIn) {
        logout();
        Swal.fire({ 
          icon: 'warning', 
          title: 'Sesi Berakhir', 
          text: 'Anda telah logout otomatis karena tidak ada aktivitas selama 5 menit demi keamanan.', 
          timer: 5000, 
          timerProgressBar: true, 
          showConfirmButton: true,
          confirmButtonText: 'Tutup',
          allowOutsideClick: false 
        });
      }
    };

    const resetTimer = () => {
      if (!isLoggedIn) return;
      if (idleTimer) clearTimeout(idleTimer);
      idleTimer = setTimeout(handleIdleLogout, IDLE_TIMEOUT_MS);
    };

    if (isLoggedIn) {
      // Mulai timer saat pertama kali login
      resetTimer();

      // Daftar event yang dianggap sebagai aktivitas
      const events = [
        'mousedown', 'mousemove', 'keypress', 
        'scroll', 'touchstart', 'click', 
        'keydown', 'wheel'
      ];

      // Tambahkan listener ke level document agar lebih menyeluruh
      events.forEach(event => {
        document.addEventListener(event, resetTimer, { passive: true });
      });

      // Bersihkan listener dan timer saat unmount atau logout
      return () => {
        if (idleTimer) clearTimeout(idleTimer);
        events.forEach(event => {
          document.removeEventListener(event, resetTimer);
        });
      };
    }
  }, [isLoggedIn]);

  const verifyUser = async (u: string, p: string): Promise<boolean> => {
    try {
        const { data, error } = await supabase.from('admin_users').select('id, username').eq('username', u).eq('password', p).limit(1);
        if (error) return false;
        return data && data.length > 0;
    } catch (err) { return false; }
  };

  const addAdminUser = async (newUsername: string, newPassword: string, masterPass: string): Promise<boolean> => {
      if (masterPass !== MASTER_ADMIN_PASSWORD) {
          Swal.fire('Kode ID Server Gagal', 'Kode ID Server tidak valid!', 'error');
          return false;
      }
      try {
          const { data: existing } = await supabase.from('admin_users').select('id').eq('username', newUsername).single();
          if (existing) { Swal.fire('Gagal', 'Username tersebut sudah digunakan.', 'warning'); return false; }
          const { error } = await supabase.from('admin_users').insert({ username: newUsername, password: newPassword });
          if (error) throw error;
          return true;
      } catch (error: any) { Swal.fire('Error', error.message, 'error'); return false; }
  };

  const getAdminUsers = async () => {
      const { data, error } = await supabase.from('admin_users').select('id, username, created_at').order('created_at', { ascending: false });
      if (error) return [];
      return data || [];
  };

  const deleteAdminUser = async (id: string, masterPass: string): Promise<boolean> => {
      if (masterPass !== MASTER_ADMIN_PASSWORD) {
          Swal.fire('Kode ID Server Gagal', 'Kode ID Server tidak valid!', 'error');
          return false;
      }
